using namespace std;

int N;
vector<long> A(100005);
vector<long> ans(100005);
vector<pair<long, int>> P(1000005);

int main() {
  cin >> N;
  rep(i, N) {
    cin >> A.at(i);
    P.at(i) = make_pair(A.at(i), i);
  }
  sort(P.rbegin(), P.rend());
  pair<long, int> pfirst = P.at(0);
  int num = 1;
  int pos = pfirst.second;
  for (int i=1; i<N; i++) {
    pair<long, int> psecond = P.at(i);
    if (pfirst.first > psecond.first) {
      ans.at(pos) += (pfirst.first - psecond.first)*num;
      pfirst.first = psecond.first;
    }
    if (pos > psecond.second) {
      pos = psecond.second;
    }
    num++;
  }
  ans.at(0) += num;
  rep(i, N) {
    cout << ans.at(i) << endl;
  }
}

