typedef long long ll;
typedef pair<int,int> PII;
typedef pair<ll,ll> PLL;
typedef vector<int> VI;
typedef vector<ll> VL;
typedef vector<string> VS;
typedef vector<VI> VVI;
typedef vector<VL> VVL;
typedef vector<PII> VPI;
typedef vector<PLL> VPL;
#define rep(i,n) for(ll i=0;i<(n);i++)
#define all(a) (a).begin(),(a).end()
#define pf push_front
#define pb push_back
#define mp make_pair
#define mt make_tuple
#define ub upper_bound
#define lb lower_bound

int main(){
  int N;
  cin>>N;
  VI A(N);
  rep(i,N) cin>>A[i];
  int size=1;
  while(N>=size) size*=2;
  VI B(N);
  rep(i,N) B[i]=A[i];
  sort(all(B));
  map<int,int> M;
  int tmp=2;
  rep(i,N) if(M.find(B[i])==M.end()) M[B[i]]=tmp++;
  VI BIT(size);
  VI ans(N);
  rep(i,N){
    int tmp=M[A[N-1-i]]-1;
    int sum=0;
    while(tmp){
      sum+=BIT[tmp];
      tmp-=tmp&-tmp;
    }
    ans[N-1-i]=i-sum;
    tmp=M[A[N-1-i]];
    while(tmp<size){
      BIT[tmp]++;
      tmp+=tmp&-tmp;
    }
  }
  int max=A[0]-1;
  rep(i,N){
    if(max<A[i]){
      ans[i]+=A[i]-max;
      max=A[i];
    }else ans[i]=0;
  }
  rep(i,N) cout<<ans[i]<<endl;
}

