typedef pair<int,int> P;
P pairs[100010];
int answers[100010];
int main() {
  memset(answers,0,sizeof(answers));
  scanf("%d", &N);
  for(int i=0;i<N;++i) {
    scanf("%d", &pairs[i].first);
    pairs[i].second = i;
  }
  sort(pairs, pairs+N, greater<P>());
  pairs[N].first=0;
  pairs[N].second=N;

  int minIndex=N;
  for(int i=0;i<N;++i) {
    minIndex = min(minIndex, pairs[i].second);
    if(pairs[i+1].first != pairs[i].first || i==N-1) {
      answers[minIndex] += (i+1)*(pairs[i].first-pairs[i+1].first);
    }
  }

  for(int i=0;i<N;++i) {
    printf("%d\n", answers[i]);
  }

  return 0;
}

