class SegmentTree {
public:
    unsigned int n;
    vector<pair<int, int>> dat; // (num, idx)

    SegmentTree(vector<int> v) {
        this->n = 1;
        while (n < v.size()) { n *= 2; }   // sz以上の最小の2冪
        dat.resize(2 * n - 1, make_pair(-1, INT_MAX));

        // 最下段
        for (int i = 0; i < v.size(); ++i) {
            dat[i + n - 1] = make_pair(v[i], i);  // 最下段は配列の(n - 1)番目からはじまる
        }
        // 木の全体を更新
        for (int i = n - 2; i >= 0; --i) {
            dat[i] = comparison(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }

    pair<int, int> comparison(pair<int, int> a, pair<int, int> b) {
        if (a.first == b.first) {
            // idxが小さい方
            if (a.second < b.second) {
                return a;
            }
            else {
                return b;
            }
        }
        if (a.first > b.first) {
            return a;
        }
        else {
            return b;
        }
    }

    // 元の配列でのidxをxにし、木を更新
    void update(int idx, int x) {
        int temp = idx;
        idx += n - 1;   // 木での対象のインデックス
        dat[idx] = make_pair(x, temp);
        while (idx > 0) {
            idx = (idx - 1) / 2;                                  // 親のインデックス
            dat[idx] = comparison(dat[idx * 2 + 1], dat[idx * 2 + 2]);   // 左の子と右の子
        }
    }

    // 区間[a, b)の最小値
    pair<int, int> query(int a, int b) {
        return this->query(a, b, 0, 0, n);
    }

private:

    // [a, b)の最小値をノードk（区間[l, r]）から検索
    pair<int, int> query(int a, int b, int k, int l, int r) {
        assert(a < b && l < r);
        // 範囲外
        if (r <= a || b <= l) {
            return make_pair(INT_MIN, INT_MIN);
        }
        // 完全に含む
        if (a <= l && r <= b) {
            return this->dat[k];
        }
            // 一部含む
        else {
            auto vl = query(a, b, k * 2 + 1, l, (l + r) / 2);    // 左の子
            auto vr = query(a, b, k * 2 + 2, (l + r) / 2, r);    // 右の子
            return comparison(vl, vr);
        }
    }
};

class SegmentTree2 {
public:
    unsigned int n;
    vector<pair<int, int>> dat; // (num, idx)

    SegmentTree2(vector<int> v) {
        this->n = 1;
        while (n < v.size()) { n *= 2; }   // sz以上の最小の2冪
        dat.resize(2 * n - 1, make_pair(-1, -1));

        // 最下段
        for (int i = 0; i < v.size(); ++i) {
            dat[i + n - 1] = make_pair(v[i], i);  // 最下段は配列の(n - 1)番目からはじまる
        }
        // 木の全体を更新
        for (int i = n - 2; i >= 0; --i) {
            dat[i] = comparison(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }

    pair<int, int> comparison(pair<int, int> a, pair<int, int> b) {
        if (a.first == b.first) {
            // idxが大きい方
            if (a.second > b.second) {
                return a;
            }
            else {
                return b;
            }
        }
        if (a.first > b.first) {
            return a;
        }
        else {
            return b;
        }
    }

    // 元の配列でのidxをxにし、木を更新
    void update(int idx, int x) {
        int temp = idx;
        idx += n - 1;   // 木での対象のインデックス
        dat[idx] = make_pair(x, temp);
        while (idx > 0) {
            idx = (idx - 1) / 2;                                  // 親のインデックス
            dat[idx] = comparison(dat[idx * 2 + 1], dat[idx * 2 + 2]);   // 左の子と右の子
        }
    }

    // 区間[a, b)の最小値
    pair<int, int> query(int a, int b) {
        return this->query(a, b, 0, 0, n);
    }

private:

    // [a, b)の最小値をノードk（区間[l, r]）から検索
    pair<int, int> query(int a, int b, int k, int l, int r) {
        assert(a < b && l < r);
        // 範囲外
        if (r <= a || b <= l) {
            return make_pair(-1, -1);
        }
        // 完全に含む
        if (a <= l && r <= b) {
            return this->dat[k];
        }
            // 一部含む
        else {
            auto vl = query(a, b, k * 2 + 1, l, (l + r) / 2);    // 左の子
            auto vr = query(a, b, k * 2 + 2, (l + r) / 2, r);    // 右の子
            return comparison(vl, vr);
        }
    }
};


void solve(long long N, vector<int> A){
    vector<LL> ans(N, 0);

    SegmentTree st1(A);
    SegmentTree2 st2(A);

    LL total = SUM(A);
    FOR(i, 0, total) {

        auto insert_num_idx = st1.query(0, N);
        auto remove_num_idx = st2.query(0, N);


        int insert_idx = insert_num_idx.second;
        int remove_idx = remove_num_idx.second;
        ans.at(insert_idx)++;
        st1.update(remove_idx, A.at(remove_idx) - 1);
        st2.update(remove_idx, A.at(remove_idx) - 1);
        A.at(remove_idx)--;
    }

    FOE(x, ans) {
        print(x);
    }
}

