    // for (Idx i : vec) cout << i.val << " " << i.idx << "\n";

    vector <int> ans(n, 0);

    int pc = 0;
    int cur = vec[0].val;
    while (pc <= n) {
        if (vec[pc].val == cur) {
            pc++;
            continue;
        }

        ans[vec[pc - 1].idx] = (cur - vec[pc].val) * pc;
        cur = vec[pc].val;
        pc++;
    }

    for (int ret : ans) cout << ret << "\n";
    return 0;
}

