void sol() {
	rep(i, 0, N) _cnt[A[i]]++;
	ll c = 0;
	for (auto i = _cnt.rbegin(); i != _cnt.rend(); ++i) {
		c += i->second;
		cnt[i->first] = c;
	}
	rrep(i, N - 1, 0) idx[A[i]] = i;
	for (auto p : cnt) v.push_back(p.first);
	reverse(v.begin(), v.end());

