template<class T> T gcd(T a, T b) { return b ? gcd(b, a % b) : a; }
template<class T> T lcm(T a, T b) { return a / gcd(a, b) * b; }
ll mod_pow(ll a, ll n, ll mod) {
	ll ret = 1;
	ll p = a % mod;
	while (n) {
		if (n & 1) ret = ret * p % mod;
		p = p * p % mod;
		n >>= 1;
	}
	return ret;
}
template<class T> T extgcd(T a, T b, T& x, T& y) { for (T u = y = 1, v = x = 0; a;) { T q = b / a; swap(x -= q * u, u); swap(y -= q * v, v); swap(b -= q * a, a); } return b; }
template<class T> T mod_inv(T a, T m) { T x, y; extgcd(a, m, x, y); return (m + x % m) % m; }

int main() {
	int n; reader(n);
	vector<ll> a(n);
	FOR(i, n) reader(a[i]);

	map<ll, vector<int>> mp;
	mp[0].push_back(n);
	FOR(i, n) mp[a[i]].push_back(i);
	vector < pair<ll, vector<int>>> mp2(mp.rbegin(),mp.rend());

	vector<ll> ans(n);
	int min_val = n;
	ll cnt = 0;
	for (auto it = mp2.begin(); it != mp2.end(); ++it) {
		auto it2 = it; ++it2;
		if (it2 == mp2.end()) break;
		ll diff = it->first - it2->first;
		cnt += sz(it->second);
		int cand = it->second[0];
		min_val = min(min_val, cand);
		ans[min_val] += cnt * diff;
	}
	for (auto v : ans) writerLn(v);

	return 0;
}

