vector<pair<int,int>> maximumStoneNumber(const vector<int> &a){
	set<int> s;
	map<int,int> m;
	rep(i,a.size()){
		//show(a[i])
		if(not s.count(a[i])){
			m[a[i]] = i;
			s.emplace(a[i]);
		}
	}

	vector<pair<int, int>> res;
	for(auto i = m.rbegin(); i != m.rend(); i++){
		res.emplace_back(*i);
		//cout << (*i).first << ' ' << (*i).second << endl;
	}
	return res;
}

void compress(vector<int> &v) {
	sort(v.begin(), v.end());
	v.erase(unique(v.begin(),v.end()),v.end());
}

int lb(vector<int> v, int num){
	return lower_bound(all(v), num) - v.begin();
}

const int MAX_N = 100005;

//[1, n]
int bit[MAX_N + 1] = {0};

int sum(int i){
	int s = 0;
	i++;
	while(i > 0){
		s += bit[i];
		i -= i & -i;
	}
	return s;
}

void add(int i, int x){
	i++;
	while(i <= MAX_N){
		bit[i] += x;
		//bit[i] = max(bit[i], x);
		i += i & - i;
	}
}

int main(){
	int n;
	cin >> n;

	vector<int> a(n), press(n);
	rep(i,n){
		cin >> a[i];
		press[i] = a[i];
	}
	compress(press);

	vector<pair<int, int>> p = maximumStoneNumber(a); //石の個数(降順)、添字
	vector<long long> ans;
	for(int i = n - 1, j = 0; i >= 0; i--){
		add(lb(press, a[i]), 1);
		if(i == p[j].second){
			//cout << "in- " <<  i <<' ' << p[j].first << endl;
			int com_p = lb(press,a[i]);
			if(com_p == 0){
				int num = sum(100001);
				ans.emplace_back(num * p[j].first);
			}else{
				int num = sum(100001) - sum(lb(press,a[i]) - 1);
				//show(num)
					//show(p[j].first - p[j + 1].first)
				ans.emplace_back(num * (p[j].first - p[j + 1].first));
			}
			j++;
		}else{
			ans.emplace_back(0);
		}
	}

	for(auto i = ans.rbegin(); i != ans.rend(); i++){
		cout << *i << endl;
	}

}

