int main() {
  scanf("%lld", &n);
  priority_queue<P> pq;
  for (ll i = 0; i < n; i++) scanf("%lld", &a[i]), pq.push(P(a[i], i));
  pq.push(P(0, n));
  ll counter = 1, before = pq.top().second; pq.pop();
  while (!pq.empty() && a[before] == pq.top().first) before = pq.top().second, pq.pop(), counter++;
  while (!pq.empty()) {
    P p = pq.top(); pq.pop();
    ll temp = 1;
    while (!pq.empty() && pq.top().first == p.first) {
      p = pq.top(); pq.pop();
      temp++;
    }
    ans[before] = counter * (a[before] - p.first);
    counter += temp;
    before = p.second;
  }
  for (ll i = 0; i < n; i++) printf("%lld\n", ans[i]);
}

