BIT<ll> bit1;
BIT<ll> bit2;

struct K {
  ll v;
  int idx;
};
bool operator<(const K& a, const K& b) {
  if(a.v != b.v) return a.v < b.v;
  return a.idx > b.idx;
}
priority_queue<K> q;

