  REP(i, n) {
    q.push((K){vs[i], i});
  }
  bit1.init(n);
  bit2.init(n);
  while(!q.empty()) {
    K cur = q.top(); q.pop();
    ll sum = bit1.sum(n) - bit1.sum(cur.idx+1);
    ll cnt = bit2.sum(n) - bit2.sum(cur.idx+1);
    cs[cur.idx] = sum - cnt * cur.v;
    bit1.add(cur.idx, cur.v);
    bit2.add(cur.idx, 1);
  }

  ll last = -1;
  ll rest = bit1.sum(n);
  REP(i, n) {
    if(vs[i] <= last) {
      puts("0");
      continue;
    }
    ll cur = rest - cs[i];
    printf("%lld\n", cur);
    rest -= cur;
    last = vs[i];
  }

  return 0;
}

