int main() {

    int n;
    vector<int> a;
    vector<int> max_left(n);
    vector<int64_t> result(n);
    map<int, int> right;
    int index;
    int current;
    int64_t n_current;

    scanf("%d", &n);
    a.resize(n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);

        max_left[i] = a[i];
        if (i > 0) {
            max_left[i] = max(max_left[i], max_left[i - 1]);
        }
    }

    index = max_element(a.begin(), a.end()) - a.begin();
    current = a[index];
    n_current = count(a.begin(), a.end(), a[index]);
    for (int i = index + 1; i < n; i++) {
        if (a[i] < current) {
            right[a[i]]++;
        }
    }

    while (index > 0) {
        int next = max_left[index - 1];

        while (!right.empty()) {
            map<int, int>::iterator it = right.end();

            --it;
            if (it->first < next) {
                break;
            }

            result[index] += n_current * (current - it->first);

            current = it->first;
            n_current += it->second;

            right.erase(it);
        }

        result[index] += n_current * (current - next);

        current = next;
        while (index > 0 && max_left[index - 1] == current) {
            index--;
            if (a[index] == current) {
                n_current++;
            }
            else {
                right[a[index]]++;
            }
        }
    }

    result[0] += n_current * current;
    for (auto it : right) {
        result[0] += it.second * current;
    }

    for (int i = 0; i < n; i++) {
        printf("%lld\n", result[i]);
    }

    return 0;
}

