int binary(vector<int> &k,int left,int right,int key){
  if(k[0]>=key)return 0;
  int mid=(left+right)/2;
  if(left==mid){
    if(k[left]<key)return right;
    else return mid;
  }
  if(k[mid-1]<key)return binary(k,mid,right,key);
  else return binary(k,left,mid,key);
}
