template <class Type>
class Bit {
    public:

    Bit(int n) : size(n + 1) {
        bit = (Type *)calloc(size, sizeof(Type));
    }

    ~Bit() {
        free(bit);
    }

    void add(int x, Type value) {
        for (x++; x < size; x += x & -x) bit[x] += value;
    }

    //[0,x]
    Type sum(int x) {
        Type value = 0;

        for (x++; x > 0; x -= x & -x) value += bit[x];

        return value;
    }

    //[x,y]
    Type get(int x, int y) {
        return sum(y) - sum(x - 1);
    }

    private:

    int size;
    Type *bit;
};

