  cin >> n;
  for(int i = 0; i < n; ++i) {
    cin >> a[i];
    b[i] = a[i];
    mx[i] = i;
    if(i > 0 && a[mx[i-1]] >= a[i])
      mx[i] = mx[i-1];
  }
  sort(b, b+n, greater<ll>());

  int cnt = 0;
  int cur = n-1;
  ll sum = 0;
  ll prev = 0;

  while(cur >= 0) {
    int idx = mx[cur];
    ll v = a[idx];

    if(idx > 0) {
      int lidx = mx[idx-1];
      v = a[lidx];
      while(cnt < n && b[cnt] >= v) sum += b[cnt++];
      ans[idx+1] = (sum-cnt*v)-prev;
      prev += ans[idx+1];
      cur = lidx;
    } else {
      while(cnt < n && b[cnt] >= v) sum += b[cnt++];
      ans[idx+1] = sum-prev;
      cur=-1;
    }
  }

  for(int i = 1; i <= n; ++i)
    cout << ans[i] << "\n";
}

