int findMax(int N, int* a) {

    int res = N - 1;
    int tmp = a[res];
    for(int i=N-2;i>=0;i--) {
        if(a[i]>=tmp) {
            tmp = a[i];
            res = i;
        }
    }

    return res;
}

int calcUpSum(int N, int* a, int div) {
    int res = 0;
    for(int i=div+1;i<N;i++) {
        res += a[i];
    }

    return res;
}

void zeroClrUp(int N, int* a, int div) {
    for(int i=div+1;i<N;i++) {
        a[i] = 0;
    }
}

int main() {

    int N;
    int* a;

    scanf("%d", &N);
    a = (int*)malloc(sizeof(int)*N);
    for(int i=0;i<N;i++) {
        scanf("%d", &a[i]);
    }

    int* res;
    res = (int*)malloc(sizeof(int)*N);
    for(int i=0;i<N;i++) {
        res[i] = 0;
    }

    int x;
    while(1) {
        x=findMax(N, a);
        if(a[x] == 0) break;
        res[x]=res[x] + calcUpSum(N, a, x) + 1;
        a[x] = a[x] - 1;
        zeroClrUp(N, a, x);
    }

    for(int i=0;i<N;i++) {
        printf("%d\n", res[i]);
    }


    return 0;
}

