void solve() {
	for (int i = SZ(b); i >= 1; --i) sum[i] = sum[i + 1] + SZ(g[i]);
	int idx = n + 1;
	for (int i = SZ(b); i >= 1; --i) {
		if (i == SZ(b)) idx = g[i][0];
