const int N = 1e5 + 123;
int n, a[N], p[N], b[N];
ll f[2][N], t, cur, ans[N];

void upd(int c, int x, int y) {
	for (; x <= n; x |= (x + 1))
		f[c][x] += y;
}

ll get(int c, int x) {
	ll res = 0;
	for (; x >= 0; x = (x & (x + 1)) - 1)
		res += f[c][x];
	return res;
}

void solve(int pos, int mx) {
	if (pos == 1) {
		ans[pos] = t - cur;
		return;
	}
	int to = p[pos - 1];
	for (int i = pos; i > to; i--)
		upd(0, b[i], 1), upd(1, b[i], a[i]);
	ll num = get(0, mx) - get(0, b[to]);
	ans[pos] = (get(1, mx) - get(1, b[to])) - a[to] * num;
	upd(0, b[to], num);
	upd(1, b[to], num * a[to]);
	cur += ans[pos];
	solve(to, b[to]);
}

