		v.pb(a[i]);
		p[i] = p[i - 1];
		if (a[i] > a[p[i]])
			p[i] = i;
	}
	sort(all(v));
	v.erase(unique(all(v)), v.end());
	for (int i = 1; i <= n; i++) b[i] = lower_bound(all(v), a[i]) - v.begin() + 1;
	for (int i = n; i > p[n]; i--)
		upd(0, b[i], 1), upd(1, b[i], a[i]);
	solve(p[n], b[p[n]]);
	for (int i = 1; i <= n; i++) cout << ans[i] << '\n';
}

