typedef long long int ll;
typedef pair<int,int> ii;
const int N = 1e5+1;
int i,n,a[N],sz[N];
ll ans[N];
priority_queue<ii>pq;
int main()
{
	scanf("%d",&n);
	for(i=1;i<=n;i++)
	{
		scanf("%d",&a[i]);
		pq.push(ii(a[i],i));
		sz[i] = 1;
	}
	while(pq.size()>1)
	{
		int t1 = pq.top().first;
		int i1 = pq.top().second;
		pq.pop();
		int t2 = pq.top().first;
		int i2 = pq.top().second;
		pq.pop();
		ans[i1] += 1ll * sz[i1] * (t1 - t2);
		pq.push(ii(t2,min(i1,i2)));
		sz[min(i1,i2)] += sz[max(i1,i2)]; 
	}
	ans[1] += 1ll * n * pq.top().first;
	for(i=1;i<=n;i++)	printf("%lld\n",ans[i]);
}

#include <bits/stdc++.h>
#define For(i, a, b) for(int (i)=(a); (i)<(b); ++(i))
#define rFor(i, a, b) for(int (i)=(a)-1; (i)>=(b); --(i))
#define rep(i, n) For((i), 0, (n))
#define rrep(i, n) rFor((i), (n), 0)
#define fi first
#define se second
using namespace std;
typedef long long lint;
typedef pair<int, int> pii;
typedef pair<int, lint> pil;

typedef struct SegTree{
    int n = 1;
    vector<pil> node;

    SegTree(int n_){
        while(n < n_) n *= 2;
        node.resize(2*n-1, pil(0, 0));
    }

    void update(int i, int x){
        i += n-1;
        node[i] = pil(i-n+1, x);
        while(i){
            i = (i-1) / 2;
            if(node[2*i+1].se >= node[2*i+2].se) node[i] = node[2*i+1];
            else node[i] = node[2*i+2];
        }
    }

    pil query(int a, int b, int i, int l, int r){
        if(r<=a || b<=l) return pil(0, 0);
        if(a<=l && r<=b) return node[i];
        pil pl = query(a, b, 2*i+1, l, (l+r)/2);
        pil pr = query(a, b, 2*i+2, (l+r)/2, r);
        if(pl.se >= pr.se) return pl;
        else return pr;
    }
}ST;

int main(){
    int n;
    scanf("%d", &n);
    ST st(n+1);
    map<lint, lint> mp;
    rep(i, n){
        lint a;
        scanf("%lld", &a);
        st.update(i+1, a);
        ++mp[a];
    }
    lint ans[n+1];
    rep(i, n+1) ans[i] = 0;
    pil p = st.query(0, n+1, 0, 0, st.n);
    pil np = st.query(0, p.fi, 0, 0, st.n);
    while(p.fi){
        ans[p.fi] = (lint)(p.se - np.se) * mp[p.se];
        mp[np.se] += mp[p.se];
        mp.erase(p.se);
        p = np;
        np = st.query(0, p.fi, 0, 0, st.n);
    }
    for(auto itr=mp.begin(); itr!=mp.end(); ++itr) ans[1] += itr->fi * itr->se;
    rep(i, n) printf("%lld\n", ans[i+1]);
}

