      E[i]=1; L[i]=ls; ls=A[i];
    }
  }
  treap_ptr t=0;
  FORD(i,n-1,0) {
    t=treap::insert_key(t,A[i]);
    if(E[i]) {
      auto p = treap::split_key(t,L[i]+1);
      lli r = treap::get_size(p.y());
      lli r2 = treap::get_sum(p.y());
      t=treap::merge(p.x(),new treap(L[i], r));
      ANS[i]=r2-r*L[i];
      S-=ANS[i];
    }
  }
  ANS[0]+=S;
  FOR(i,n) cout << ANS[i] << '\n';
  cout << flush;
  return 0;
}

