int main() {
    int N;
    cin >> N;
    vector<i64> A(N), ans(N, 0);
    for(i64 &x : A) cin >> x;
    deque<int> deq;
    for(int i = N - 1; i >= 0; i--) {
        while(!deq.empty() && A[i] > A[deq.front()]) {
            deq.pop_front();
        }
        deq.push_front(i);
    }
    priority_queue<i64> q;
    int cur, prev = N;
    // prevと同じ高さの山の数
    int m = 0;
    while(!deq.empty()) {
        // 取る必要のある石の数
        i64 S = 0;

        cur = deq.back(); deq.pop_back();
        // 右側の山を、取る山キューに追加
        if(prev >= 0) {
            for(int i = cur; i < prev; i++) {
                q.push(A[i]);
            }
        }
        if(prev < N) {
            ans[prev] += (A[prev] - A[cur]) * m;
        }
        while(q.size() && q.top() >= A[cur]) {
            S += q.top() - A[cur];
            q.pop();
            m++;
        }
        if(prev < N) ans[prev] += S;
        prev = cur;
    }
    ans[prev] = accumulate(WHOLE(A), - accumulate(WHOLE(ans), 0));
    for(i64 x : ans) cout << x << endl;
    return 0;
}

