int N;
ll a[100005];
ll v[100005];


int main(){
  cin >> N;

  map<ll,pair<ll,ll> > memo;
  rep(i,N){
    cin >> a[i];
    if(memo.count(a[i]) == 0){
      memo[a[i]] = make_pair(i,1);
    }else{
      pair<ll,ll> x = memo[a[i]];
      x.second++;
      memo[a[i]] = x;
    }
  }

  vector<ll> rev;
  FOR(it,memo){
    rev.push_back(it->first);
  }
  reverse(ALLOF(rev));

  rep(i,rev.size()){
    ll x = rev[i];
    pair<ll,ll> z = memo[rev[i]];
    ll mn = z.first;
    ll y = z.second;
    if(i+1<rev.size()){
      x = rev[i] - rev[i+1];

      pair<ll,ll> pr = memo[rev[i+1]];
      pr.first = min(pr.first, mn);
      pr.second += y;
      memo[rev[i+1]] = pr;
    }
    v[mn] = x*y;
  }
  rep(i,N){
    cout << v[i] << endl;
  }

  return 0;
}

