}

int64 rec(int64 L, map<int64,int>& D, map<int64,int64>& next_){
    if(D[next_[L]] == 0) return 0;
    int64 res = rec(next_[L], D, next_);
    int64 tmp = D[next_[L]];
    D[L] += D[next_[L]];
    D[next_[L]] = 0;
    return res + tmp * (next_[L] - L);
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    vector<int64> A(N+1);
    REP(i,N) cin >> A[i+1];//番兵として0を入れる
    N++;
    map<int64,int> D;
    for(auto a:A){
        D[a]++;
    }

    auto B=A;
    sort(ALL(B));
    B.erase(unique(ALL(B)), B.end());
    map<int64,int64> next_;
    REP(i,B.size()-1){
        next_[B[i]] = B[i+1];
    }
    next_[B.back()] = -1;

    vector<int64> ans(N);
    int max_idx = 0;
    REP(i,N){
        if(A[i] > A[max_idx]){
            max_idx = i;
        }
    }
    while(max_idx > 0){
        int L_idx = find_max_idx(max_idx, A);
        int64 L = A[L_idx];
        ans[max_idx] = rec(L, D, next_);
        max_idx = L_idx;
    }   

    for(int i=1; i<N; i++){
        cout << ans[i] << bn;
    }
}

