const int dx[] = {1, 0, -1, 0}, dy[] = {0, -1, 0, 1};
int N;
vector<ll> result;
vector<pii> stones;

int find_tar(int pos){
  int cur = -stones[pos].second;
  for (int i = pos + 1; i < N; i++){
    int tmp = -stones[i].second;
    if (tmp < cur){
      return i;
    }
  }
  return -1;
}
ll rest;
int main() {
  cin >> N;
  result.resize(N);
  stones.resize(N);
  for (int i = 0; i < N; i++){
    int x;
    cin >> x;
    stones[i] = mp(x, -i);
    rest += x;
  }
  sort(stones.rbegin(), stones.rend());
  ll pos,tar;
  pos = tar = 0;
  ll pos_cnt,tar_cnt;
  ll pos_val;
  while (true){
    tar = find_tar(pos);
    if (tar == -1)break;
    pos_cnt = stones[pos].first;
    tar_cnt = stones[tar].first;

    pos_val = -stones[pos].second;
    ll sum = 0;
    sum += pos * (pos_cnt - tar_cnt);
    sum += (pos_cnt - tar_cnt) * (tar - pos);
    result[pos_val] = sum;
    rest -= sum;
    pos = tar;
  }
  pos_val = -stones[pos].second;
  result[pos_val] += rest;
  for(int i = 0; i < N; i++){
    cout << result[i] << endl;
  }
  return 0;
}

