using namespace std;
ll ini[100005];
map<ll, ll> hsh;
set<ll> help;
ll fin[100005];
ll bit1[100005];
ll bit2[100005];
ll freq[100005];
void update (ll *a, ll i, ll v) {
	if (i > 100000) return;
	a[i] += v;
	update(a, i + (i & (-i)), v);
}
ll query (ll *a, ll i) {
	return ((i == 0) ? 0 : a[i] + query(a, i - (i & (-i))));
}
int main () {
	ll a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q;
	scanf("%lld", &a);
	for (i = 1; i <= a; i++) {
		scanf("%lld", &ini[i]);
		help.insert(ini[i]);
	}
	e = 0;
	for (auto r : help) {
		hsh[r] = ++e;
	}
	b = 0;
	vector<ll> app;
	app.pb(0);
	for (i = 1; i <= a; i++) {
		fin[i] = hsh[ini[i]];
		if (fin[i] > b) {
			b = fin[i];
			app.pb(i);
		}
	}
	ini[0] = fin[0] = 0;
	SET(bit1, 0); SET(bit2, 0); m = 0; SET(freq, 0);
	for (i = app.size() - 1, j = a; i >= 1; i--) {
		c = app[i]; d = app[i - 1];
		for (; j >= c; j--) {
			update(bit1, fin[j], ini[j]);
			update(bit2, fin[j], 1);
		}
		f = query(bit1, e) - query(bit1, fin[d]);
		g = query(bit2, e) - query(bit2, fin[d]);
		h = f - g * fin[d] - m;
		freq[c] = h; m += h;
	}
	for (i = 1; i <= a; i++) {
		cout << freq[i] << endl;
	}
	return 0;
}

