    }
    auto b=a;
    rep(i,n+1)b.push_back(tmp[i]);
    rep(i,n+1)b.push_back(tmp[i]+1);
    sort(all(b));
    segment<lint>s(b.size()),t(b.size());
    rrep(i,n){  
        lint p=lower_bound(all(b),a[i])-b.begin();
        lint l=lower_bound(all(b),tmp[i]+1)-b.begin();
        lint r=lower_bound(all(b),tmp[i+1])-b.begin();
        s.update(p,p);
        t.update(p,1);
        if(a[i]==tmp[i+1])ans[i]=s.get(l,r)-t.get(l,r)*tmp[i]+(tmp[i+1]-tmp[i])*t.get(l,b.size());
