vector<int> trivial(int n, vector<int> a) {
    vector<int> s;

    auto sum = accumulate(a, 0LL);

    while (true) {
        pair<int, int> p(0, n + 1), q(0, n + 1);

        for (int i : rep(0, n)) {
            p = max(p, {a[i], i});

            if (q.first < a[i]) {
                q = make_pair(a[i], i);
            }
        }

        if (p.first == 0) {
            break;
        }

        s.push_back(q.second + 1);

        a[p.second]--;
    }

    vout(s, sum);

    vector<int> cnt(n + 1);
    for (int i : rep(0, n)) {
        cnt[i] = count(s, i + 1);
    }

    return cnt;
}

