	ll arr[N], ans[N];
	bool cmparr(const int i, const int j)
	{
		return arr[i] == arr[j] ? i < j : arr[i] > arr[j];	
	}
	int work()
	{
		read(n);
		for (int i = 0; i < n; i++)
			read(arr[i]), id[i] = i;
		sort(id, id + n, cmparr);
		int fir = 0, sec = 1;
		while (sec < n)
		{
			while (sec < n && arr[id[sec]] == arr[id[sec - 1]])
