using namespace std;

typedef long long ll;

template<typename T>
struct BIT {
  vector<T> data;
  BIT() {}
  BIT(int n) : data(n+1, 0) {}
  void init(int n) { data.assign(n+1, 0); }
  T sum(int ed) const {
    for(T res(0); ; ed &= ed-1) if(ed) res += data[ed]; else return res;
  }
  void add(int i, const T& x) {
    for(++i; i < (int)data.size(); i += i&-i) data[i] += x;
  }
};


int vs[100000+10];
ll cs[100000+10];
BIT<ll> bit1;
BIT<ll> bit2;

struct K {
  ll v;
  int idx;
};
bool operator<(const K& a, const K& b) {
  if(a.v != b.v) return a.v < b.v;
  return a.idx > b.idx;
}

int main(void) {
  int n;
  scanf("%d", &n);
  REP(i, n) {
    scanf("%d", &vs[i]);
  }

  priority_queue<K> q;
  REP(i, n) {
    q.push((K){vs[i], i});
  }
  bit1.init(n);
  bit2.init(n);
  while(!q.empty()) {
    K cur = q.top(); q.pop();
    ll sum = bit1.sum(n+1) - bit1.sum(cur.idx+1);
    ll cnt = bit2.sum(n+1) - bit2.sum(cur.idx+1);
    cs[cur.idx] = sum - cnt * cur.v;
    bit1.add(cur.idx, cur.v);
    bit2.add(cur.idx, 1);
  }

  ll last = -1;
  ll rest = bit1.sum(n+1);
  REP(i, n) {
    if(vs[i] <= last) {
      puts("0");
      continue;
    }
    ll cur = rest - cs[i];
    printf("%lld\n", cur);
    rest -= cur;
    last = vs[i];
  }

  return 0;
}

