	int val = mx, idx = mxidx, cnt = 0;
	pque <int> pq;
	ForE(i, mxidx, n){
		if (a[i] >= val){
			cnt++;
			ans[idx] += a[i] - val;
		}
		else{
			pq.push(a[i]);
		}
	}
	while (idx != 0){
		int newidx = b[idx];
