	for (int i = changed[max_it] + 1;i < a.size();++i) {
		unsolved.push(woa[i]);
	}
	for (int t = 0;t >= 0;++t) {
		long long next_max = changed[max_it - 1];
		for (int i = next_max + 1;i <= changed[max_it];++i) {
			unsolved.push(woa[i]);
