const int MAXN = 100100;
const int offset = (1 << 18);
const int inf = (1 << 30);

struct tournament {
	vector <ll> pref[offset * 2];
	vector <int> v[offset * 2];

	void ubaci(int x, int y) {
		x += offset;
		while (x) {
			v[x].push_back(y);
			x /= 2;
		}
	}

	void init() {
		REP(i, offset * 2) {
			if (v[i].empty()) continue;
			sort(all(v[i]));
			pref[i].push_back(v[i][0]);
			FOR(j, 1, (int)v[i].size()) pref[i].push_back(pref[i].back() + v[i][j]);
		}
	}

	ll f(int x, int l, int r) {
		ll ret = pref[x][r];
	if (l) ret -= pref[x][l - 1];
		return ret;
	}

	ll get(int cvor, int l, int r, int a, int b, int c, int d) {
		if (l > b || r < a) return 0;
		if (l >= a && r <= b) {
			int L = lower_bound(all(v[cvor]), c) - v[cvor].begin();
			int R = lower_bound(all(v[cvor]), d) - v[cvor].begin();
			if (R >= (int)pref[cvor].size()) R--;
			return f(cvor, L, R);
		}

		int mid = (l + r) / 2;

		ll x = get(cvor * 2, l, mid, a, b, c, d);
		ll y = get(cvor * 2 + 1, mid + 1, r, a, b, c, d);
		return x + y;
	}

	int cnt(int cvor, int l, int r, int a, int b, int c, int d) {
		if (l > b || r < a) return 0;
		if (l >= a && r <= b) {
			int L = lower_bound(all(v[cvor]), c) - v[cvor].begin();
			int R = upper_bound(all(v[cvor]), d) - v[cvor].begin();
			return R - L;
		}

		int mid = (l + r) / 2;
		int x = cnt(cvor * 2, l, mid, a, b, c, d);
		int y = cnt(cvor * 2 + 1, mid + 1, r, a, b, c, d);
		return x + y;
	}
}T;

int n, p[MAXN];

ll sol[MAXN];

pii pref[MAXN];
int in;

int main() {
	scanf("%d",&n);
	REP(i, n) scanf("%d",&p[i]);
	REP(i, n) T.ubaci(i, p[i]);
	T.init();

	pref[0] = mp(p[0], 0);
	FOR(i, 1, n) {
		pref[i] = pref[i - 1];
		if (p[i] > pref[i - 1].fi) pref[i] = mp(p[i], i);
	}

	in = pref[n - 1].sec;

	int pret = pref[n - 1].fi;
	int pretin = n;

	while (1) {
		ll suma = (pret - pref[in].fi) * T.cnt(1, 0, offset - 1, pretin, n - 1, pret, inf);
		sol[pretin] += suma;
		if (!in) break;
		pretin = in;
		pret = pref[in].fi;
		in = pref[in - 1].sec;
	}

	sol[0] += (ll)n * p[0];

	REP(i, n) printf("%lld\n",sol[i]);
	return 0;
}

