const int maxn = 1e5 + 7; 
const int inf = 1e9 + 7;

pii a[maxn];
int af[maxn];
ll ans[maxn];
ll sum[maxn];
int bit[maxn];

int qry(int x) {
	int ans = inf;
	while (x > 0) { ans = min(ans, bit[x]); x -= x & (-x); }
	return ans;
}

void upd(int x, int z) {
	while (x < maxn) { bit[x] = min(bit[x], z); x += x & (-x); }
}

inline bool rev(pii x, pii y) {
	if (x.first != y.first) return x.first > y.first;
	return x.second < y.second;
}

int main() {
	int n; sd(n);
	for (int i = 1; i <= n; i++) {
		sd(a[i].first); a[i].second = i;
	}

	sort(a+1, a+n+1, rev); fill(bit, bit+maxn, n+1); a[n+1].first = 0;
	fill(ans, ans+maxn, 0); sum[0] = 0;

	for (int i = n; i >= 1; i--) {
		af[i] = qry(a[i].second); upd(a[i].second, i);
		//cout<<a[i].first<<";"<<a[i].second<<" ;; "<<af[i]<<endl;
	}

	int i = 1;
	while (i <= n) {
		int nx = af[i], cur = a[i].second, occ = a[i].first, nxo = a[nx].first;
		ans[cur] = (occ - nxo) * 1ll * i;
		for (int j = i + 1; j < nx; j++) 
			ans[cur] += a[j].first - nxo;
		i = nx;
	}

	for (int i = 1; i <= n; i++) {
		pl(ans[i]); endc;
	}
}

