    ll cnt = 0;
    ll prev_sum_diff = 0;
    ll sum_diff = 0;
    while (2 <= que.size()) {
        PLL p = que.top(); que.pop();
        int idx = -p.second;
        cnt++;
        prev_sum_diff = sum_diff;
        while (2 <= que.size() && -que.top().second > idx) {
            cnt++;
            sum_diff += (p.first - que.top().first) * cnt;
            p = que.top(); que.pop();
        }
        sum_diff += (p.first - que.top().first) * cnt;

        ans[idx] = sum_diff - prev_sum_diff;
    }
