    cin.tie(nullptr);
    int N; cin >> N;
    ll ans[N+1] = {};
    priority_queue<pair<ll, int>> pq;
    rep(i, N){
        ll a; cin >> a;
        pq.push(make_pair(a, i+1));
    }
    while(!pq.empty()){
        //最大の数をなるべくたくさん取り出す
        ll cnt = 0;
        ll base = pq.top().first;
        pair<ll, int> op;
        while(!pq.empty() && pq.top().first == base){
            cnt++;
            op = pq.top();
            pq.pop();
        }
        ll diff;
        if(!pq.empty()) diff = op.first - pq.top().first;
        else diff = op.first;
        //diff*(これまで取り出したものの数)だけans[op.second]に加算
        ans[op.second] += diff*(N-pq.size());
    }
    for(int i = 1; i <= N; i++){
        cout << ans[i] << endl;
    }
    return 0;
}

