        assert(diff>0);

        ans[ml[i]] += diff*ct[i];
        ct[i-1] += ct[i];
        ct[i]=0;
    }

    rep(i,S) ans[0]+=k[i]*ct[i];

    rep(i,n) printf("%lld\n", ans[i]);
    return 0;
