using namespace std;

int n;

struct Pile
{
    int cnt;
    int cntBigger;
    int diff;
    int index;
};

bool cmpCnt (const Pile &a, const Pile &b)
{
    return make_pair(a.cnt, a.index) > make_pair(b.cnt, b.index);
}
bool cmpIndex (const Pile &a, const Pile &b)
{
    return a.index < b.index;
}

Pile a[N_MAX];

set <int> s;

int main()
{
    cin >> n;
    for(int i = 1; i <= n; i++)
    {
        cin >> a[i].cnt;
        a[i].index = i;
    }
    sort(a + 1, a + n + 1, cmpCnt);
    for(int i = 1; i <= n; i++)
    {
        a[i].cntBigger = i;
        a[i].diff = a[i].cnt - a[i + 1].cnt;
    }
    sort(a + 1, a + n + 1, cmpIndex);
    for(int i = 1; i <= n; i++)
    {
        if(s.find(a[i].cnt) != s.end())
        {
            cout << "0\n";
            continue;
        }
        cout << a[i].diff * a[i].cntBigger << "\n";
        s.insert(a[i].cnt);
    }
    return 0;
}

