int main()
{
	ll n; cin >> n;
	vector<ll> a( n );
	priority_queue<ll> pq;
	map<ll, priority_queue<ll, vector<ll>, greater<ll>>> mpq;
	rep( i, n )
	{
		cin >> a[i];
		pq.push( a[i] );
		mpq[a[i]].push( i );
	}

	ll x = pq.top();
	ll idx = mpq[x].top();
	map<ll, ll> mcnt;
	rep( i, n ) mcnt[a[i]]++;
	vector<ll> ans( n );
	while ( pq.empty() == false )
	{
		pq.pop();
		ll y;
		if ( pq.empty() ) y = 0;
		else y = pq.top();

//		cout << x << " : " << mcnt[x] << ", " << y << " : " << mcnt[y] << endl;

		if ( x != y )
		{
			ans[idx] += ( x - y ) * mcnt[x];
			mcnt[y] += mcnt[x];
			if ( y != 0 )
				idx = mpq[y].top();
		}
		else
		{
			ans[idx] += mcnt[x];
			mcnt[mpq[pq.top()].top()] += mcnt[x];
			idx = mpq[pq.top()].top();
		}
		mcnt[x] = 0;
		x = y;
	}

	rep( i, n ) cout << ans[i] << endl;

	return ( 0 );
}

