	scanf("%d",&n);

	for(i=1;i<=n;i++){
		scanf("%d",&par[i].x);
		par[i].y=i;
	}

	sort( par+1 , par+1+n , cmp );

	mind=par[1].y;
	cur=par[1].x;

	for(i=1;i<=n+1;i++){
