    int N; cin >> N;
    vector<int> A(N); for (auto &a : A) cin >> a;
    vector<int> I = {0};
    for (int i = 0; i < N; i++) {
        if (A[i] > A[I.back()]) {
            I.push_back(i);
        }
    }
    vector<Int> X(I.size()), C(I.size()), R(I.size());
    for (int i = 0; i < I.size(); i++) X[i] = A[I[i]];
    for (int i = 0; i < N; i++) {
        int t = lower_bound(begin(X), end(X), A[i]) - begin(X);
        R[t] += A[i] - X[t];
        C[t] += 1;
    }
    for (int i = I.size()-2; i >= 0; i--) {
        C[i] += C[i+1];
    }
    vector<Int> ANS(N);
    for (int i = 0; i < I.size(); i++) {
        ANS[I[i]] = C[i] * (X[i] - (i-1 >= 0 ? X[i-1] : 0)) + R[i];
    }
    for (auto a : ANS) cout << a << '\n';
    return 0;
}

