		while(ps[k].second != ms[i]){
			sum += ps[k].first - as[ms[i]];
			--k;
			++cnt;
		}
		ans[ms[i + 1]] = sum;
	}

	for(int i = 1; i <= n; ++i){
		printf("%lld\n", ans[i]);
	}
}



