// quoted from beet-aizu
template <typename T, typename E, typename F, typename G>
struct SegmentTree{
    // using F = function<T(T, T)>
    // using G = function<T(T, E)>
    int n;
    F f;
    G g;
    T ti;
    vector<T> dat;
    SegmentTree(){};
    SegmentTree(F f,G g,T ti):f(f),g(g),ti(ti){}
    void init(int n_){    
        n=1;
        while(n<n_) n<<=1;
        dat.assign(n<<1,ti);
    }
    void build(const vector<T> &v){
        int n_=v.size();
        init(n_);
        for(int i=0;i<n_;i++) dat[n+i]=v[i];
        for(int i=n-1;i;i--)
            dat[i]=f(dat[(i<<1)|0],dat[(i<<1)|1]);
    }
    void update(int k,const E &x){
        k += n;
        dat[k] = g(dat[k], x);
        while(k>>=1)
            dat[k]=f(dat[(k<<1)|0],dat[(k<<1)|1]);    
    }
    T operator [](int k) const { return dat[k+n]; }
    T query(int a,int b) const {
        T vl=ti,vr=ti;
        for(int l=a+n,r=b+n;l<r;l>>=1,r>>=1) {
            if(l&1) vl=f(vl,dat[l++]);
            if(r&1) vr=f(dat[--r],vr);
        }
        return f(vl,vr);
    }



    /* TODO わからない 聞く 
    template<typename C>
    int find(int a,int b,C &check,int k,int l,int r){
        if(!check(dat[k])||r<=a||b<=l) return -1;
        if(k>=n) return k-n;
        int m=(l+r)>>1;
        int vl=find(a,b,check,(k<<1)|0,l,m);
        if(~vl) return vl;
        return find(a,b,check,(k<<1)|1,m,r);
    }
    template<typename C>
    int find(int a,int b,C &check){
        return find(a,b,check,1,0,n);
    }*/

};


int main(){
  using T = pair<lint, lint>;  // type T
  using E = lint;  // type E
  auto f = [](T a, T b){ // return type T value
    if(a.first > b.first) return a;
    else if(a.first < b.first) return b;
    else {
      if(a.second < b.second) return a;
      else return b;
    }
  };
  auto g = [](T a, E b){ // return type T value
    return a;
  };
  T ti = {0, INF};  // identify element
  SegmentTree<T, E, decltype(f), decltype(g)> sg(f, g, ti);  // don't change

  lint n; cin >> n;
  vector<lint> a(n);
  vector<pair<lint, lint>> dat(n);
  rep(i, n) {
    cin >> a[i];
    dat[i] = {a[i], i};
  }
  sg.build(dat);   // 初期配列を代入

  lint r = n;
  lint l = 0;
  vector<pair<lint, lint>> cols;
  while(l < r) {
    pair<lint, lint> val = sg.query(l, r);
    cols.push_back(val);
    r = val.second; 
  }

  cols.push_back({0, 0});

  map<lint, lint> mp;
  rep(i, n) mp[a[i]]++;
  vector<int> ans(n, 0);
  for(int i = 0; i < cols.size() - 1; i++) {
    lint before = cols[i].first;
    lint after = cols[i + 1].first;
    lint cnt = mp[before];
    ans[cols[i].second] += cnt * (before - after);
    mp[after] += cnt;
  } 
  for(int i = 0; i < n; i++) cout << ans[i] << endl;
  return 0;
}

