typedef long long ll;
const int maxn = 4e5+10;
int n,tmp,a[100005];
ll cnt[100005];
int ret,id1,id2;
struct tree{
	int left;
	int right;
	int max_num;
	int id;
	int flag;
}node[maxn];


void gx(int o){
	if(node[o*2].flag==-1&&node[o*2+1].flag==-1){
		if(node[o*2].max_num==node[o*2+1].max_num){
			node[o].max_num=node[o*2].max_num;
			node[o].flag=-1;
			node[o].id=node[o*2].id;
		}else{
			if(node[o*2].max_num>=node[o*2+1].max_num){
				node[o].max_num=node[o*2].max_num;
				node[o].id=node[o*2].id;
			}else{
				node[o].max_num=node[o*2+1].max_num;
				node[o].id=node[o*2+1].id;
			}
			node[o].flag=0;
		}
	}else{
			if(node[o*2].max_num>=node[o*2+1].max_num){
				node[o].max_num=node[o*2].max_num;
				node[o].id=node[o*2].id;
			}else{
				node[o].max_num=node[o*2+1].max_num;
				node[o].id=node[o*2+1].id;
			}
			node[o].flag=0;
	}
}

void build(int o,int l,int r){
	node[o].left=l;
	node[o].right=r;

	if(l==r){
		node[o].max_num=a[l];
		node[o].flag=-1;
		node[o].id=l;
		return;
	}
	build(o*2,l,(l+r)/2);
	build(o*2+1,(l+r)/2+1,r);

	gx(o);
}

void find_max(int o,int ql,int qr){
	if(ql<=node[o].left&&qr>=node[o].right){
		if(node[o].max_num>ret){
			ret=node[o].max_num;
			id2=node[o].id;
			return;
		}
	}else{
		int mid=(node[o].left+node[o].right)>>1;
		if(ql<=mid)find_max(o*2,ql,qr);
		if(qr>mid)find_max(o*2+1,ql,qr);
	}
}

void change(int o,int ql,int qr){
	if(node[o].max_num<=ret)return;
	if(node[o].flag==-1){
		cnt[id1]+=(node[o].max_num-ret)*(node[o].right-node[o].left+1);
		node[o].max_num=ret;
		return;
	}
	if(node[o].left==node[o].right){
		cnt[id1]+=(node[o].max_num-ret);
		node[o].max_num=ret;
		return;
	}
	int mid=(node[o].left+node[o].right)>>1;
	if(ql<=mid)change(o*2,ql,qr);
	if(qr>mid)change(o*2+1,ql,qr);

	gx(o);
}
int main(int argc, char** argv) {
	//freopen("in.txt","r",stdin);
	cin>>n;int x;ll sum=0;
	for(int i=1;i<=n;i++){
		scanf("%d",&a[i]);
        sum+=a[i];
	}
	build(1,1,n);
	//for(int i=1;i<=20;i++)cout<<node[i].left<<"-"<<node[i].right<<":"<<node[i].id<<"-"<<node[i].max_num<<endl;
	ret=node[1].max_num,id1=node[1].id;
	if(id1==1){
		cout<<sum<<endl;
		for(int i=2;i<=n;i++)cout<<0<<endl;
		return 0; 
	}
	while(id1!=1){
		ret=-1;
		find_max(1,1,id1-1);
		change(1,id1,n);
		id1=id2;
	}
	cnt[1]+=(n*ret);
	for(int i=1;i<=n;i++)cout<<cnt[i]<<endl;
	return 0;
}

