template<typename T>
struct BIT {
    int n;
    vector<T> dat;

    BIT(int n=0){
        initialize(n);
    }

    void initialize(int nin){
        n = nin;
        dat.resize(n);
        for(int i = 0; i<n; i++) dat[i] = 0;
    }

    T sum(int i){
        T s = 0;
        while(i >= 0){
            s += dat[i];
            i = (i & (i+1)) - 1;
        }
        return s;
    }

    T sum_between(int i, int j){
        if(i > j) return 0;
        return sum(j) - sum(i-1);
    }

    void plus(int i, T x){
        while(i < n){
            dat[i] += x;
            i |= i+1;
        }
    }

    // a[0]+...+a[ret+1] >= x
    int lower_bound(T x){
        int ret = -1;
        int k = 1;
        while(2*k <= n) k <<= 1;
        for( ;k>0; k>>=1){
            if(ret+k < n && dat[ret+k] < x){
                x -= dat[ret+k];
                ret += k;
            }
        }
        return ret + 1;
    }
};

int main(){
  int n;cin>>n;
  int a[n];rep(i,n)cin>>a[i];
  set<int> s;rep(i,n)s.insert(a[i]);
  s.insert(0);
  BIT<int> bit(n+1);
  int forth[n];
  rep(i,n){
    int j=n-1-i;
    bit.plus(a[j],1);
    forth[j]=bit.sum_between(a[j],n);
  }
  int ans[n]={};
  auto it=s.end();
  --it;
  int k=n-1;
  while(true){
    if(it==s.begin())break;
    if(k==-1){
      ans[0]+=n;break;
    }
    if(a[k]==(*it)){
      while(a[k]==(*it))--k;
      ++k;
      ans[k]=forth[k]*((*it)-(*(--it)));
    }
    --k;
  }
  rep(i,n)cout<<ans[i]<<endl;
}

