long long ans[100005];

int data[100005], cc = 0;

inline int hs(int x) {
    return lower_bound(data, data + cc, x) - data + 1;
}

pair <int, long long> operator + (pair <int, long long> a, pair <int, long long> b) {
    return make_pair(a.first + b.first, a.second + b.second);
}

struct Seg {
    int l, r, c, lz;
    long long s;
} T[400005];

inline void push_up(int o) {
    T[o].c = T[ls].c + T[rs].c;
    T[o].s = T[ls].s + T[rs].s;
}

inline void clr(int o) {
    T[o].c = T[o].s = 0;
    T[o].lz = 1;
}

inline void push_down(int o) {
    if(!T[o].lz) return;
    clr(ls); clr(rs);
    T[o].lz = 0;
}

void build(int o, int l, int r) {
    T[o].l = l; T[o].r = r;
    T[o].c = T[o].s = T[o].lz = 0;
    if(l == r) return;
    int m = (l + r) >> 1;
    build(ls, l, m);
    build(rs, m + 1, r);
}

void update(int o, int x, int c, long long v) {
    if(T[o].l == T[o].r) {
        T[o].c += c;
        T[o].s += v;
        return;
    }
    push_down(o);
    int m = (T[o].l + T[o].r) >> 1;
    update(x <= m ? ls : rs, x, c, v);
    push_up(o);
}

void modify(int o, int l, int r) {
    if(T[o].l == l && T[o].r == r) {
        clr(o);
        return;
    }
    push_down(o);
    int m = (T[o].l + T[o].r) >> 1;
    if(r <= m) modify(ls, l, r);
    else if(l > m) modify(rs, l, r);
    else {
        modify(ls, l, m);
        modify(rs, m + 1, r);
    }
    push_up(o);
}

pair <int, long long> query(int o, int l, int r) {
    if(T[o].l == l && T[o].r == r) return make_pair(T[o].c, T[o].s);
    push_down(o);
    int m = (T[o].l + T[o].r) >> 1;
    if(r <= m) return query(ls, l, r);
    if(l > m) return query(rs, l, r);
    return query(ls, l, m) + query(rs, m + 1, r);
}

