        if(a[i] > a[p[i]])
            p[i] = i;
    }
    for(int i = 1; i <= n; ++ i)
        data[cc ++] = a[i];
    sort(data, data + cc);
    cc = unique(data, data + cc) - data;
    build(1, 1, cc);
    for(int i = 1; i <= n; ++ i)
        update(1, hs(a[i]), 1, a[i]);
