void solve() {
	int N; cin >> N;
	vector<int> A(N); cin >> A;
	vector<pii> nums;
	nums.emplace_back(0, 0);
	nums.emplace_back(A[0], 0);
	vector<int> memo(N);
	for (int i = 1; i < N; ++i) {
		if (nums.back().first < A[i]) nums.emplace_back(A[i], i);
	}
	vector<int> imos(nums.size());
	for (int i = 0; i < N; ++i) {
		auto it = lower_bound(ALL(nums), make_pair(A[i], -1LL));
		auto it2 = it - 1;
		int index = it2 - nums.begin();
		imos[index]++;
		memo[it->second] += (A[i] - it2->first);
	}
	RREP(i,nums.size()-1){
		imos[i] += imos[i + 1];
	}
	REP(i,nums.size()-1){
		memo[nums[i+1].second] += (nums[i + 1].first - nums[i].first)*imos[i+1];
	}
	for (int i = 0; i < N; ++i) {
		cout << memo[i] << endl;
	}
}

