    Compress<int> comp(a); comp.build();
    SegmentTree<ll> segt(n + 1, [](ll a, ll b){return a+b;}, 0);
    for (auto &p : comp.get(a)) {
        segt.update(p, segt.query(p, p + 1) + 1);
    }
    vector<int> b(n); b[0] = a[0]; rep (i, 1, n) b[i] = max(a[i], b[i - 1]);
    vector<ll> ans(n); ans[0] = n;
    reprev (i, 1, n) {
        if (b[i] != b[i - 1]) {
            ll k = b[i] - b[i - 1];
            ans[i] = k * segt.query(comp.get(a)[i], n + 1);
        }
    }
    rep (i, n) cout << ans[i] << '\n';
    return 0;
}

