struct Compressor {
  llToIntHash compress;
  intToLlHash restore;

  Compressor(int N, ll *a) {

    ll b[N];
    for(int i = 0; i < N; i++)
      b[i] = a[i];

    sort(b, b + N);

    for(int i = 0; i < N; i++)
      if(compress.find(b[i]) == compress.end()) {
	int compressed = compress.size() + 1;
	compress[b[i]] = compressed;
	restore[compressed] = b[i];
      }
  }
};

class Bit {
private:
  const int size = (1 << 18);
  int tree[(1 << 18) + 1];
public:
  Bit() {
    for(int i = 0; i < size + 1; i++) {
      tree[i] = 0;
    }
  }

  void addOne(int pos) {
      while(pos <= size) {
        tree[pos] += 1;
        pos += (pos & -pos);
      }
  }

  int countUpTo(int pos) {
      int ret = 0;
      while(pos > 0) {
        ret += tree[pos];
        pos -= (pos & -pos);
      }
      return ret;
  }

};


