    vector<ll> a(n);
    vector<ll> sorted(n);
    ll sum = 0;
    rep(i, n) {
        cin >> a[i];
        sorted[i] = a[i];
        sum += a[i];
    }

    sort(all(sorted));
    get_unique(sorted);
    vector<int> order(n);
    rep(i, n) order[i] = lower_bound(all(sorted), a[i]) - sorted.begin();

    vector<ll> num(n);
    vector<ll> vec(100100, 0);
    SegmentTree segt(vec);
    rrep(i, n) {
        segt.update(order[i], 1);
        num[i] = segt.query(order[i], 100100);
    }

    vector<bool> zero(n, true);
    ll now = 0;
    int cnt = 0;
    rep(i, n) {
        if (chmax(now, a[i])) {
            zero[i] = false;
            cnt++;
        }
    }

    now = 0;
    vector<ll> ans(n);
    rep(i, n) {
        if (zero[i]) {
            ans[i] = 0;
            continue;
        }
        if (i == 0) {
            now=a[i];
            cnt--;
            continue;
        }
        if (cnt == 1) {
            int pos = i - 1;
            while (zero[pos]) pos--;
            ll tmp = 0;
            for (int j = i; j < n; j++) {
                tmp += max(0LL, a[j] - a[pos]);
            }
            ans[i] = tmp;
            sum -= tmp;
            cnt--;
            continue;
        }

        ans[i] = (a[i] - now) * num[i];
        sum -= (a[i] - now) * num[i];
        cnt--;
        now = a[i];
    }

    ans[0]=sum;
    rep(i, n) cout << ans[i] << endl;
