class SegmentTree{
  int n;
  vl node;
public:
  SegmentTree(int n_){
    n=1;
    while(n<n_)n*=2;
    node = vl(2*n-1,0);
  }

  void add(int k, int v){
    int cur = k + n-1;
    node[cur] += v;
    while(cur>0){
      cur = (cur-1)/2;
      node[cur] = node[cur*2+1] + node[cur*2+2];
    }
  }

  //return maximum value in [a,b). ( [l,r) is interval in which k is.)
  ll rangeSum(int a,int b,int k=0,int l=0,int r=0){
    if(l>=r)r = n;
    if(r<=a || b<=l)return 0;
    if(a<=l && r<=b)return node[k];
    ll vl = rangeSum(a,b,2*k+1,l,(l+r)/2);
    ll vr = rangeSum(a,b,2*k+2,(l+r)/2,r);
    return vl + vr;
  }
};

