    partial_max[i+1] = max(a[i+1], partial_max[i]);
  }

  vl id = a;
  sort(all(id));
  id.erase(unique(all(id)), id.end());

  SegmentTree st(n+1);

  rrep(i,n){
    ll val = lower_bound(all(id), a[i+1]) - id.begin();
    st.add(val, 1);

    ll dif = partial_max[i+1] - partial_max[i];
    ll val_max = lower_bound(all(id), partial_max[i]) - id.begin();
    if(dif > 0) ans[i] = dif * st.rangeSum(val_max+1,n+1);
  }

  rep(i,n) cout << ans[i] << endl;
}

