int max_i(const vector<int> &v, int start, int end)
{
  int max = 0, ret = 0;
  for (int i = start; i < end; i++) {
    if (max < v[i]) {
      max = v[i];
      ret = i;
    }
  }
  return ret;
}

int sum_up(vector<int> &v, int start, int end, int up)
{
  int sum = 0;
  for (int i = start; i < end; i++) {
    if (v[i] > up) {
      sum += (v[i] - up);
      v[i] = up;
    }
  }
  return sum;
}

