      while (!rest.empty() && rest.begin()->first <= a[i]) {
        t += rest.begin()->first - now_max;
        rest.erase(rest.begin());
      }
      t += rest.size() * (a[i] - now_max);
      now_max = a[i];
    }
    io.writeln(t);
  }
  return 0;
}

