	repn(i, N) za[p[i].second] = p[i].first;

	Segment_Tree<ll> sg(N, [](ll a, ll b) {return a + b; }, 0);

	vector<ll> suf(N + 1);

	for (ll i = N; i >= 1; i--) {
		ll x = sg.query(za[i],za[i] + 1);

		sg.update(za[i], x + 1);

