int compress(vector<int> &x) {
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    for(int i = 0; i < x.size(); i++){
        zip[x[i]] = i;
        unzip[i] = x[i];
    }
    return x.size();
}

struct BIT{
    int bit[MAX_N + 1];
    int n;

    BIT(const int n): n(n){
        for (int i=0;i<MAX_N;i++) bit[i] = 0;
    }

    int sum(int i){
        int S = 0;
        while(i > 0){
            S += bit[i];
            i -= i & -i;
        }
        return S;
    }

    void add(int i, int x){
        while(i <= n){
            bit[i] += x;
            i += i & -i;
        }
    }

};

