		if(a[i] > prev)
		{
			// wez wszystkie <= od niego po prawej
			// one automatycznie sa na prawo od niego - tak dziala algos
			while(ind < N && t[ind].first <= a[i])
			{
				res[i] += t[ind].first - prev;
				ind++;
			}
			// uzupelnij to, czego brakuje
			res[i] += (N-ind)*(LL)(a[i]-prev);
			// do kolejnego wiekszego
			prev = a[i];
		}

	REP(i,N)
		printf("%lld\n", res[i]);

	return 0;
}

