void body() {
    auto N = read<i64>();
    auto as = read<i64>(N);

    OrderedMap<i64, Vector<i64>> xs;
    REP (i, N) {
        if (xs.find(as[i]) == xs.end()) {
            xs[as[i]] = {};
        }
        xs[as[i]].push_back(i);
    }

    Vector<pair<i64, Vector<i64>>> Xs = {make_pair(0L, Vector<i64>())};
    EACH (x, xs) {
        Xs.push_back(x);
    }

    Vector<i64> ans(N, 0);
    i64 M = numeric_limits<i64>::max();
    i64 total = 0;
    FORR(i, 1, Xs.size()) {
        auto n_0 = Xs[i].first;
        auto n_1 = Xs[i - 1].first;
        if (Xs[i].second.empty()) continue;
        if (M > Xs[i].second.front()) {
            M = Xs[i].second.front();
        }
        total += Xs[i].second.size();

        ans[M] += total * (n_0 - n_1);
    }

    REP (i, N) {
        cout << ans[i] << endl;
    }
}

