        }
        a.emplace_back(0LL);

        CoordinateCompression<lint> c(a, -1);
        vector<int> id(c.size() - 1);
        for(int i = n - 1 ; i >= 0 ; --i){
            id[c.get(a[i])] = i;
        }
        for(int i = c.size() - 3 ; i >= 0 ; --i){
            id[i] = min(id[i], id[i + 1]);
        }

        SegmentTree<lint, lint> sum(c.size() - 1, [](lint l, lint r){ return l + r; }, [](lint l, lint r){ return l + r; }, 0LL);

        vector<lint> ans(n, 0LL);
        int k = n - 1;
        for(int i = c.size() - 2 ; i >= 0 ; --i){
            for( ; k > id[i] ; --k){
                sum.update(c.get(a[k]), 1LL);
            }
            ans[k] += (sum.get(i, c.size() - 1) + 1LL) * (c.restore(i) - c.restore(i - 1));
        }
        for(int i = 0 ; i < n ; ++i){
