        cin >> a[i];
    }
    auto b = a;
    sort(all(b));
    b.erase(unique(all(b)), b.end());
    int sz = b.size();
    map<int, int> mp;
    rep(i, sz) {
        mp[b[i]] = i;
    }
    vector<int> cnt(sz, 0);
    rep(i, n) {
        cnt[mp[a[i]]] ++;
    }
    vector<int> c(sz + 1, 0);
    rep(i, sz) {
        c[i + 1] = c[i] + cnt[i];
    }
