int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll N;
    cin >> N;
    vector<ll> a(N+1), ans(N);
    rep(i, N)cin >> a[i+1];
    auto iter = max_element(all(a));
    priority_queue<ll> que;
    for(auto i = iter; i<end(a); i++){
        que.push(*i);
    }
    ll cnt = 0;
    int index = distance(begin(a), iter);
    while(index>=1){
        auto next_iter = max_element(begin(a), iter);
        ll p = *iter, np = *next_iter;
        ll res = cnt*(p-np);
        for(auto i = next_iter; i<iter;i++){
            que.push(*i);
        }
        while(SZ(que) && que.top()>np){
            res+=que.top()-np;
            cnt+=1;
            que.pop();
        }
        ans[index-1] = res;
        iter = next_iter;
        index = distance(begin(a), iter);
    }
    rep(i, N)cout << ans[i] << '\n';
    return 0;
}

