using namespace std;

int max_i(const vector<long> &v, int start, int end)
{
  long max = 0;
  int ret = 0;
  for (int i = start; i < end; i++) {
    if (max < v[i]) {
      max = v[i];
      ret = i;
    }
  }
  return ret;
}

long sum_up(vector<long> &v, int start, int end, long up)
{
  long sum = 0;
  for (int i = start; i < end; i++) {
    if (v[i] > up) {
      sum += (v[i] - up);
      v[i] = up;
    }
  }
  return sum;
}

int main()
{
  int N;
  cin >> N;

  vector<long> a(N), s(N);
  for (int i = 0; i < N; i++) {
    cin >> a[i];
    s[i] = 0;
  }

  int spot = max_i(a, 0, N);
  int target = max_i(a, 0, spot);
  while(spot != 0) {
    s[spot] = sum_up(a, spot, N, a[target]);
    spot = target;
    target = max_i(a, 0, spot);
  }

  s[0] = sum_up(a, 0, N, 0);
  for (int i = 0; i < N; i++) {
    cout << s[i] << endl;
  }
  return 0;
}

