int64 rec(int64 L, map<int64,int>& D, map<int64,int64>& next_){
    auto ne = next_[L];
    if(D[ne] == 0) return 0;
    int64 res = rec(ne, D, next_);
    int64 tmp = D[ne];
    D[L] += tmp;
    D[ne] = 0;
    return res + tmp * (ne - L);
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int N; cin >> N;
