    N++;
    map<int64,int> D;
    for(auto a:A){
        D[a]++;
    }

    auto B=A;
    sort(ALL(B));
    B.erase(unique(ALL(B)), B.end());
    map<int64,int64> next_;
    REP(i,B.size()-1){
        next_[B[i]] = B[i+1];
    }
    next_[B.back()] = -1;

    vector<int64> ans(N);
    int max_idx = 0;
