  b.n=n+1;
  priority_queue<P> que;
  ll sum=0,cnt=0;
  rrep(i,n) {
    que.push(P(a[i],i));
    if(d[i]!=i) continue;
    while(!que.empty()&&(!i||que.top().F>=a[d[i-1]])) {
      P p=que.top();que.pop();
