/* 考察メモ
1の個数が最大になったら，それ以外をずっと取り除くのが最善
一番後ろにある大きな数を取り除く貪欲法で問題ない

max(t, 0)の総和
 */
int N;
vector<int64_t> a;
struct BIT{
  vector<int64_t> bit;int64_t size;
  BIT(int64_t n){
    size=n;bit=vector<int64_t>(n+1);
  }
  //a[i]=x
  void add(int64_t i,int64_t x){
    i+=1;
    while(i<=size)bit[i]+=x,i+=i&-i;
  }

  int64_t get(int64_t i) {
    return sum(i + 1) - sum(i);
  }
  //a[k] (k<i)の和
  int64_t sum(int64_t i){
    int64_t s=0;
    while(i>0)s+=bit[i],i-=i&-i;
    return s;
  }
};

int main() {
  cin >> N;
  a.resize(N);
  for(auto &num: a)cin >> num;
  vector<int64_t> ca(a);
  sort(ca.begin(), ca.end());
  ca.erase(unique(ca.begin(), ca.end()), ca.end());
  unordered_map<int64_t, int64_t> compress;
  for(size_t i = 0; i < ca.size(); i++) {
    compress[ca[i]] = i;
  }
  BIT bit(ca.size() + 1);
  BIT cnt(ca.size() + 1);
  for(size_t i = 0; i < a.size(); i++) {
    bit.add(compress[a[i]], a[i]);
    cnt.add(compress[a[i]], 1);
  }
  int64_t last = 0;
  int64_t diff = 0;
  for(size_t i = 0; i < a.size(); i++) {
    // a[i]以下の和
    int64_t target = a[i] - diff;
    if(target < 0) {
      cout << 0 << endl;
      continue;
    }
    diff += target;
    target = diff;
    int64_t target_ofs = lower_bound(ca.begin(), ca.end(), target) - ca.begin();
    int64_t sum = bit.sum(target_ofs);
    int64_t sum2 = cnt.sum(ca.size() + 1) - cnt.sum(target_ofs);
    int64_t cur = sum +  sum2 * target;
    cout << cur - last << endl;
    last = cur;
  }
  return 0;
}

