bool DEBUG = false;

void bf() {
  ll sum = 0;
  rep(i,n) sum += (ll)a[i];
  while(sum) {
    int maxi_p = -1;
    if( DEBUG ) {
      cout << "sum = " << sum << endl;
      cout << "a = "; rep(i,n) cout << a[i] <<" "; puts("");
      cout << "h = "; rep(i,n) cout << h[i] <<" "; puts("");
    }
    rep(i,n) {
      if( a[i] == 0 ) continue;
      if( maxi_p == -1 ) maxi_p = i;
      else if( a[maxi_p] < a[i] ) maxi_p = i;
    }
    assert( maxi_p != -1 );
    int next_p = -1;
    rep(i,n) {
      if( a[i] == 0 ) continue;
      if( i == maxi_p ) continue;
      if( next_p == -1 ) next_p = i;
      else if( a[next_p] < a[i] ) next_p = i;
    }
    if( next_p == -1 ) {
      h[maxi_p] += (ll)a[maxi_p];
      a[maxi_p] = 0;
      sum = 0;
    } else {
      if( next_p < maxi_p ) {
	ll diff = a[maxi_p] - a[next_p];
	h[maxi_p] += diff;
	a[maxi_p] -= diff;
	sum -= diff;
      } else {
	int prev_p = -1;
	rep(i,maxi_p) {
	  if( a[i] == 0 ) continue;
	  if( a[prev_p] < a[i] ) prev_p = i;
	}
	if( prev_p == -1 ) {
	  REP(i,maxi_p+1,n) {
	    h[maxi_p] += a[i];
	    sum -= a[i];
	    a[i] = 0;
	  }
	} else {
	  REP(i,maxi_p+1,n) {
	    if( a[i] > a[prev_p] ) {
	      h[maxi_p] += ( llabs(a[i]-a[prev_p]) );
	      sum -= ( llabs(a[i]-a[prev_p]) );
	      a[i] -= ( llabs(a[i]-a[prev_p]) );
	      assert( a[i] >= 0LL );
	    }
	  }
	}
      }
    }
  }
}

