template <typename T=int>
struct BIT {
    const int n;
    vector<T> v;

    BIT(int n): n(n), v(n+1,0) {}

    void add(int i, int x) {
        i += 1;
        while (i <= n) {
            v[i] += x;
            i += i & -i;
        }
    }
    T sum(int i) {
        i += 1;
        T ret = 0;
        while (i > 0) {
            ret += v[i];
            i -= i & -i;
        }
        return ret;
    }
    T sum(int l, int r) {
        return sum(r) - sum(l-1);
    }
};

void solve() {
    int n;
    cin >> n;
    VI a(n);
    REP(i,0,n) cin >> a[i];

    VP ps(n);
    REP(i,0,n) ps[i] = MP(a[i],i);
    ps.pb(0,-1);
    sort(all(ps));
    reverse(all(ps));

    VLL ans(n);

    int mini = n;
    REP(i,0,n) {
        int idx = ps[i].second;
        chmin(mini, idx);
        ans[mini] += (1LL + i) * (ps[i].first - ps[i+1].first);
    }

    REP(i,0,n) cout << ans[i] << endl;
}

