    vector<DATA> lazy2; //遅延評価 - http://tsutaj.hatenablog.com/entry/2017/03/30/224339
    vector<bool> lazy1_flag;
    vector<bool> lazy2_flag;
    Segment_Tree(ll n__, const F &f, DATA init) : f(f), init(init){
      // For simply, the number of component is set to be power of 2
      n = 1;
      n_ = n__;
      while(n < n_) n*=2;

      dat.resize(2*n-1, init);
      lazy1.resize(2*n-1, 0);
      lazy2.resize(2*n-1, init);
      lazy1_flag.resize(2*n-1, false);
      lazy2_flag.resize(2*n-1, false);
      return;
    };

    ~Segment_Tree(void){
      return;
    };

    void eval1(ll k, ll l, ll r){
      if(!lazy1_flag[k]) return;
      if(l>=r) return;
      lazy1_flag[k] = false;

      dat[k] = lazy1[k];

      if(r-l>1){
        lazy1[2*k+1] = lazy1[k];
        lazy1[2*k+2] = lazy1[k];
        lazy1_flag[2*k+1] = true;
        lazy1_flag[2*k+2] = true;
      }

      lazy1[k] = 0;
    }

    DATA eval2_2(DATA tmp, ll n){
      DATA ans = tmp;
      ll n_copy = n;
      DATA tmp_copy = tmp;
      n--;
      while(n>0){
        if(n&1) ans = f(ans, tmp);
        tmp = f(tmp, tmp);
        n>>=1;
      }
      return ans;
    }

    void eval2(ll k, ll l, ll r){
      if(!lazy2_flag[k]) return;
      if(l>=r) return;
      lazy2_flag[k] = false;

      dat[k] = f(dat[k], eval2_2(lazy2[k], r-l));

      if(r-l>1){
        lazy2[2*k+1] = f(lazy2[2*k+1], lazy2[k]);
        lazy2[2*k+2] = f(lazy2[2*k+2], lazy2[k]);
        lazy2_flag[2*k+1] = true;
        lazy2_flag[2*k+2] = true;
      }

      lazy2[k] = init;
    }

    //k-th value is changed to a
    void update1(ll k, DATA a){
      k += n-1;
      dat[k] = a;
      while(k>0){
        k = (k-1)/2;
        dat[k] = f(dat[k*2+1], dat[k*2+2]);
      }
      return;
    };

    //k-th value is operated of a
    void update2(ll k, DATA a){
      k += n-1;
      dat[k] = f(dat[k], a);
      while(k>0){
        k = (k-1)/2;
        dat[k] = f(dat[k*2+1], dat[k*2+2]);
      }
      return;
    };

    //[a,b)の範囲の値をxに変える
    void rangeupdate1(ll a, ll b, DATA x, ll k, ll l, ll r){

      eval1(k,l,r);

      if(r<=a || b<=l) return;

      if(a<=l && r<=b){
        lazy1[k] = x;
        lazy1_flag[k] = true;
        //eval1(k,l,r);
      }else{
        rangeupdate1(a, b, x, 2*k+1, l, (l+r)/2);
        rangeupdate1(a, b, x, 2*k+2, (l+r)/2, r);
        dat[k] = f(dat[2*k+1], dat[2*k+2]);
      }
      return;
    }

    void rangeupdate1(ll a, ll b, DATA x){
      rangeupdate1(a,b,x,0,0,n);
    }

    //[a,b)の範囲に対してxを作用させる
    void rangeupdate2(ll a, ll b, DATA x, ll k, ll l, ll r){

      eval2(k,l,r);

      if(r<=a || b<=l) return;

      if(a<=l && r<=b){
        lazy2[k] = f(lazy2[k], x);
        lazy2_flag[k] = true;
        eval2(k,l,r);
      }else{
        rangeupdate2(a, b, x, 2*k+1, l, (l+r)/2);
        rangeupdate2(a, b, x, 2*k+2, (l+r)/2, r);
        dat[k] = f(dat[2*k+1], dat[2*k+2]);
      }

      return;
    }

    void rangeupdate2(ll a, ll b, DATA x){
      rangeupdate2(a,b,x,0,0,n);
    }

    // search the minimum of [a, b)
    // Other values are used for simply
    // From outside, call query(a, b, 0, 0, n)
    // k is the node index, 
    // temporary block is [l, r)
    DATA query(ll a, ll b, ll k, ll l, ll r){
      //if there are no overlap between [a, b) and [l, r)
      if(r<=a || b<=l) return init;

      eval1(k,l,r);
      eval2(k,l,r);

      //if [a, b) contains [l, r), return the value of this node
      if(a<=l && r<=b) return dat[k];

      DATA vl = query(a, b, k*2+1, l, (l+r)/2);
      DATA vr = query(a, b, k*2+2, (l+r)/2, r);
      return f(vl, vr);
    };

    // search the minimum of [a, b)
    DATA query(ll a, ll b){
      if(a<0 || n_<b || a==b){
        fprintf(stderr, "Segment_Tree Search Space Error\n");
        fprintf(stderr, "Desired:\n");
        fprintf(stderr, "%lld <= %lld < %lld <= %lld\n", 0, a, b, n_);
        exit(0);
      }
      return query(a, b, 0, 0, n);
    };
};



