void solve() {
  ini(N);
  vi a(N);
  in(a);

  map<int,vi> m;
  rep(i , N){
    m[a[i]].push_back(i);
  }

  vl ans(N);
  while(sz(m) != 1){
    auto bac = --m.end();
    auto pre = --(--m.end());

    // 後ろを前にマージする
    ll val = bac->first - pre->first;
    ans[bac->second[0]] += val * sz(bac->second);

    // マージテク
    if(sz(bac->second) > sz(pre->second))
      swap(bac->second , pre->second);
    while(!(bac->second).empty()){
      pre->second.eb(bac->second.back());
      bac->second.pop_back();
    }
    sort(all(pre->second));
    m.erase(bac);
  }

  ans[0] += m.begin()->first * N;

  each(x,ans) out(x);

}

