		rs[nrt]=rs[rt];
		add(ls[rt],ls[nrt],l,mid,x,k);
	}else{
		rs[nrt]=++tot;
		ls[nrt]=ls[rt];
		add(rs[rt],rs[nrt],mid+1,r,x,k);
	}
}
long long query(int lrt,int rrt,int l,int r,int x,int y)
{
	if(y<x)return 0;
	if(x<=l&&r<=y)return s[rrt]-s[lrt];
	int mid=(l+r)>>1;long long tmp=0;
	if(x<=mid)tmp=query(ls[lrt],ls[rrt],l,mid,x,y);
	if(y>mid)tmp+=query(rs[lrt],rs[rrt],mid+1,r,x,y);
	return tmp;
}
