const int maxn = 1e5 + 228;

vector<int> tree[4 * maxn];
vector<int64_t> tree2[4 * maxn];
vector<int> in;

void build(int node, int node_l, int node_r) {
    if (node_l == node_r - 1)
        tree[node] = {in[node_l]};
    else {
        int mid = node_l + (node_r - node_l) / 2;
        build(2 * node + 1, node_l, mid);
        build(2 * node + 2, mid, node_r);

        tree[node].resize(node_r - node_l);
        std::merge(ALL(tree[2 * node + 1]), ALL(tree[2 * node + 2]), tree[node].begin());
    }

    tree2[node].resize(node_r - node_l + 1);
    for (int i = 0; i != node_r - node_l; ++i)
        tree2[node][1 + i] = tree2[node][i] + tree[node][i];
}

int64_t count(int node, int node_l, int node_r, int l, int r, int x0, int x1) {
    if (l <= node_l and node_r <= r) {
        int p0 = std::lower_bound(ALL(tree[node]), x0) - tree[node].begin();
        int p1 = std::upper_bound(ALL(tree[node]), x1) - tree[node].begin();
        return (tree2[node][p1] - tree2[node][p0]) - (x0 - 1) * 1ll * (p1 - p0) + (SZ(tree[node]) - p1) * 1ll * (x1 - x0 + 1);
    }
    if (node_r <= l or r <= node_l)
        return 0;
    int mid = node_l + (node_r - node_l) / 2;
    return count(2 * node + 1, node_l, mid, l, r, x0, x1)
         + count(2 * node + 2, mid, node_r, l, r, x0, x1);
}

