    int mx = 0;
    for (int i = 0; i != SZ(in); ++i) {
        int ans = 0;
        if (in[i] > mx) {
            ans = count(0, 0, SZ(in), i, SZ(in), mx + 1, in[i]);
            mx = in[i];
        }

        cout << ans << "\n";
    }


    return 0;
}

