class Mountain
{
    public:
    ll number_of_stones;
    ll mountain_number;
};

void ALLIN_MOUNTAINS(int N, vector<Mountain>& mountains)
{
    for(ll i=0;i<N;i++)
    {
        cin >> mountains[i].number_of_stones;
        mountains[i].mountain_number = i+1;
    }
}

void Sort_Mountains_DownUp(vector<Mountain>& mountains)
{
    sort(ALL(mountains),
    [](Mountain& A, Mountain& B)
    {
        return (A.number_of_stones==B.number_of_stones) ? (A.mountain_number < B.mountain_number) : (A.number_of_stones > B.number_of_stones);
    });
}

void Sort_Mountains_DownDown(vector<Mountain>& mountains)
{
    sort(ALL(mountains),
    [](Mountain& A, Mountain& B)
    {
        return (A.number_of_stones==B.number_of_stones) ? (A.mountain_number > B.mountain_number) : (A.number_of_stones > B.number_of_stones);
    });
}

void ALLOUT_MOUNTAINS(vector<Mountain> mountains)
{
    for(auto x : mountains)
    {
        cout << x.number_of_stones << ' ' << x.mountain_number << endl;
    }
}

vector<ll> Decreasing_subsequence(ll N, vector<Mountain> mountains)
{
    vector<ll> ret = {mountains[0].mountain_number};
    for(ll i=1;i<N;i++)
    {
        if(ret[ret.size()-1]>mountains[i].mountain_number)
        {
            ret.push_back(mountains[i].mountain_number);
        }
    }
    return ret;
}

vector<ll> Ruisekiwa(ll N, vector<Mountain> mountains)
{
    vector<ll> ret(N);
    ret[0] = mountains[0].number_of_stones;
    for(ll i=1;i<N;i++)
    {
        ret[i] = mountains[i].number_of_stones + ret[i-1];
    }
    return ret;
}

void Counter(ll N, vector<Mountain> mountains, vector<ll> dec_sub, vector<ll> Rui)
{
    ll dec_itr = 0;

    vector<ll> height(dec_sub.size()+1);
    height[dec_sub.size()] = 0;

    for(ll i=0;i<N;i++)
    {
        if(dec_sub[dec_itr] == mountains[i].mountain_number)
        {
            height[dec_itr] = mountains[i].number_of_stones;
            dec_itr++;
        }
    }

    dec_itr = 0;
    Sort_Mountains_DownDown(mountains);

    vector<ll> kyokai;

    for(ll i=0;i<N;i++)
    {
        if(mountains[i].mountain_number == dec_sub[dec_itr])
        {
            kyokai.push_back(i);
            dec_itr++;
        }
    }
    kyokai.push_back(0);

    vector<ll> ret_vec;
    for(ll i=0;i<dec_itr;i++)
    {
        ret_vec.push_back(Rui[kyokai[i+1]-1] - height[i+1] * (kyokai[i+1]));
    }
    ret_vec[ret_vec.size()-1] = Rui[Rui.size()-1];

    for(ll i=dec_itr-1;i>=1;i--)
    {
        ret_vec[i] -= ret_vec[i-1];
    }

    map<ll,ll> ret_map;
    for(ll i=0;i<dec_itr;i++)
    {
        ret_map[dec_sub[i]] = ret_vec[i];
    }
    for(ll i=1;i<=N;i++)
    {
        cout << ret_map[i] << endl;
    }
} 

int main()
{
    ll N;
    cin >> N;

    vector<Mountain> mountains(N);
    ALLIN_MOUNTAINS(N,mountains);
    Sort_Mountains_DownUp(mountains);

    vector<ll> dec_sub = Decreasing_subsequence(N,mountains);

    vector<ll> Rui = Ruisekiwa(N,mountains);

    Counter(N,mountains,dec_sub,Rui);

    return 0;
}

