int compare_num(const void *a, const void *b) {
	struct number_t *A = (struct number_t *)a;
	struct number_t *B = (struct number_t *)b;
	if(A->num - B->num >0){
		return 1;
	}else if(A->num - B->num >0){
		return -1;
	}else{
		return 0;
	}
}


int compare_idnum(const void *a, const void *b) {
	struct number_t *A = (struct number_t *)a;
	struct number_t *B = (struct number_t *)b;
	return A->idnum - B->idnum;
}


