class BIT{
public:
  ll n,bit[555555];
  BIT(){fill(bit,bit+555555,0);}
  void add(ll i,ll x){
    while(i<=n){
      bit[i]+=x;
      i+=i&-i;
    }
  }
  ll sum(ll i){
    ll s=0;
    while(i>0){
      s+=bit[i];
      i-=i&-i;
    }
    return s;
  }
};

void Main() {
  ll n;
  R n;
  ll a[n];
  rep(i,n) R a[i];
  ll d[n];
  d[0]=0;
  REP(i,1,n) {
    d[i]=d[i-1];
    if(a[i]>a[d[i-1]]) d[i]=i;
  }
  ll c[n];
  mem(c);
  BIT b=BIT();
  b.n=n;
  priority_queue<P> que;
  ll sum=0,cnt=0;
  rrep(i,n) {
    que.push(P(a[i],i));
    if(d[i]!=i) continue;
    while(!que.empty()&&(!i||que.top().F>=a[i])) {
      P p=que.top();que.pop();
      b.add(p.S+1,p.F);
      cnt++;
    }
    c[i]=b.sum(n)-sum;
    if(i) c[i]-=a[d[i-1]]*cnt;
    sum+=c[i];
  }
  rep(i,n) pr(c[i]);
}

