void add(int id, int u, ll v) {
  while (u <= lv) {
    s[id][u] += v;
    u += u & -u;
  }
}

ll get(int id, ll u) {
  ll res = 0;
  while (u) {
    res += s[id][u];
    u -= u & -u;
  }
  return res;
}

