int n;
ll ans[MAXN];
std::priority_queue<PLI, std::vector<PLI>, std::greater<PLI> > pq;

int main(){
	scanf("%d", &n);
	for(int i = 1; i <= n; ++ i){
		ll ai;
		scanf("%lld", &ai);
		pq.push({ai, i});
	}
	ll delta = 0;
	while(!pq.empty()){
		auto u = pq.top();
		while(u.first == delta){
			pq.pop();
			u = pq.top();
		}
		ans[u.second] = (u.first - delta) * pq.size();
		delta = u.first;
		pq.pop();
	}
	for(int i = 1; i <= n; ++ i){
		printf("%lld\n", ans[i]);
	}
	return 0;
}

