int N;
vector<int> A;
vector<int> sorted;
vector<long long> suffix_sums;

long long count_between(int before, int now) {
    int first = lower_bound(sorted.begin(), sorted.end(), before) - sorted.begin();
    int second = lower_bound(sorted.begin(), sorted.end(), now) - sorted.begin();
    long long first_half = suffix_sums[first] - suffix_sums[second];
    long long second_half = (long long) (N - second) * now;
    return first_half + second_half - (long long) (N - first) * before;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    A.resize(N);

    for (int &a : A)
        cin >> a;

    sorted = A;
    sort(sorted.begin(), sorted.end());
    suffix_sums.assign(N + 1, 0);

    for (int i = N - 1; i >= 0; i--)
        suffix_sums[i] = suffix_sums[i + 1] + sorted[i];

    vector<long long> answers(N, 0);
    int maximum = 0;

    for (int i = 0; i < N; i++)
        if (A[i] > maximum) {
            answers[i] = count_between(maximum, A[i]);
            maximum = A[i];
        }

    for (int i = 0; i < N; i++)
        cout << answers[i] << (i < N - 1 ? ' ' : '\n');
}

