const int maxn = 1e5 + 10;
typedef long long ll;
int n;
int a[maxn];
ll ans[maxn];
struct Node
{
	int val, pos, cnt;
	Node & operator += (const Node & rhs)
	{
		pos = min(pos, rhs.pos);
		cnt += rhs.cnt;
		return *this;
	}
}b[maxn];
bool cmp(const Node & a, const Node & b) { return a.val < b.val;}
int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i) 
	{
		scanf("%d", &a[i]);
		b[i].val = a[i];
		b[i].pos = i;
		b[i].cnt = 1;
	}
	sort(b + 1, b + n + 1, cmp);
	int tot = 1;
	for(int i = 2; i <= n; ++i)
		if(b[i].val != b[tot].val)
			b[++tot] = b[i];
		else
			b[tot] += b[i];
	for(int i = tot; i; --i)
	{
		ans[b[i].pos] += 1ll * b[i].cnt * (b[i].val - b[i - 1].val);
		b[i - 1] += b[i];
	}
	for(int i = 1; i <= n; ++i)
		printf("%lld\n", ans[i]);
	return 0;
}

