using namespace std;

using I = long long;

int main() {
  int N;
  cin >> N;
  vector<I> A(N);
  for(auto& i: A) cin >> i;

  auto M = 1e9 + 1;
  SegmentTree<I> T(M, 1e18);
  vector<I> high(N);
  for(auto i=N-1; 0<=i; --i) {
    high[i] = T.sum(A[i], M);
    T.add(1, A[i]+1, 1);
  }

  // for(auto i:A)cout<<" "<<i;cout<<endl;
  // for(auto i:high)cout<<" "<<i;cout<<endl;

  vector<I> ans(N);
  I pa = 0, px = N, sum = 0;
  vector<pair<I,int>> Q;
  for(auto i=0; i<N; ++i) Q.emplace_back(A[i], i);
  sort(begin(Q), end(Q), [](auto l, auto r) {return (l.first!=r.first) ? l.first>r.first : l.second<r.second;});
  Q.erase(unique(begin(Q), end(Q), [](auto l, auto r) {return l.first==r.first;}), end(Q));
  for(auto i=0; i<Q.size(); ++i) {
    auto a = Q[i].first;
    auto x = Q[i].second;
    if(px < x) continue;
    if(i) {
      auto d = pa - a;
      ans[px] += d;
      sum += d;
    }
    ans[x] += high[x] - sum;
    sum = high[x];
    pa = a;
    px = x;
    // cout<<a<<","<<x<<endl;
    // for(auto i:ans)cout<<" "<<i;cout<<endl;
  }
  ans[px] += pa;
  for(auto i: ans) cout << i << endl;
}

