int main()
{
	uint N;
	vector<uint> a;
	vector<uint> answer;

	cin >> N;

	answer.resize(N, 0);

	for(int i = 0; i < N; i++)
	{
		uint u;
		cin >> u;
		a.push_back(u);
	}

	int max = 0;

	for(uint i = 0; i < N; i++)
	{
		uint count = 0;
		if(max >= a[i])
		{
			answer[i] = 0;
			continue;
		}

		count = a[i] - max; 
		for(uint j = i+1; j < N; j++)
		{
			if(a[j] > max)
			{
				count += MIN(a[i] - max, a[j] - max);
			}
		}
		answer[i] = count;
		max = a[i];
	}

	for(uint i = 0; i < N; i++)
	{
		cout << answer[i] << endl;
	}

	return 0;
}

