using namespace std;

int max_i(const vector< pair<long, int> > &v, int start, int end)
{
  long max = 0;
  int ret = 0;
  for (int i = start; i < end; i++) {
    if (max < v[i].first) {
      max = v[i].first;
      ret = i;
    }
  }
  return ret;
}

long sum_up(vector< pair<long, int> > &v, int start, long up)
{
  long sum = v[start].first - up * v[start].second;
  v[start].first = up * v[start].second;
  for (vector< pair<long, int> >::iterator it = v.begin() + start + 1; it != v.end(); it++) {
    if (it->first > up * it->second) {
      sum += it->first - up * it->second;
      v[start].first += up * it->second;
      v[start].second += it->second;
      it = v.erase(it) - 1;
    }
  }
  return sum;
}

int main()
{
  int N;
  cin >> N;

  vector< pair<long, int> > a(N);
  vector<long> s(N);
  for (int i = 0; i < N; i++) {
    cin >> a[i].first;
    a[i].second = 1;
    s[i] = 0;
  }

  int spot = max_i(a, 0, N);
  int target = max_i(a, 0, spot);
  while(spot != 0) {
    s[spot] = sum_up(a, spot, a[target].first);
    spot = target;
    target = max_i(a, 0, spot);
  }

  s[0] = sum_up(a, 0, 0);
  for (int i = 0; i < N; i++) {
    cout << s[i] << endl;
  }
  return 0;
}

