    for(ll i=1; i<=N; ++i) {
        ll a;
        cin >> a;
        same[a]++;
        nextN.insert(a);
        pos[a] = pos[a] <= 0 ? i : min(pos[a], i);
    }
    auto it = nextN.begin();
    while(it != nextN.end()) {
        auto forward = it;
        ++forward;
        if(forward != nextN.end()) {
            dp[pos[*it]] = same[*it] * (*it - *forward);
            same[*forward] += same[*it];
            pos[*forward] = min(pos[*forward], pos[*it]);
        } else {
            dp[pos[*it]] = same[*it];
        }
        ++it;
    }
    for(ll i=1; i<=N; ++i) {
        printf("%lld\n", dp[i]);
    }

    return 0;
}

