int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  ll n;
  std::cin>>n;

  struct Rock{
    ll num,cnt,itr;
    Rock(ll a,ll b,ll c):num(a),cnt(b),itr(c){}
  };

  auto comp=[](const Rock& a,const Rock& b){
    if(a.num!=b.num)return a.num<b.num;
    return a.itr>b.itr;
  };

  std::priority_queue<Rock,std::vector<Rock>,decltype(comp)> que(comp);

  rep(i,0,n){
    ll a;
    std::cin>>a;
    que.emplace(a,1,i);
  }

  std::vector<ll> ans(n,0);

  while(!que.empty()){
    auto now=que.top();que.pop();
    while(!que.empty()&&que.top().num==now.num){
      auto tmp=que.top();que.pop();
      now.cnt+=tmp.cnt;
    }
    if(!que.empty()){
      ans[now.itr]+=now.cnt*(now.num-que.top().num);
      now.num=que.top().num;
      que.emplace(now);
    }else{
      ans[now.itr]+=now.cnt*now.num;
    }
  }

  for(const auto& e:ans)std::cout<<e<<"\n";

  return 0;
}

