const int N = 100010, INF = 0x3f3f3f3f;
int n,a[N],cur,ans[N],rec[N],cnt;
struct node {
  int mx,semx,num,sum,tag;
} t[N << 2];
void puttag(int x,int v) {
  if (v >= t[x].mx) return;
  if (v <= t[x].semx) assert(0);
  t[x].sum -= t[x].num * (t[x].mx - v);
  t[x].mx = v;
  t[x].tag = min(t[x].tag,v);
}
void push_down(int x) {
  puttag(x<<1,t[x].tag);
  puttag(x<<1|1,t[x].tag);
  t[x].tag = INF;
}
void push_up(int x) {
  if (t[x].tag != INF) push_down(x);
  if (t[x<<1].mx > t[x<<1|1].mx) {
    t[x].mx = t[x<<1].mx;
    t[x].num = t[x<<1].num;
    t[x].semx = max(t[x<<1].semx,t[x<<1|1].mx);
  } else if (t[x<<1].mx < t[x<<1|1].mx) {
    t[x].mx = t[x<<1|1].mx;
    t[x].num = t[x<<1|1].num;
    t[x].semx = max(t[x<<1|1].semx,t[x<<1].mx);
  } else {
    t[x].mx = t[x<<1].mx;
    t[x].num = t[x<<1].num + t[x<<1|1].num;
    t[x].semx = max(t[x<<1].semx,t[x<<1|1].semx);
  }
  t[x].sum = t[x<<1].sum + t[x<<1|1].sum;
}
void modify(int l,int r,int v,int x=1,int lp=1,int rp=n) {
  if (l > rp || r < lp) return;
  if (lp >= l && rp <= r && v > t[x].semx)
      return (void)(puttag(x,v));
  push_down(x);
  int mid = (lp + rp) >> 1;
  modify(l,r,v,x<<1,lp,mid);
  modify(l,r,v,x<<1|1,mid+1,rp);
  push_up(x);
}
int query(int l,int r,int x=1,int lp=1,int rp=n) {
  if (l > rp || r < lp) return 0;
  if (lp >= l && rp <= r)
    return t[x].sum;
  push_down(x);
  int mid = (lp + rp) >> 1;
  return query(l,r,x<<1,lp,mid) + query(l,r,x<<1|1,mid+1,rp);
}
void build(int x=1,int lp=1,int rp=n) {
  t[x].tag = INF;
  if (lp == rp) {
    t[x].mx = t[x].sum = a[lp];
    t[x].num = 1;
    t[x].semx = -INF;
    return;
  }
  int mid = (lp + rp) >> 1;
  build(x<<1,lp,mid);
  build(x<<1|1,mid+1,rp);
  push_up(x);
}
signed main() {
  scanf("%lld",&n);
  for (int i = 1 ; i <= n ; ++ i) {
    scanf("%lld",&a[i]);
    if (a[i] > cur) {
      cur = a[i];
      rec[++cnt] = i;
    }
  }
  build();
  for (int i = cnt ; i >= 1 ; -- i) {
    ans[rec[i]] = query(rec[i],n);
    modify(rec[i],n,a[rec[i-1]]);
    ans[rec[i]] -= query(rec[i],n);
  }
  for (int i = 1 ; i <= n ; ++ i)
    printf("%lld\n",ans[i]);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>

int findMax(int N, int* a) {

    int res = N - 1;
    int tmp = a[res];
    for(int i=N-2;i>=0;i--) {
        if(a[i]>=tmp) {
            tmp = a[i];
            res = i;
        }
    }

    return res;
}

int calcUpSum(int N, int* a, int div, int val) {
    int res = 0;
    for(int i=div+1;i<N;i++) {
        if(a[i] > val) {
            res += (a[i] - val);
        }
    }

    return res;
}

void valClrUpper(int N, int* a, int div, int val) {
    for(int i=div+1;i<N;i++) {
        if(a[i] > val) {
            a[i] = val;
        }
    }
}

int main() {

    int N;
    int* a;

    scanf("%d", &N);
    a = (int*)malloc(sizeof(int)*N);
    for(int i=0;i<N;i++) {
        scanf("%d", &a[i]);
    }

    int* res;
    res = (int*)malloc(sizeof(int)*N);
    for(int i=0;i<N;i++) {
        res[i] = 0;
    }

    int x,y;
    while(1) {
        x=findMax(N, a);
        if(a[x] == 0) break;
        y=findMax(x, a);
        printf("(%d,%d)\n", x, a[y]);
        res[x]=calcUpSum(N, a, x, a[y]);
        res[x]+=(a[x]-a[y]);
        a[x]=a[y];
        valClrUpper(N, a, x, a[y]);
    }

    for(int i=0;i<N;i++) {
        printf("%d\n", res[i]);
    }

    free(a);
    free(res);


    return 0;
}

