        if(MAX < a[i]){
            MAX = a[i];
            ind = i;
            vec.push_back(P(a[i], i));
        }
    }
    reverse(vec.begin(), vec.end());
    int n = vec.size();
    int right = N;
    for(int i = 0; i < n - 1; i++){
        P v = vec[i];
        int now = v.second;
        for(int i = now; i < right; i++){
            m[a[i]]++;
        }
        long long nex = vec[i + 1].first;
