vector<ii> vec;
ll ans[100001];

int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	int n; cin>>n;
	vec.resize(n);
	ll sum = 0;
	for(int i = 0; i < n; i++)
	{
		ll x; cin>>x;
		vec[i].fi=x;vec[i].se=i;
		sum+=x;
	}
	sort(vec.begin(),vec.end(),cmp);
	ll weight = 0;
	for(int i = 0; i < vec.size(); i++)
	{
		ll cnt = vec[i].fi; ll idx = vec[i].se;
		if(i+1<vec.size()&&vec[i+1].fi==vec[i].fi)
		{
			weight++;
			continue;
		}
		if(i==int(vec.size()) - 1)
		{
			ans[idx]+=cnt*(weight+1);
			break;
		}
		int ptr = i + 1;
		int nxtval = vec[ptr].fi;
		int ext = 1;
		while(ptr<n&&vec[ptr].fi==nxtval)
		{
			ext++;
			ptr++;
		}
		ptr--;
		ext--;
		if(vec[ptr].se<idx)
		{
			ans[idx]+=(cnt-(nxtval+1))*(weight+1)+1+weight;
			weight++;
			continue;
		}
		ans[idx]+=(cnt-nxtval)*(weight+1);
		vec[ptr].se=idx;
		i=ptr-1;
		weight+=ext;
		continue;
	}
	for(int i=0;i<n;i++)
	{
		cout<<ans[i]<<'\n';
	}
}

