struct SEG{
	ll l;
	ll r;
	ll s;
	ll t;
	bool ch;
	SEG *chl,*chr;
	void init(ll l_,ll r_,ll s_,ll t_){
		l = l_;
		r = r_;
		s = s_;
		t = t_;
		ch = false;
	}
	void mkch(){
		chl = new SEG;
		chl->init(l,(l+r)/2,0,0);
		chr = new SEG;
		chr->init((l+r)/2,r,0,0);
		ch = true;
	}
	void add(ll a,ll b,ll x){
		if(b <= l || r <= a)return;
		if(a <= l && r <= b){
			s += x*(r-l);
			t += x;
			return;
		}
		if(!ch){
			mkch();
		}
		chl->add(a,b,x);
		chr->add(a,b,x);
		s = t*(r-l) + chl->s + chr->s;
	}
	ll sum(ll a,ll b){
		if(b <= l || r <= a)return 0;
		if(a <= l && r <= b)return s;
		if(!ch){
			return t*max((ll)0,min(r,b)-max(l,a));
		}
		return chl->sum(a,b) + chr->sum(a,b) + t*max((ll)0,min(r,b)-max(l,a));
	}
};

