signed main() {
	INIT;
	VAR(int, n);
	VEC(int, a, n);
	std::vector<int> top;
	top.reserve(n);
	int mmax = 0;
	REP(i, n) {
		if (mmax < a[i]) {
			top.emplace_back(i);
			mmax = a[i];
		}
	}
	std::vector<int> b(a);
	std::sort(ALL(b));
	std::vector<int> ans(n, 0);
	int checked = n;
	RREP(i, top.size()) {
		int t = (i == 0) ? 0 : a[top[i - 1]];
		auto it = std::upper_bound(ALL(b), t);
		int l = std::distance(b.begin(), it);
		ans[top[i]] += (n - checked) * (a[top[i]] - t);
		FOR(j, l, checked) {
			ans[top[i]] += b[j] - t;
		}
		checked = l;
	}
	REP(i, n) {
		OUT(ans[i])BR;
	}
	return 0;
}

