const int max_n = 100000;
int n;
int a[max_n+1];
ll ans[max_n+1];

int main() {
  cin >> n;
  for (int i = 1; i <= n; ++i) cin >> a[i];

  vector<pll> vp(n);
  for (int i = 1; i <= n; ++i) {
    vp[i-1].fi = a[i]; vp[i-1].sc = i;
  }
  sort(all(vp));
  reverse(all(vp));


  ll sum = 0;
  int i = 0;
  while (i != n-1 && vp[i].fi == vp[i+1].fi) ++i;

  if (i == n-1) {
    ans[vp[i].sc] = vp[i].fi * n;
  }

  while (i != n-1) {
    sum = vp[i].fi * (i+1);
    int t = i+1;

    while (true) {
      while (t != n-1 && vp[t].fi == vp[t+1].fi) { 
        sum += vp[t].fi;
        ++t;
      }
      sum += vp[t].fi;
      if (t == n-1) break;
      if (vp[t].sc < vp[i].sc) break;
      ++t;
    }

    if (t == n-1) {
      if (vp[i].sc > vp[t].sc) {
        ans[vp[i].sc] = sum - vp[t].fi*(t+1);
        ans[vp[t].sc] = vp[t].fi * n;
        break;
      } else {
        ans[vp[i].sc] = sum;
        break;
      }
    }

    ans[vp[i].sc] = sum - vp[t].fi * (t+1);
    i = t;
  }

  for (int i = 1; i <= n; ++i) {
    cout << ans[i] << endl;
  }

  return 0;
}

