vector<uint64_t> answer;
// mountains[stone_num] = pair<min_mountain_id, mountain_count>
map<uint64_t, pair<uint64_t, uint64_t>, greater<uint64_t> > mountains;


void count()
{
  while (true) {
    auto it = mountains.begin();
    auto stone_num = it->first;
    auto m_id = it->second.first;
    auto mountain_num = it->second.second;
    it = mountains.erase(it);

    if (it == mountains.end()) {
      answer[m_id] += stone_num * mountain_num;
      return;
    }

    auto stone_diff = stone_num - it->first;
    answer[m_id] += mountain_num * stone_diff;

    if (m_id < it->second.first)
      it->second.first = m_id;
    it->second.second += mountain_num;
  }
}


int main()
{
  uint64_t n;
  cin >> n;
  answer.reserve(n);

  for (uint64_t i=0; i<n; ++i) {
    answer.push_back(0);

    uint64_t s;
    cin >> s;
    auto it = mountains.find(s);
    if (it == mountains.end())
      mountains.emplace(s, make_pair(i, 1));
    else
      it->second.second += 1;
  }

  count();

  for (const auto a : answer) {
    cout << a << endl;
  }

  return 0;
}

