void solve(long long N, vector<int> A){

    map<LL, LL> height_count;
    map<int, int> height_leftidx;
    FOR(i, 0, N) {
        LL h = A[i];
        if (height_count[h] == 0) {
            height_leftidx[h] = i;
        }
        height_count[h]++;
    }
    height_count[0] = 1;

    vector<int> height;
    FOE(p, height_count) {
        height.push_back((int)p.first);
    }
    sort(RALL(height));

    int min_idx = height_leftidx[height[0]];
    vector<LL> ans(N);
    FOR(i, 0, height.size() - 1) {
        int h1 = height[i];
        int h2 = height[i + 1];

        min_idx = min(min_idx, height_leftidx[h1]);

        ans[min_idx] += height_count[h1] * (h1 - h2);
        height_count[h2] += height_count[h1];
    }

    FOR(i, 0, N) {
        cout << ans[i] << endl;
    }
}

