int main() {
	const auto n = IO.input<uint32>();
	std::vector<uint32> a(n);
	for (auto &e : a)IO >> e;
	Compress<std::pair<uint32, uint32>> c;
	{
		uint32 cur = 0;
		for (const auto i : irange<>(0, n))
			if (smaxi(cur, a[i]))
				c.emplace(a[i], i);
	}
	c.emplace(0, 0);
	c.build();
	std::vector<uint64> imos(c.size(), 0);
	std::vector<uint64> ans(n, 0);
	for (const auto e : a) {
