	}

	for (const auto i : irange<>(0, c.size() - 1).rev())
		imos[i] += imos[i + 1];

	for (const auto i : irange<>(1, c.size())) {
		ans[c[i].second] += imos[i-1] * (c[i].first - c[i - 1].first);
	}
