void update(int d,LL x){
  int i=d+start;
  segt[i]=x;
  while(par(i)!=-1){
    segt[par(i)]=max(segt[i],segt[(i+1)/2*4-1-i]);
    i=par(i);
  }
  i=0;
  while(i<start){
    i=(segt[i]==segt[2*i+1])?2*i+1:2*i+2;
  }
  best=i-start;
}

void init(int n){
  while((1<<depth)<n){
    depth++;
  }
  start=(1<<depth)-1;
  REP(i,1<<(depth+1)){
    if(i<start)
      segt[i]=0;
    else if(i<start+n)
      segt[i]=input[i-start];
    else
      segt[i]=-LLONG_MAX;
  }
  FOR(i,start,start+n){
    int tmp=i;
    while(par(tmp)!=-1){
      segt[par(tmp)]=max(segt[tmp],segt[(tmp+1)/2*4-1-tmp]);
      tmp=par(tmp);
    }
  }
  int i=0;
  while(i<start){
    i=(segt[i]==segt[2*i+1])?2*i+1:2*i+2;
  }
  best=i-start;
}

