class SegmentTree{
  int n;
  vp node;
  vl val;
public:
  SegmentTree(int n_, vl a){
    n=1;
    while(n<n_)n*=2;
    node = vp(2*n-1, pll(0,0));
    val = a;
  }

  void add(int k, ll v){
    int cur = k + n-1;
    node[cur].fs += v*val[k];
    node[cur].sc += v;
    while(cur>0){
      cur = (cur-1)/2;
      node[cur].fs = node[cur*2+1].fs + node[cur*2+2].fs;
      node[cur].sc = node[cur*2+1].sc + node[cur*2+2].sc;
    }
  }

  //return maximum value in [a,b). ( [l,r) is interval in which k is.)
  pll rangeSum(int a,int b,int k=0,int l=0,int r=0){
    if(l>=r)r = n;
    if(r<=a || b<=l) return pll(0,0);
    if(a<=l && r<=b) return node[k];
    pll vl = rangeSum(a,b,2*k+1,l,(l+r)/2);
    pll vr = rangeSum(a,b,2*k+2,(l+r)/2,r);
    return pll(vl.fs + vr.fs, vl.sc + vr.sc);
  }
};

