// Binary Indexed Tree
struct bit {
  typedef ll TT;
  int n; vector<TT> d;
  vi e;
  bit() {}
  bit(int mx): n(mx), d(mx), e(mx) {}
  void add(int i, TT x=1) {
    for (++i;i<n;i+=i&-i) d[i] += x, ++e[i];
  }
  int y;
  TT sum(int i) {
    TT x = 0; y = 0;
    for (++i;i;i-=i&-i) x += d[i], y += e[i];
    return x;
  }
};
