		}
		f = query(bit1, e) - query(bit1, fin[d]);
		g = query(bit2, e) - query(bit2, fin[d]);
		h = f - g * ini[d] - m;
		freq[c] = h; m += h;
	}
	for (i = 1; i <= a; i++) {
		printf("%lld\n", freq[i]);
	}
	return 0;
}

