#include <bits/stdc++.h>
using namespace std;

map<int, pair<int, int>> st;
long long ans[100005];

int main()
{
	int n;
	scanf("%d", &n);
	for (int i = 1; i <= n; i++)
	{
		int tmp;
		scanf("%d", &tmp);
		auto &&p = st[tmp];
		p.second++;
		if (p.first == 0) p.first = i;
		else p.first = min(p.first, i);
	}

	while (st.rbegin()->second.first != 1)
	{
		auto ri1 = st.rbegin();
		auto ri2 = next(ri1);
		int diff = ri1->first - ri2->first;
		ans[ri1->second.first] += diff * 1ll * ri1->second.second;
		ri2->second.second += ri1->second.second;
		ri2->second.first = min(ri2->second.first, ri1->second.first);
		st.erase(prev(st.end()));
	}

	for (auto &&e : st)
	{
		ans[1] += e.second.first * 1ll * e.second.second;
	}

	for (int i = 1; i <= n; i++) printf("%lld\n", ans[i]);
}

