struct BIT {
  LL val[N];
  inline int lowbit(int x) {
    return x & (-x);
  }
  void add(int p, LL v) {
    while (p <= m) {
      val[p] += v;
      p += lowbit(p);
    }
  }
  LL sum(int p) {
    LL ret = 0;
    while (p) {
      ret += val[p];
      p -= lowbit(p);
    }
    return ret;
  }

