#define b second
LL ans[101010];

struct Mt{
    int c; // 石の個数.
    int i; // 山の番号.
    bool operator < (const Mt &rhs) const {
        return (c < rhs.c) || ((c == rhs.c) && (i > rhs.i));
    }
};

int main(){

    // 1. 入力情報.
    int N, a;
    scanf("%d", &N);
    priority_queue<Mt> pq;
    Mt mt;
    map<LL, LL> m;
    rep(i, N){
        scanf("%d", &a);
        mt.c = a;
        mt.i = i + 1;
        pq.push(mt); // {石の個数, 山の番号}
        m[mt.c]++;
    }

    // 2. 番兵.
    mt.c = 0;
    mt.i = 0;
    pq.push(mt);
    m[0] = 0;

    // 3. 累積和.
    LL t = 0;
    map<LL, LL> sCum;
    map<LL, LL>::reverse_iterator it;
    for(it=m.rbegin(); it!=m.rend(); ++it){
        t += it->b;      // 山の個数.
        sCum[it->a] = t; // 累積和を保存.
    }
    sCum[0] = 0; // 番兵分は, 除外.
    // for(auto &p : sCum) printf("key=%lld val=%lld\n", p.a, p.b);

    // 4. 集計.
    // 石の個数が変化したら, 山の番号を確認し, 減少していたら更新.
    LL cur = 0, bef = 0, idx = 101010;
    while(!pq.empty()){
        // 4-1. 要素を一つ取得.
        Mt m = pq.top();
        pq.pop();

        // 4-2. 現在の石の個数を取得.
        cur = (LL)m.c;

        // 4-3. 初回設定.
        if(idx == 101010) idx = m.i;

        // 4-4. 前回と変わっていたら, 更新.
        if(cur != bef){
            // 石の個数をカウント.
            ans[idx] += (bef - cur) * sCum[bef];

            // 山の番号を更新.
            if(idx > m.i) idx = m.i;
        }

        // 4-5. 前回分更新.
        bef = cur;
        // printf("c=%d i=%d\n", m.c, m.i);
    }

    // 5. 出力.
    repx(i, 1, N + 1) printf("%lld\n", ans[i]);
    return 0;

}

