struct BIT {
	int n;
	vector<int>bit, ko;
	BIT(int x) {
		n = x; bit.resize(n, 0); ko.resize(n, 0);
	}
	int sum(int x) {
		int s = 0;
		while (x > 0) {
			s += bit[x]; x -= x & -x;
		}
		return s;
	}
	int kosum(int x) {
		int s = 0;
		while (x > 0) {
			s += ko[x]; x -= x & -x;
		}
		return s;
	}
	void add(int x, int y) {
		while (x <= n) {
			ko[x]++;
			bit[x] += y; x += x & -x;
		}
	}
	int secsum(int l, int r) {
		return sum(r) - sum(l - 1);
	}
	int kosecsum(int l, int r) {
		return kosum(r) - kosum(l - 1);
	}
};
struct info {
	int type, index, x;
	bool operator<(info& a)const {
