int main()
{
	int n;
	while(~scanf("%d",&n))
	{
		memset(idx,-1,sizeof idx);
		memset(num,0,sizeof num);
		memset(flag,0,sizeof flag);
		for(int i=1;i<=n;i++)
		{
			scanf("%lld",&arr[i].v);
			arr[i].x=i;
		}
		sort(arr+1,arr+1+n,cmp);
		arr[0].v=-1;
		int cnt=0;
		//idx[cnt] = arr[1].x;
		for(int i=1;i<=n;i++)
		{
			if(arr[i-1].v!=arr[i].v)
			{
				cnt++;
				idx[cnt]=arr[i].x;
				num[cnt]=1;
				val[cnt]=arr[i].v;
			}
			else 
			num[cnt]++;
		}
		for(int i=1;i<cnt;i++)
		{
			flag[idx[i]]+=num[i]*(val[i]-val[i+1]);
			idx[i+1]=min(idx[i],idx[i+1]);
			num[i+1]+=num[i];
		}
		flag[idx[cnt]]+=num[cnt]*val[cnt];
		for(int i=1;i<=n;i++)
		printf("%lld\n",flag[i]);
	}
	return 0;
