        }
        for(int i = c.size() - 3 ; i >= 0 ; --i){
            id[i] = min(id[i], id[i + 1]);
        }

        SegmentTree<lint, lint> sum(c.size() - 1, [](lint l, lint r){ return l + r; }, [](lint l, lint r){ return l + r; }, 0LL);

        vector<lint> ans(n, 0LL);
        int k = n - 1;
        for(int i = c.size() - 2 ; i >= 0 ; --i){
