template <class T>
struct BIT {
	int n;
	vector<T> x;
	BIT(int n_ = 0) : n(n_), x(n + 1, 0) {}
	int size() const { return n; }
	T sum(int r) const {
		T S = 0;
		for(r = r - 1; r >= 0; r = (r & (r + 1)) - 1) S += x[r];
		return S;
	}
	T sum(int l, int r) const { return sum(r) - sum(l); }
	void add(int k, const T &a) {
		for(; k < n; k |= k + 1) x[k] += a;
	}
	void set(int k, const T &a) { add(k, a - sum(k, k + 1)); }
	int lower_bound(T x) {
		int ng = -1, ok = n - 1;
		while(abs(ng - ok) > 1) {
			int mid = (ng + ok) / 2;
			if(sum(0, mid + 1) >= x) ok = mid;
			else ng = mid;
		}
		return ok;
	}
};


BIT<ll> bit(100000);
ll a[100000];
ll ans[100000];

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;

	priority_queue<P, vector<P>, greater<P>> q;
	for(int i = 0; i < N; i++) {
		cin >> a[i];
		q.push({ a[i], i });
		bit.add(i, 1);
	}

	ll h = 0;
	for(int i = 0; i < N; i++) {
		if(a[i] < h) continue;
		ll sum = 0;

		while(q.size() && q.top().first <= a[i]) {
			ll b = q.top().first, idx = q.top().second;
			q.pop();
			sum += b - h;
			bit.add(idx, -1);
		}
		sum += bit.sum(i, N) * (a[i] - h);
		ans[i] = sum;
		h = a[i];
	}

	for(int i = 0; i < N; i++) {
		cout << ans[i] << endl;
	}
}

