void updatesum(int i, int val)
{
    while (i <= N)
    {
        T[i] += val;
        i += i & -i;
    }
}

int getsum(int i)
{
    int res = 0;
    while (i > 0)
    {
        res += T[i];
        i -= i & -i;
    }
    return res;
}

void updatenum(int i, int val)
{
    while (i <= N)
    {
        num[i] += val;
        i += i & -i;
    }
}

int getnum(int i)
{
    int res = 0;
    while (i > 0)
    {
        res += num[i];
        i -= i & -i;
    }
    return res;
}

