	St(int i, int a)
	{
		this->i = i;
		this->a = a;
	}

	bool operator < (const St &st) const
	{
		if (a == st.a)
		{
			return i < st.i;
		}
		return a > st.a;
	}
};

vector<St> st;
vector<St> work;
int ans[100000] = { 0 };

signed main()
{
	int min_i = INT_MAX;
	int n;
	cin >> n;
	for (int i = 0; i < n; i++)
	{
		int a;
		cin >> a;
		if (a > 0)
		{
			st.push_back(St(i, a));

			if (i < min_i)
			{
				min_i = i;
			}
		}
	}

	if (st.size() > 0)
	{
		sort(st.begin(), st.end());

		int w = st[0].a;
		work.push_back(st[0]);
		int l = 1;
		for (int i = 1; i < st.size(); i++)
		{
			if (st[i].a < w)
			{
				w = st[i].a;
				work[work.size() - 1].l = l;
				work.push_back(st[i]);
				l = 1;
			}
			else
			{
				l++;
			}
		}
		work[work.size() - 1].l = l;

		int ll = work[0].l;
		for (int i = 0; i < work.size() - 1; i++)
		{
			if (work[i].i == min_i)
			{
				for (int j = 0; j < work.size(); j++)
				{
					ans[min_i] += work[j].a * work[j].l;
				}
				goto ANS;
			}
			ans[work[i].i] = ll * (work[i].a - work[i + 1].a);
			ll += work[i + 1].l;
			work[i].a = work[i + 1].a;
		}
		ans[work[work.size() - 1].i] = ll * (work[work.size() - 1].a);
	}

ANS:
	for (int i = 0; i < n; i++)
	{
		cout << ans[i] << endl;
	}
}

