// 値が大きい順にソート。
// 値が同じ場合は、indexが大きい順にソート
bool SortbyVal(const Idx &a, const Idx &b) {
    if (a.val == b.val) return a.idx > b.idx;
    return a.val > b.val;
}

int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector <Idx> vec(n);
    for (int i = 0; i < n; i++) {
        ll a;
