        vec[i] = (Idx){i, a};
    }

    vec.push_back((Idx){-1, 0LL});
    sort(vec.begin(), vec.end(), SortbyVal);

    vector <ll> ans(n, 0);
    int id = n;
    ll pc = 0, cur = vec[0].val;
    while (pc <= n) {
        if (vec[pc].val == cur) {
            pc++;
            continue;
        }

        id = min(id, vec[pc - 1].idx);
        ans[id] += (cur - vec[pc].val) * pc;
        cur = vec[pc++].val;
    }

    for (ll ret : ans) cout << ret << "\n";
    return 0;
}

