const int N = 1e5 + 5;

ll a[N], b[N], tree_ctr[3*N], tree_sum[3*N], inv[N], ans[N], steps[N];
map <ll, int> m;
set <int> pos[N];

void update(ll *tree, int i, int l, int r, int p, ll x);
ll query(ll *tree, int i, int l, int r, int ql, int qr);

int main()
{
	int n;
	cin >> n;

	int x = 0;
	ll sum = 0;
	for (int i = 1; i <= n; ++i)
	{	
		cin >> a[i];
		b[i] = a[i];
		sum += a[i];
	}

	sort(b + 1, b + n + 1);
	for (int i = 1; i <= n; ++i)
	{
		if (m.find(b[i]) == m.end())
		{
			m[b[i]] = x++;
			inv[x] = b[i];
		}
	}

	for (int i = 1; i <= n; ++i)
		pos[m[a[i]]].insert(i);

	int p = n + 1;
	vector <int> elems;
	for (int i = x - 1; i >= 0; --i)
	{
		if (pos[i].empty())
			continue;

		for (auto &j : pos[i])
		{
			update(tree_ctr, 1, 1, n, j, 1);
			update(tree_sum, 1, 1, n, j, a[j]);
		}

		if (*pos[i].begin() < p)
		{
			elems.pb(*pos[i].begin());
			p = *pos[i].begin();
			steps[p] = query(tree_sum, 1, 1, n, p + 1, n) - a[p] * query(tree_ctr, 1, 1, n, p + 1, n);
		}
	}

	int t = elems.size();
	for (int i = 1; i < t; ++i)
		ans[elems[i - 1]] = steps[elems[i]] - steps[elems[i - 1]];

	ans[elems[t - 1]] = sum - steps[elems[t - 1]];
	for (int i = 1; i <= n; ++i)
		cout << ans[i] << '\n';
}

void update(ll *tree, int i, int l, int r, int p, ll x)
{
	tree[i] += x;
	if (l == r)
		return;

	int mid = (l + r) / 2;
	if (p <= mid)
		update(tree, 2*i, l, mid, p, x);
	else
		update(tree, 2*i + 1, mid + 1, r, p, x);
}

ll query(ll *tree, int i, int l, int r, int ql, int qr)
{
	if (ql > r or qr < l)
		return 0;

	if (ql <= l and r <= qr)
		return tree[i];

	int mid = (l + r) / 2;
	return query(tree, 2*i, l, mid, ql, qr) + query(tree, 2*i + 1, mid + 1, r, ql, qr);
}

