typedef unordered_set<int> llSet;

struct Bit {
  ll sz = (1ll << 18);
  ll tree[(1ll << 18) + 1];
  Bit() {
    for(ll i = 0; i < sz + 1; i++) {
      tree[i] = 0;
    }
  }

  void set(ll v, ll x) {
    while(x <= sz) {
      tree[x] += v;
      x += (x & -x);
    }
  }
  ll getUpTo(ll x) {
    ll ret = 0;
    while(x >= 1) {
      ret += tree[x];
      x -= (x & -x);
    }
    return ret;
  }
};

