int main(){
    vector<LL> ans;
    LL all_cnt = 0;
    vector<pair<LL,int> > memo;
    int n;

    cin >> n;
    REP(i, n){
        LL a;
        cin >> a;
        all_cnt += a;
        memo.PB(MP(a, i));
        ans.PB(0);
    }

    sort(ALL(memo));
    int idx = n;
    LL stone = 0;
    int cnt = 0;
    LL used_stone = 0;
    int insert_index = INF;
    while(true){
        idx--;
        cnt++;
        pair<LL,int> now = memo[idx];
        if(now.second == 0){
            ans[0] = all_cnt - used_stone;
            break;
        }
        insert_index = min(insert_index, now.second);

        pair<LL,int> next = memo[idx-1];
        stone += now.first;
        LL used = stone - cnt * next.first;
        ans[insert_index] += used;
        stone -= used;
        used_stone += used;
    }

    REP(i, n){
        cout << ans[i] << endl;
    }
}

