template<typename T>
struct Segment_Tree {
	typedef function<T(T, T)> F;

	ll n;
	F f;//モノイドとしての演算(最小値、和　など)
	T unit;//単位元

	ll size;
	vector<T> seg;

	Segment_Tree(ll n0, F f0, T unit0) {
		n = n0;
		f = f0;
		unit = unit0;

		size = 1;
		while (size < n) {
			size *= 2;
		}
		seg.assign(2 * size, unit);
	}


	void update(ll k, T x) {//k番目の要素をxに更新
		k += size - 1;
		seg[k] = x;
		while (k > 1) {
			k /= 2;
			seg[k] = f(seg[2 * k], seg[2 * k + 1]);
		}
	}



	T query_prep(ll a, ll b, ll k, ll l, ll r) {//[a,b)とkに対応する区間[l,r)の共通部分でクエリ
		if (b <= l || a >= r) { return unit; }
		if (a <= l && r <= b) { return seg[k]; }

		T v1 = query_prep(a, b, 2 * k, l, (l + r) / 2);
		T v2 = query_prep(a, b, 2 * k + 1, (l + r) / 2, r);
		return f(v1, v2);

	}

	T query(ll a, ll b) {
		return query_prep(a, b, 1, 1, size + 1);
	}

};



int main() {

	ll N;
	cin >> N;

	vector<ll> a(N+1);
	repn(i, N) cin >> a[i];

	vector<pair<ll, ll>> p(N+1);
	repn(i, N)  p[i] = { a[i],i };

	sort(++p.begin(), p.end());

	vector<ll> za(N + 1);//座標圧縮
	repn(i, N) za[p[i].second] = i;

	//repn(i, N) cout << za[i] << endl;

	Segment_Tree<ll> sg(N, [](ll a, ll b) {return a + b; }, 0);

	vector<ll> suf(N + 1);

	for (ll i = N; i >= 1; i--) {
		ll x = sg.query(za[i],za[i] + 1);

		sg.update(za[i], x + 1);

		suf[i] = sg.query(za[i], N + 1);

		//cout << suf[i] << endl;
	}

	vector<ll> mx(N + 1);
	mx[0] = 0;
	repn(i, N) mx[i] = max(mx[i - 1], a[i]);

	vector<ll> ans(N + 1);

	repn(i, N) {
		ans[i]= max(a[i] - mx[i - 1],0)*suf[i];
	}

	ans[1] = 0;
	repn(i, N) ans[1] += a[i];
	for (ll i = 2; i <= N; i++) ans[1] -= ans[i];

	repn(i, N) cout << ans[i] << endl;

	system("PAUSE");

}

