		sum.push_back(make_pair(it->first,it->second));
	}

	for (int i = 1; i < sum.size(); i++) {
		sum[i].second += sum[i - 1].second;
	}

	min_index.push_back(make_pair(0,0));
	sum.push_back(make_pair(0, 0));
	vector<ll>ans(n);
	int j = 0;
	for (int i = 0; i < min_index.size()-1; i++) {
		ll tmp=0;
		while (min_index[i].first != sum[j].first) {
			tmp += sum[j].second * (min_index[i].first - min_index[i + 1].first);
