signed main()
{
    int n, nowmx = 0;
    cin >> n;
    vector<ll> v(n), ans(n, 0);
    vector<int> mx(n, 0);
    rep(i, 0, n)
    {
        cin >> v[i];
        if (nowmx < v[i])
        {
            mx[i] = i;
            nowmx = v[i];
        }
        else
        {
            mx[i] = mx[i - 1];
        }
    }

    int mxi = mx[n - 1], ind = n - 1, nmxi = mxi, cnt = 0, pmxi=0;
    priority_queue<ll> q;
    while (1)
    {

        if (0 < mxi)
        {
            nmxi = mx[mxi - 1];
        }
        else
        {
            while (mxi < ind)
            {
                ans[0]+=v[ind];
                ind--;
            }
            while (!q.empty())
            {
                ans[0] += q.top();
                q.pop();
            }
            ans[0] += v[0];
            ans[0] += (v[mxi]) * cnt;
            break;
        }

        ans[mxi] += (v[mxi] - v[nmxi]) * cnt;

        while (mxi < ind)
        {
            if (v[nmxi] <= v[ind])
            {
                ans[mxi] += v[ind] - v[nmxi];
                cnt++;
            }
            else
            {
                q.push(v[ind]);
            }
            ind--;
        }
        ind--;

        while (!q.empty() && q.top() > v[nmxi])
        {
            ans[mxi] += q.top() - v[nmxi];
            q.pop();
            cnt++;
        }

        ans[mxi] += v[mxi] - v[nmxi];
        cnt++;
        pmxi = mxi;
        mxi = nmxi;
    }

    rep(i, 0, n) cout << ans[i] << endl;
}

