template <typename T=int>
struct BIT {
    const int n;
    vector<T> v;

    BIT(int n): n(n), v(n+1,0) {}

    void add(int i, int x) {
        i += 1;
        while (i <= n) {
            v[i] += x;
            i += i & -i;
        }
    }
    T sum(int i) {
        i += 1;
        T ret = 0;
        while (i > 0) {
            ret += v[i];
            i -= i & -i;
        }
        return ret;
    }
    T sum(int l, int r) {
        return sum(r) - sum(l-1);
    }
};

void solve() {
    int n;
    cin >> n;
    VI a(n);
    REP(i,0,n) cin >> a[i];

    VLL ans(n);
    VI mv(n);
    REP(i,1,n) mv[i] = max(a[i-1], mv[i-1]);

    VI cnt(n);
    BIT<> bit(n);
    VP ps(n);
    REP(i,0,n) {
        ps[i] = MP(i,a[i]);
    }
    sort(all(ps), [](auto &l, auto &r) {
        if (l.second == r.second) return l.first > r.first;
        return l.second > r.second;
    });
    for (auto &p: ps) {
        int idx = p.first;
        bit.add(idx,1);
        cnt[idx] = bit.sum(idx, n-1);
