inline void eval(int n, long sum, const std::vector<int>& a, std::vector<int>& nexists) {
    // 要素数、石の番号のペア
    std::priority_queue<std::pair<int, int>> que;
    std::map<int, int> minNum;

    for (int i = n-1; i >= 0; i--) {
        que.push(std::make_pair(a[i], i));
        minNum[a[i]] = i;
    }

    // 減らす順: 要素数が最大のもの、数が大きいものから
    while (sum) {
        sum--;
        // std::cout << "n: " << n << ", sum: " << sum << std::endl;

        auto pair = que.top();
        que.pop();
        que.push(std::make_pair(pair.first-1, pair.second));

        nexists[minNum[pair.first]]++;

#ifdef DEBUG
        std::cout << minNum[pair.first];
#endif

        // update minNum
        if (minNum.find(pair.first-1) == minNum.end()) {
            minNum[pair.first-1] = pair.second;
        } else {
            minNum[pair.first-1] = std::min(minNum[pair.first-1], pair.second);
        }
    }

#ifdef DEBUG
    std::cout << std::endl;
#endif
}

