struct node {
  int x, y = rand(), s = 1;
  ll sum = 0;
  node* l = 0;
  node* r = 0;

  node(int v) {
    x = v;
    sum = v;
  }

  ~node() {
    delete l;
    delete r;
  }

  void update() {
    s = 1;
    sum = x;
    if(l) {
      s += l->s;
      sum += l->sum;
    }
    if(r) {
      s += r->s;
      sum += r->sum;
    }

  }
};

struct treap {
  node* root = nullptr;

  ~treap() {
    delete root;
  }

  node* join(node* l, node* r) {
    if(!l || !r)
      return l ?: r;
    if(l->y < r->y) {
      l->r = join(l->r, r);
      l->update();
      return l;
    } else {
      r->l = join(l, r->l);
      r->update();
      return r;
    }
  }

  void split(int x, node* p, node*& l, node*& r) {
    l = r = 0;
    if(not p)
      return;

    if(x < p->x) {
      r = p;
      split(x, r->l, l, r->l);
    } else {
      l = p;
      split(x, l->r, l->r, r);
    }
    p->update();
  }

  void insert(int x) {
    node*l,*r;
    split(x, root, l, r);
    root = join(l, join(new node(x), r));
  }

  void remove(int x) {
    node*l,*r,*l2,*l3;
    split(x, root, l, r);
    split(x-1, l, l2, l3);
    if(l3)
      l3 = join(l3->l, l3->r);
    l = join(l2, l3);
    root = join(l, r);
  }

  ll query(int x) {
    node*l,*r;
    split(x, root, l, r);

    ll cnt = r ? r->s : 0;
    ll ans = r ? r->sum : 0;

    root = join(l, r);

    return ans-x*cnt;
  }
};

int a[N];
int st[18][N];

void build() {
  for(int i = 0; i < n; ++i)
    st[0][i] = i;

  for(int j = 1; (1<<j) <= n; ++j) {
    int b = 1 << j-1;
    int lim = b + b -1;

    for(int i = 0; i + lim < n; ++i) {
      int x = st[j-1][i];
      int y = st[j-1][i+b];
      if(x > y) swap(x, y);
      st[j][i] = (a[x] >= a[y]) ? x : y;
    }
  }
}

int query(int l, int r) {
  if(l>r)
    return -1;
  int b = 31 - __builtin_clz(r-l+1);
  int x = st[b][l];
  int y = st[b][r-(1<<b)+1];
  if(x > y) swap(x, y);
  return (a[x] >= a[y]) ? x : y;
}

int main() {
  cin.tie(0);
  cin.sync_with_stdio(0);
  cin >> n;
  for(int i = 0; i < n; ++i)
    cin >> a[i];

  build();
  int in = n-1;
  treap t;
  int l = 0;
  int r = n-1;
  ll prev = 0;

  while(1) {

    int idx = query(l, r);
    int lidx;

    if(idx > 0) {
      while(in >= idx)
        t.insert(a[in--]);
      lidx = query(l, idx-1);
      int mn = a[idx];
      cnt[idx+1] = t.query(a[lidx])-prev;
      prev += cnt[idx+1];
      r = lidx;

    } else {
      lidx = n;
      a[lidx] = 0;
      while(in >= idx)
        t.insert(a[in--]);
      int mn = a[idx];
      cnt[idx+1] = t.query(a[lidx])-prev;
      break;
    }
  }

  for(int i = 1; i <= n; ++i)
    cout << cnt[i] << "\n";
}

