long long bs(int L,int R)
{
    int l=1,r=n,vl,vr;
    while(l<r)
    {
        int mid=(l+r)>>1;
        if(b[mid]>=L) r=mid; else l=mid+1;
    }
    vl=l;
    l=1; r=n;
    while(l<r)
    {
        int mid=(l+r+1)>>1;
        if(b[mid]<=R) l=mid; else r=mid-1;
    }
    vr=l;
    return sum[vr]-sum[vl-1]-L*(vr-vl+1)+(R-L)*(n-vr);
}
