void solve(){
    i64 N;
    cin >> N;
    map<i64,i64> min_idx,count;
    vector<i64> num;
    rep(i,0,N){
        i64 a;
        cin >> a;
        num.push_back(a);
        ++count[a];
        if(min_idx.find(a)==min_idx.end()) min_idx[a]=i;
    }

    sort(num.begin(),num.end());
    num.erase(unique(num.begin(),num.end()),num.end());

    vector<i64> ans(N);
    for(int i=num.size()-1; i>=1; --i){
        i64 d=num[i]-num[i-1];
        ans[min_idx[num[i]]]+=d*count[num[i]];
        min_idx[num[i-1]]=min(min_idx[num[i-1]],min_idx[num[i]]);
        count[num[i-1]]+=count[num[i]];
    }
    ans[min_idx[num[0]]]+=num[0]*count[num[0]];

    rep(i,0,N) cout << ans[i] << endl;
}

