void solve() {
  int n; cin >> n;
  vector<pii> arr(n);
  rep(i,n) {
    int a; cin >> a;
    arr[i] = {a, i};
  }

  sort(RALL(arr));

  arr.emplace_back(0, -1);

  vi ans(n);
  int cnt = 1;
  int idx = 0;
  int pos = n;

  while (idx != n) {
    while (arr[idx].first == arr[idx+1].first) {
      ++idx;
      ++cnt;
    }

    chmin(pos, arr[idx].second);
    ans[pos] += cnt * (arr[idx].first - arr[idx+1].first);

    ++idx;
    ++cnt;
  }

  interval[0] = "\n";
  cout << ans << endl;
}


