    b.erase(unique(b.begin(), b.end()), b.end());
    unordered_map<ll, int> zip;
    for (int i = 0; i < b.size(); i++) {
        zip[b[i]] = i;
    }
    const int size = b.size();
    SegmentTree<Min_Set> seg{size};
    SegmentTree<Sum_Plus> seg2{vector<pair<ll, ll>>(N, pair<ll, ll>{0, 1})};
    for (int i = N - 1; i >= 0; i--) {
        seg.modify(0, zip[a[i]] + 1, i);
        seg2.modify(0, zip[a[i]] + 1, 1);
    }

    vector<int> ans(N, 0);
    int prev_l = 0;
    for (int i = 0; i < size; i++) {
        const int l = b[i];
        const int cnt = seg2.get(i).first;
        const int num = seg.get(i);
        assert(a[num] >= l);
        ans[num] += cnt * (l - prev_l);
