template<typename T>
struct BIT {
	int n;
	vector<T>dat;
	BIT(int n = 0) {
		initialize(n);
	}
	void initialize(int temp) {
		n = temp;
		dat.resize(n);
		rep(i, 0, n)dat[i] = 0;
	}
	T sum(int i) {
		T s = 0;
		while (i >= 0) {
			s += dat[i];
			i = (i & (i + 1)) - 1;
		}
		return s;
	}
	T sum_between(int i, int j) {
		if (i > j)return 0;
		return sum(j) - sum(i - 1);
	}
	void plus(int i, T x) {
		while (i < n) {
			dat[i] += x;
			i |= i + 1;
		}
	}
	int lower_bound(T x) {
		if (sum(n - 1) < x)return -1;
		else if (sum(0) >= x)return 0;
		int ng = 0, ok = n - 1;
		while (ok - ng > 1) {
			int mid = (ok + ng) / 2;
			if (sum(mid) >= x)ok = mid;
			else ng = mid;
		}
		return ok;
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);


	ll N;
	cin >> N;
	vector<ll>a;
	a.resize(N);
	set<ll>li;
	vector<ll>adic;

	ll ma = -1;
	for (int i = 0; i < N; i++) {
		cin >> a[i];
		if (a[i] > ma) {
			li.insert(i);
			ma = a[i];
		}
		adic.pb(a[i]);
	}
	sort(all(adic));
	adic.erase(unique(all(adic)),adic.end());



	ll sz = adic.size();
	BIT<ll>bit(sz);
	BIT<ll>bitsum(sz);
	vector<ll>ans(N);
	for (int i = N-1; i >= 0;i--){
		ll idx = lower_bound(all(adic), a[i]) - adic.begin();
		bit.plus(idx,1);
		bitsum.plus(idx,a[i]);
		if (li.count(i)) {
			li.erase(i);
			if (li.size()) {
				ll idx1 = lower_bound(all(adic), a[i]) - adic.begin();
				auto itr = li.end();
				itr--;
				ll idx2 = lower_bound(all(adic),a[*itr]) - adic.begin();
				ans[i] += (bit.sum_between(idx1,sz-1))*(a[i]-a[*itr]);
				ans[i] += bitsum.sum_between(idx2,idx1-1)-bit.sum_between(idx2,idx1-1)*a[*itr];
			}
			else {
				ll idx1 = lower_bound(all(adic), a[i]) - adic.begin();
				ans[i] += (bit.sum_between(idx1, sz - 1))*a[i];
				ans[i] += bitsum.sum_between(0, idx1 - 1);
			}
		}
	}


	for (int i = 0; i < N; i++)puts(ans[i]);


	return 0;
}

