struct node{
  int idx;
  int size;
  int num;
  node(int i, int s, int n): idx(i), size(s), num(n) {}
};

int main(){
  ll N;
  cin >> N;

  map<int, pair<int,int> > stnmap;
  for(int i=0; i<N; i++){
    int tmp;
    cin >> tmp;
    if(stnmap.find(tmp) == stnmap.end()){
      stnmap[tmp] = make_pair(i,1);
    } else {
      stnmap.at(tmp).second += 1;
    }
  }

  queue<node> q;
  for(auto itr = stnmap.rbegin(); itr!=stnmap.rend(); itr++){
    q.push(node(itr->second.first, itr->first, itr->second.second));
  }

  vector<int> ans(N,0);
  while(!q.empty()){
    node crr = q.front();
    q.pop();
    if(crr.idx==0){
      ans[0] += crr.size * crr.num;
      while(!q.empty()){
        node lp = q.front();
        q.pop();
        ans[0] += lp.size * crr.num;
      }
      break;
    }

    ans[crr.idx] += (crr.size - q.front().size) * crr.num;
    q.front().idx = min(q.front().idx, crr.idx);
    q.front().num += crr.num;
  }

  for(int i=0; i<N; i++){
    cout << ans[i] << endl;
  }


  return 0;
}

