const int MAXN = 131072;
long long int getv(int *idx, int a, int b)
{
    a += MAXN; b += MAXN;
    long long ans = 0;
    while(a<=b)
    {
        if(a%2==1) ans += idx[a++];
        if(b%2==0) ans += idx[b--];
        a /= 2; b /= 2;
    }
    return ans;
}
void setv(int *idx, int a, int v)
{
    a += MAXN; idx[a] = v;
    while(a = a/2)
    {
        idx[a] = idx[2*a] + idx[2*a+1];
    }
}
int sumtree[2*MAXN], counttree[2*MAXN];
int N; int arr[MAXN]; int ni[MAXN];
