//よく使うクラス、構造体
class UnionFind {
public:
    vi par, rank, sizes;
    int n, trees;
    UnionFind(int n) : n(n), trees(n) {
        par.resize(n), rank.resize(n), sizes.resize(n);
        rep(i, n)par[i] = i, sizes[i] = 1;
    }
    int root(int x) {
        if (par[x] == x)return x;
        else return par[x] = root(par[x]);
    }
    int find(int x) { return root(x); }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y)return;
        if (rank[x] < rank[y])swap(x, y);
        trees--;
        par[y] = x;
        sizes[x] += sizes[y];
        if (rank[x] == rank[y])rank[x]++;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return sizes[root(x)]; }
    //順不同 umapなので
    vec<vi> sets() {
        vec<vi> res(trees);
        umap<int, vi> map;
        rep(i, n) map[root(i)].push_back(i);
        int i = 0;
        for (auto &&p:map) {
            int r = p.F;
            res[i].push_back(r);
            for (auto &&v:p.S) {
                if (r == v)continue;
                res[i].push_back(v);
            }
            i++;
        }
        return res;
    }
};

//MOD関連
ll MOD = (int) 1e9 + 7;
class mint {
public:
    int x;
    mint() : x(0) {}
    mint(signed y) : x(y >= 0 ? y % MOD : MOD - (-y) % MOD) {}
    mint(int y) : x(y >= 0 ? y % MOD : MOD - (-y) % MOD) {}
    static int _mpow(int v, ll a) {
        ll x = v, n = a, res = 1;
        while (n) {
            if (n & 1)res = (res * x) % MOD;
            x = (x * x) % MOD;
            n >>= 1;
        }
        return res;
    }

    // Arithmetic Oprators
    mint &operator+=(mint that) {
        if ((x += that.x) >= MOD) x -= MOD;
        return *this;
    }
    mint &operator-=(mint that) {
        if ((x += MOD - that.x) >= MOD) x -= MOD;
        return *this;
    }
    mint &operator*=(mint that) {
        x = 1LL * x * that.x % MOD;
        return *this;
    }
    mint &operator/=(const mint &that);
    mint &operator^=(const mint &that) {
        this->x = _mpow(x, that.x);
        return *this;
    }
    mint &operator%=(mint that) {
        x %= that.x;
        return *this;
    }

