typedef unsigned long long u64; 

using namespace std;

#define MIN(a, b) a < b ? a : b

int main()
{
	u64 N;
	vector<u64> a;
	vector<u64> answer;

	cin >> N;

	answer.resize(N, 0);

	for(int i = 0; i < N; i++)
	{
		u64 u;
		cin >> u;
		a.push_back(u);
	}

	u64 max = 0;

	for(int i = 0; i < N; i++)
	{
		u64 count = 0;
		if(max >= a[i])
		{
			answer[i] = 0;
			continue;
		}

		count = a[i] - max; 
		for(int j = i+1; j < N; j++)
		{
			if(a[j] > max)
			{
				count += MIN(a[i] - max, a[j] - max);
			}
		}
		answer[i] = count;
		max = a[i];
	}

	for(int i = 0; i < N; i++)
	{
		cout << answer[i] << endl;
	}

	return 0;
}

