ll N_ = 1;
ll seg[(1 << 20) - 1], lazy[(1 << 20) - 1];

void eval(ll k, ll l, ll r){
  if(lazy[k] == 0) return;
  seg[k] += lazy[k];
  if(r - l > 1){
    lazy[2 * k + 1] += lazy[k] / 2;
    lazy[2 * k + 2] += lazy[k] / 2;
  }
  lazy[k] = 0;
}

void add(ll a, ll b, ll x, ll k, ll l, ll r){
  eval(k, l, r);
  if(r <= a || b <= l) return;
  if(a <= l && r <= b){
    lazy[k] += (r - l) * x;
    eval(k, l, r);
    return;
  }
  add(a, b, x, 2 * k + 1, l, (l + r) / 2);
  add(a, b, x, 2 * k + 2, (l + r) / 2, r);
  seg[k] = seg[2 * k + 1] + seg[2 * k + 2];
  return;
}

ll sum(ll a, ll b, ll k, ll l, ll r){
  if(b <= a) return 0;
  if(r <= a || b <= l) return 0;
  eval(k, l, r);
  if(a <= l && r <= b) return seg[k];
  ll suml = sum(a, b, 2 * k + 1, l, (l + r) / 2);
  ll sumr = sum(a, b, 2 * k + 2, (l + r) / 2, r);
  return suml + sumr;
}


int main(){
  ll N;
  cin >> N;
  while(N_ < N) N_ *= 2;
  vector<ll> A(N);
  rep(i, N) cin >> A[i];
  vector<ll> xs;
  xs.pb(INFL);
  rep(i, N) xs.pb(A[i]);
  sort(xs.begin(), xs.end());
  xs.erase(unique(xs.begin(), xs.end()), xs.end());

  rep(i, N){
    ll at = lower_bound(xs.begin(), xs.end(), A[i]) - xs.begin();
    add(0, at + 1, 1, 0, 0, N_);
  }

  ll M = 0;
  ll used = 0;
  rep(i, N){
    if(A[i] <= M){
      cout << 0 << endl;
    }else{
      ll res = 0;
      while(xs[used] <= A[i]){
        if(used == 0) res += sum(used, used + 1, 0, 0, N_) * xs[used];
        else res += sum(used, used + 1, 0, 0, N_) * (xs[used] - xs[used-1]);
        used++;
      }
      cout << res << endl;
      M = A[i];
    }
