int main() {
  int N;  cin >> N;
  vector<int> A(N);
  REP(i, N) cin >> A[i];
  res.assign(N, 0);

  int prv = A[0];
  LS.emplace_back(-1, 0);
  LS.emplace_back(0, prv);
  inLS[0] = true;

  for (int i = 1; i < N; ++i) {
    if (prv < A[i]) {
      prv = A[i];
      inLS[i] = true;
      LS.emplace_back(i, A[i]);
    }
  }

  reverse(LS.begin(), LS.end());

  int cnt = 0;
  ll sum = 0;

  priority_queue<int> pq;
  REP(i, N) pq.emplace(A[i]);

  int sz = LS.size();
  REP(i, sz - 1) {
    int tcnt = 0;
    ll tsum = 0;
    int until = LS[i + 1].second;
    while (not pq.empty() and pq.top() > until) {
      ++tcnt;
      tsum += pq.top();
      pq.pop();
    }
    int idx = LS[i].first;
    res[idx] += tsum - (ll)until * tcnt;
    res[idx] += (ll)(LS[i].second - until) * cnt;
    cnt += tcnt;
    sum += tsum;
  }

