struct Treap {
	Treap *lc,*rc;
	LL sum,pri,key,sz;
	Treap(LL _key) {
		lc=rc=NULL;
		sum=_key;
		key = _key;
		sz=1;
		pri=rand();
	}
};

LL Sz(Treap* t) {
	return t?t->sz:0;
}

LL Sum(Treap* t) {
	return t?t->sum:0;
}

void pull(Treap* t) {
	t->sz = Sz(t->lc) + Sz(t->rc) + 1;
	t->sum = Sum(t->lc) + Sum(t->rc) + t->key;
}

Treap* merge(Treap *a,Treap* b) {
	if (!a||!b) return a?a:b;
	else if (a->pri > b->pri) {
		a->rc=merge(a->rc,b);
		pull(a);
		return a;
	}
	else {
		b->lc=merge(a,b->lc);
		pull(b);
		return b;
	}
}

void split(Treap* t,LL k,Treap* &a,Treap* &b) {
	if (!t) a=b=NULL;
	else if (t->key <= k) {
		a=t;
		split(t->rc,k,a->rc,b);
		pull(a);
	}
	else {
		b=t;
		split(t->lc,k,a,b->lc);
		pull(b);
	}
}

Treap* root;

void add(LL a) {
	Treap* tl;
	split(root,a,tl,root);
	root=merge(tl,merge(new Treap(a),root));
}

LL ans[MAX_N];

pii p[MAX_N];

int main () {
	int n;
	while (scanf("%d",&n) != EOF) {
		root = NULL;
		deque<pii> dq;
		for (int i=1;n>=i;i++) {
			int a;
			scanf("%d",&a);
			add(a);
			if (dq.empty()) {
				dq.push_back(make_pair(a,i));
			}
			else if (a > dq[dq.size()-1].first) {
				dq.push_back(make_pair(a,i));
			}
		}
		dq.push_front(make_pair(0,0));
		int dq_sz = dq.size();
		for (int i=0;dq_sz>i;i++) {
			p[i] = dq.front();
			dq.pop_front();
		}
		int m=dq_sz;
		for (int i=m;i>=1;i--) {
			Treap *tl,*tr;
			split(root,p[i-1].first,tl,root);
			split(root,p[i].first-1,root,tr);
			ans[p[i].second] = Sz(tr)*(p[i].first-p[i-1].first) + (Sum(root)-Sz(root)*p[i-1].first);
			root=merge(merge(tl,root),tr);
		}
		for (int i=1;n>=i;i++) {
			printf("%lld\n",ans[i]);
		}
	}
}

