using namespace std;
const int maxn = 3e5+10;
int n,cnt[100005],tmp;
int ret,id1,id2;
struct tree{
	int left;
	int right;
	int max_num;
	int id;
}node[maxn];

void build(int o,int l,int r){
	node[o].left=l;
	node[o].right=r;
	node[o].max_num=-1;
	node[o].id=-1;
	if(l==r)return;
	build(o*2,l,(l+r)/2);
	build(o*2+1,(l+r)/2+1,r);
}

void update(int o,int pos,int value,int id){
	if(node[o].left==node[o].right){
		node[o].max_num=value;
		node[o].id=id;
		return;
	}

	int mid=(node[o].left+node[o].right)>>1;
	if(pos<=mid)update(o*2,pos,value,id);
	else update(o*2+1,pos,value,id);

	if(node[o*2].max_num>=node[o*2+1].max_num){
		node[o].max_num=node[o*2].max_num;
		node[o].id=node[o*2].id;
	}else{
		node[o].max_num=node[o*2+1].max_num;
		node[o].id=node[o*2+1].id;
	}
	return;
}

void find_max(int o,int ql,int qr){
	if(ql<=node[o].left&&qr>=node[o].right){
		if(node[o].max_num>ret){
			ret=node[o].max_num;
			id2=node[o].id;
		}
	}else{

		int mid=(node[o].left+node[o].right)>>1;
		if(ql<=mid)find_max(o*2,ql,qr);
		if(qr>mid)find_max(o*2+1,ql,qr);
	}
}

void change(int o,int ql,int qr){
	if(node[o].max_num<=ret)return;
	if(node[o].left==node[o].right){
		cnt[id1]+=(node[o].max_num-ret);
		node[o].max_num=ret;
		return;
	}
	int mid=(node[o].left+node[o].right)>>1;
	if(ql<=mid)change(o*2,ql,qr);
	if(qr>mid)change(o*2+1,ql,qr);

	if(node[o*2].max_num>=node[o*2+1].max_num){
		node[o].max_num=node[o*2].max_num;
		node[o].id=node[o*2].id;
	}else{
		node[o].max_num=node[o*2+1].max_num;
		node[o].id=node[o*2+1].id;
	}
}
int main(int argc, char** argv) {
	//freopen("in.txt","r",stdin);
	cin>>n;int x;
	build(1,1,n);
	for(int i=1;i<=n;i++){
		scanf("%d",&x);
		update(1,i,x,i);
	}
	//for(int i=1;i<=20;i++)cout<<node[i].left<<"-"<<node[i].right<<":"<<node[i].id<<"-"<<node[i].max_num<<endl;
	ret=node[1].max_num,id1=node[1].id;
	while(id1!=1){
		ret=-1;
		find_max(1,1,id1-1);
		change(1,id1,n);
		id1=id2;
	}
	cnt[1]+=(n*ret);
	for(int i=1;i<=n;i++)cout<<cnt[i]<<endl;
	return 0;
}

