vector<pii> stones;

int find_next_tar(int right){
  int now = -stones[right].second;
  for (int i = right + 1; i < N; i++){
    int next = -stones[i].second;
    if (now > next){
      return i;
    }
  }
  return -1;
}
ll all_sum;
int main() {
  cin >> N;
  for (int i = 0; i < N; i++){
    int cnt;
    scanf("%d", &cnt);
    stones.emplace_back(mp(cnt, -(i + 1)));
    all_sum += cnt;
  }
  sort(stones.rbegin(), stones.rend());
  if (N == 1){
    cout << stones[0].first << endl;
    return 0;
  }
  int pos = 0;
  map<int, int> answers;
  map<int, int> rest;
  ll pos_val;
  while (true){
    ll pos_cnt = stones[pos].first;
    pos_val = -stones[pos].second;
    int tar = find_next_tar(pos);
    // cout << pos << " " << tar << endl;
    if (tar == -1)break;
    ll sum = 0;
    ll tar_val = -stones[tar].second;
    ll tar_cnt = stones[tar].first;
    map<int, int> tmp_rest;

    for (const auto &val : rest){
      ll cnt = val.first;
      ll deg = val.second;
      sum += (cnt - tar_cnt) * deg;
      tmp_rest[tar_cnt]++;
    }
    rest.clear();
    for (int i = pos; i < tar; i++){
      sum += stones[i].first - tar_cnt;
      rest[tar_cnt]++;
    }

    rest[tar_cnt] += tmp_rest[tar_cnt];
    answers[pos_val] += sum;
    all_sum -= sum;
    pos = tar;

  }
  answers[pos_val] += all_sum;

  for (int i = 1; i <= N; i++){
    printf("%d\n", answers[i]);
  }
  return 0;
}

