#define R register
#define maxn 100010
int a[maxn], hash[maxn], hcnt, cnt[maxn], fir[maxn];
std::priority_queue<std::pair<int, int> > s;
long long ans[maxn];
int main()
{
//	freopen("in.in", "r", stdin);
//	freopen("dev.ans", "w", stdout);
	int n; scanf("%d", &n);
	for (int i = 1; i <= n; ++i)
	{
		scanf("%d", &a[i]);
		hash[++hcnt] = a[i];
	}
	std::sort(hash + 1, hash + hcnt + 1);
	hcnt = std::unique(hash + 1, hash + hcnt + 1) - hash - 1;
	for (R int i = 1; i <= n; ++i)
	{
		a[i] = std::lower_bound(hash + 1, hash + hcnt + 1, a[i]) - hash;
		if (!fir[a[i]]) fir[a[i]] = i;
		s.push(std::make_pair(a[i], i));
	}
	for (; !s.empty(); )
	{
		R std::pair<int, int> top = s.top(); s.pop();
		ans[fir[top.first]] += hash[top.first] - hash[top.first - 1];
		--top.first;
		if (top.first > 0) s.push(top);
	}
	for (R int i = 1; i <= n; ++i) printf("%lld\n", ans[i]);
	return 0;
}

