		if(a[i] == max){
			ans[first[a[i]]] = (max - smax) * c;
			sum = c;
		}else{
			sum += c;
			ans[first[a[i]]] = sum;
		}		
	}

	for(int i = 1; i <= n; i++){
		cout << ans[i] << endl;
	}
	return 0;	
}

