    }
    vector<int> stk;
    for (int i = 0; i < N; i++) {
      if (stk.empty() || a[stk.back()] < a[i]) {
        stk.push_back(i);
      }
    }
    vector<ll> xs = a;
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    vector<ll> ys = a;
    for (auto& y : ys) {
      y = lower_bound(xs.begin(), xs.end(), y) - xs.begin();
    }
    vector<ll> ans(N, 0);
    fenwick_tree<ll> cnt(xs.size()), sum(xs.size());
    for (int i = stk.size() - 2, k = N - 1; i >= 0; i--) {
      int j = stk[i], p = stk[i + 1];
      while (j < k) {
        cnt.add(ys[k], 1);
        sum.add(ys[k], a[k]);
        --k;
      }
      ll c = cnt.sum(ys[j] + 1, ys[p]);
      ll s = sum.sum(ys[j] + 1, ys[p]);
      ans[p] += s - (c * a[j]);
      cnt.add(ys[j], c);
      sum.add(ys[j], c * a[j]);
    }
    for (int i = 1; i < N; i++) {
      cout << ans[i] << endl;
    }
  }
  return 0;
}

