const int MAX_N = 100000, INDEX = 1;

struct Pile {
    int ind, val;

    Pile() {
        this->ind = 0;
        this->val = 0;
    }

    Pile(int ind, int val) {
        this->ind = ind;
        this->val = val;
    }

    friend bool operator < (const Pile& a, const Pile& b) {
        if (a.val == b.val) {
            return a.ind < b.ind;
        }

        return a.val > b.val;
    }
};

int n, a[MAX_N + INDEX];
long long ans[MAX_N + INDEX];

Pile aSort[MAX_N + 1 + INDEX];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie();
    cout.tie();

    cin >> n;

    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }

    for (int i = 1; i <= n; i++) {
        aSort[i] = Pile(i, a[i]);
    }

    aSort[n + 1] = Pile(0, 0);

    sort(aSort + INDEX, aSort + n + 1 + INDEX, less<Pile>());

//    for (int i = 1; i <= n + 1; i++) {
//        cout << aSort[i].ind << ' ' << aSort[i].val << '\n';
//    }

    int r = 1;
    for (int l = 1; l <= n; ) {
        while (aSort[r].ind >= aSort[l].ind) {
            r++;
        }

        int x = aSort[l].ind;

//        cout << l << ' ' << r << ' ' << x << ' ' << aSort[l].val << ' ' << aSort[r].val << '\n';

        ans[x] += (long long)(l - 1) * (long long)(aSort[l].val - aSort[r].val);

        for (; l < r; l++) {
            ans[x] += aSort[l].val - aSort[r].val;
        }
    }

    for (int i = 1; i <= n; i++) {
        cout << ans[i] << '\n';
    }

    return 0;
}

