	for (int i = 1; i <= n; ++i)
		if (a[i] > a[lst.back()])
			lst.push_back(i);
	lst.push_back(n + 1);

	priority_queue<PII> Q;
	ll cnt = 0;
	for (int i = lst.size() - 3; i >= 0; --i){
		int u = lst[i], v = lst[i + 1], w = lst[i + 2];
		for (int j = v; j < w; ++j)
			Q.emplace(PII(a[j], j));

		ans[v] = cnt * (a[v] - a[u]);
		for (; !Q.empty() && Q.top().st > a[u]; Q.pop())
			ans[v] += a[Q.top().nd] - a[u], ++cnt;
	}

	for (int i = 1; i <= n; ++i)
		printf("%lld\n", ans[i]);
	return 0;
}

