typedef pair<long long int, long long int> P;

int main() {
	long long int n;
	cin >> n;
	priority_queue<P> pq;
	long long int a;
	vector<long long int> b(n, 0);
	for (long long int i = 0; i < n; i++) {
		cin >> a;
		pq.push(P(a, -i));
	}
	while(!pq.empty()) {
		P p = pq.top();
		pq.pop();
		if (p.first == 1) {
			b[0] = pq.size();
			b[0]++;
			break;
		}
		while (!pq.empty()) {
			P p2 = pq.top();
			if (p.first == p2.first) {
				pq.pop();
				b[-p.second]++;
				p2.first--;
				pq.push(p2);
			} else {
				b[-p.second]++;
				p.first--;
				pq.push(p);
				break;
			}
		}
		//cout << pq.size() << endl;
	}
	for (long long int i = 0; i < n; i++) {
		cout << b[i] << endl;
	}
	return 0;
}

