signed run() {
    ll n;
    cin >> n;
    vector<ll> mas(n);
    ll cur = 0;
    for (int i = 0; i < n; ++i) {
        cin >> mas[i];
        if (mas[i] > mas[cur]) cur = i;
    }
    ll curspeed = 0;
    map<ll, ll> mp;
    vector<ll> ans(n);
    set<pair<ll, ll>> st;
    for (int i = 0; i < cur; ++i) {
        st.insert({-mas[i], i});
    }
    for (int i = n - 1; i > cur; --i) {
        mp[mas[i]]++;
    }
    while (cur != -1) {
        ll curcnt = 0;
        ll nextcur = cur;
        while (!st.empty() && nextcur >= cur) {
            nextcur = st.begin()->second;
            st.erase(st.begin());
        }
        if (nextcur >= cur && st.empty()) nextcur = -1;
        while (!mp.empty() && (nextcur == -1 || mp.rbegin()->first > mas[nextcur])) {
            curcnt += (mas[cur] - mp.rbegin()->first) * curspeed + mas[cur] - mp.rbegin()->first;
            mas[cur] = mp.rbegin()->first;
            curspeed += mp.rbegin()->second;
            mp.erase(--mp.end());
        }
        ans[cur] += curcnt + (nextcur == -1 ? (curspeed + 1) * mas[cur] : (curspeed + 1) * (mas[cur] - mas[nextcur]));
        if (nextcur != -1) mas[cur] = mas[nextcur];
        while (cur != nextcur) {
            mp[mas[cur]]++;
            cur--;
        }
    }
    for (int i = 0; i < n; ++i) {
        cout << ans[i] << endl;
    }
    return 0;
}

