struct SegmentTree {
    int n;
    vector<ll> node;
    ll calc(ll a, ll b) {
        return a + b;
    }
    ll e = 0;
    SegmentTree(vector<ll> v) {
        int sz = v.size();
        n = 1;
        while (n < sz) {
            n *= 2;
        }
        node.resize(2 * n - 1, e);
        for (int i = 0; i < sz; i++) {
            node[i + n - 1] = v[i];
        }
        for (int i = n - 2; i >= 0; i--) {
            node[i] = calc(node[2 * i + 1], node[2 * i + 2]);
        }
    }
    void update(int x, ll val) {
        x = n + x - 1;
        node[x] += val;
        while (x > 0) {
            x = (x - 1) / 2;
            node[x] = calc(node[2 * x + 1], node[2 * x + 2]);
        }
    }
    ll query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return e;
        if (a <= l && r <= b) return node[k];
        ll vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return calc(vl, vr);
    }
    ll at(int x) {
        return node[n + x - 1];
    }
};

int main() {
    int n;
    cin >> n;
    vector<ll> a(n);
    vector<ll> sorted(n);
    ll sum = 0;
    rep(i, n) {
        cin >> a[i];
        sorted[i] = a[i];
        sum += a[i];
    }

    sort(all(sorted));
    get_unique(sorted);
    vector<int> order(n);
    rep(i, n) order[i] = lower_bound(all(sorted), a[i]) - sorted.begin();

    vector<ll> num(n);
    vector<ll> vec(100100, 0);
    SegmentTree segt(vec);
    rrep(i, n) {
        segt.update(order[i], 1);
        num[i] = segt.query(order[i], 100100);
    }

    vector<bool> zero(n, true);
    ll now = 0;
    rep(i, n) {
        if (chmax(now, a[i])) {
            zero[i] = false;
        }
    }

    now = 0;
    rep(i, n) {
        if (zero[i]) {
            cout << 0 << endl;
            continue;
        }

        // cout << (a[i] - now) * num[i] << endl;
        sum -= (a[i] - now) * num[i];
        now = a[i];
    }

    if (sum != 0) {
        throw runtime_error("");
    }
}

