int N;
LL A[114514];
LL ans[114514];
priority_queue<Pair> que;

int main() {
  scanf("%d", &N);

  LL res = 0;
  rep(i, N) {
    scanf("%lld", &A[i]);
    que.push(Pair(A[i], -i));
    res += A[i];
  }

  LL M = que.top().first;
  int midx = -que.top().second;
  que.pop();
  LL tot = M;
  int cnt = 1;
  while (!que.empty() && midx != 0) {
    Pair p = que.top(); que.pop();
    int idx = -p.second;
    if (idx < midx) {
      M = p.first;
      ans[midx] = tot- M*cnt;
