      res -= ans[midx];
      cnt++;
      tot = M*cnt;
      midx = idx;
      continue;
    } else {
      tot += p.first;
      cnt++;
    }
  }
  ans[0] = res;

  rep(i, N) {
    printf("%lld\n", ans[i]);
  }
}

