using namespace std;

class Counting {
	unsigned long long p, n;
	vector<long long> invMemo, facMemo, facInvMemo;
public:
	Counting(unsigned long long nn, unsigned long long np) {
		p = np;
		n = nn;
		invMemo.resize(n + 1);
		facMemo.resize(n + 1);
		facInvMemo.resize(n + 1);
		facMemo[0] = 1;
		facMemo[1] = 1;
		facInvMemo[0] = 1;
		facInvMemo[1] = 1;
		invMemo[0] = 0;
		invMemo[1] = 1;
		for (unsigned long long i = 2; i <= n; i++) {
			invMemo[i] = p - (p / i)*invMemo[p%i] % p;
			facMemo[i] = (facMemo[i - 1] * i) % p;
			facInvMemo[i] = (facInvMemo[i - 1] * invMemo[i]) % p;
		}
	}
	unsigned long long fac(unsigned long long k) {
		return facMemo[k];
	}
	unsigned long long facInv(unsigned long long k) {
		return facInvMemo[k];
	}
	unsigned long long choose(unsigned long long n, unsigned long long k) {
		if (!(0 <= k && k <= n))
			return 0;
		return (((facMemo[n] * facInvMemo[k]) % p)*facMemo[n - k]) % p;
	}
	unsigned long long divide(unsigned long long a, unsigned long long b) {
		return (a * invMemo[b]) % p;
	}
	unsigned long long mod(unsigned long long a) {
		a %= p;
		if (a < 0) a += p;
		return a;
	}
	unsigned long long power(unsigned long long a, unsigned long long e) {
		unsigned long long ans = 1;
		for (; e > 0; e /= 2) {
			if (e % 2 != 0)
				ans = ans * a % p;
			a = a*a%p;
		}
		return ans;
	}
};

class Data {
public:
	int id;
	long long a;
	Data(int i, long long ll){
		id = i;
		a = ll;
	}
	bool operator<(Data &rhs) {
		if (this->a > rhs.a) {
			return true;
		}
		else if (this->a == rhs.a) {
			return this->id > rhs.id;
		}
		return false;
	}

	bool operator>(Data &rhs) {
		if (this->a < rhs.a) {
			return true;
		}
		else if (this->a == rhs.a) {
			return this->id < rhs.id;
		}
		return false;
	}
};

int main() {
	int n;
	vector<int> ans;
	cin >> n;
	vector<Data>dt;
	ans.resize(n);
	for (int i = 0; i < n; i++) {
		long long a;
		cin >> a;
		Data hoge(i, a);
		dt.push_back(hoge);
	}
	sort(dt.begin(), dt.end());
	int id = n;
	for (int i = 0; i < n - 1; i++) {
		if (id > dt[i].id) {
			id = dt[i].id;
		}
		ans[id] += (dt[i].a - dt[i + 1].a)*(i + 1);
	}
	if (id > dt[n - 1].id) {
		id = dt[n - 1].id;
	}
	ans[id] += dt[n - 1].a * n;

	for (int i = 0; i < n; i++) {
		cout << ans[i] << endl;
	}
//	cin >> n;
	return 0;
}

