using namespace std;

int main(){
	int N;
	while(cin >> N){
		vector<int> a(N);
		for(int i=0;i<N;i++) cin >> a[i];
		vector<int> b;
		b.push_back(0);
		for(int i=0;i<N;i++) b.push_back(a[i]);
		sort(b.begin(), b.end());
		b.erase(unique(b.begin(), b.end()), b.end());
		map<int,int> numToIdx;
		for(int i=0;i<b.size();i++) numToIdx[b[i]] = i;
		vector< pair<int,int> > check;
		check.push_back(make_pair(0,-1));
		for(int i=0;i<N;i++){
			if(a[i] > check.back().first) check.push_back(make_pair(a[i], i));
		}
		vector<int> hold(b.size(), 0);
		int end = N;
		int numEnd = b.size();
		vector<int> res(N, 0);
		for(int i=check.size()-1;i>0;i--){
			int curIdx = check[i].second;
			for(int j=curIdx;j<end;j++) hold[numToIdx[a[j]]]++;
			int numIdx = numToIdx[check[i-1].first]+1;
			for(int j=numIdx;j<numEnd;j++){
				res[curIdx] += (long long)hold[j] * (b[j] - b[numIdx-1]);
				hold[numIdx-1] += hold[j];
			}
			end = curIdx;
			numEnd = numIdx;
		}
		for(int i=0;i<N;i++) cout << res[i] << endl;
	}
}

