/*
 <url:https://arc069.contest.atcoder.jp/tasks/arc069_c>
 問題文============================================================
 すぬけくんは数列を作るのが好きです。

 1 から N までの番号がついた石の山があります。 i 番の石の山は ai 個の石からなります。

 すぬけくんは以下の手順により長さ Σai の数列 s を構成することにしました。

 1. 石の数が最大である山のうち、最も番号が小さい山の番号を x として、s の末尾に x を追加する
 2. 石が 1 個以上存在する山を 1 つ選んで、選んだ山から石を 1 つ取り除く
 3. 石が 1 個以上存在する山が存在するなら 1. へ、そうでなければ数列の構成を終了する

 s が辞書順で最小の数列となるようにしたとき、s に 1,2,3,…,N という数がそれぞれいくつ含まれるか求めなさい。
 =================================================================
 解説=============================================================
 ================================================================
 */

/*
 1-index

 add : x に valを加算
 sum : [1,x] の総和を出力
 */
struct BIT {
    ll N;
    vector<ll> bit;
    BIT(ll N):N(N) {
        /* BITは[1..N]で扱う */
        bit.resize(N + 1, 0);
    }

    void add(int x, ll val){
        while (x <= N) {
            bit[x] += val;
            x += x & -x;
        }
    }

    int sum(int x){
        int ret = 0;
        while (x) {
            ret += bit[x];
            x &= (x - 1);
        }
        return (ret);
    }
};

void solve(){
    ll N; cin >> N;
    vector<int> a(N);
    for(int i = 0; i < N;i++){ cin >> a[i]; }
    vector<int> xa = a,ta = a;
    sort(xa.begin(),xa.end()); xa.erase(unique(xa.begin(),xa.end()),xa.end());

    int geta = 2;
    for(int i = 0; i < N;i++){
        a[i] = (int)(lower_bound(xa.begin(), xa.end(), a[i]) - xa.begin());
    }

 //  cout << ta << endl;
 //   cout << a << endl;
 //   cout << xa << endl;

    vector<ll> imos(xa.size()+1);
    for(int i = 0; i < N;i++){
        imos[0]++; imos[a[i]+1]--;
    }
    for(int i = 0; i < N;i++) imos[i+1] += imos[i];
    cout << imos << endl;
    vector<ll> ans(N);
    // initialize
    vector<pll> p;
    for(int i = 0; i < N;i++){
        if(p.empty()) p.push_back({a[0],i});
        if(p[p.size()-1].first < a[i]) p.push_back({a[i],i});
    }
   // cout << p << endl;
    ll sum = 0;
    ll idx = 0;
    for(int i = 0; i < N;i++){
        if(i==0){
            sum += xa[i]*imos[i];
        }else{
            sum += (xa[i]-xa[i-1])*imos[i];
        }

        if(p[idx].first == i){
