#include <bits/stdc++.h>
#define ll long long
using namespace std;

typedef unordered_set<int> llSet;

ll sz = (1ll << 25);
ll tree[(1ll << 25) + 1ll];

void bitSet(ll v, ll x) {
  while(x <= sz) {
    tree[x] += v;
    x += (x & -x);
  }
}
ll getUpTo(ll x) {
  ll ret = 0;
  while(x >= 1) {
    ret += tree[x];
    x -= (x & -x);
  }
  return ret;
}

int main() {
  ll N;
  cin >> N;
  ll a[N];

  for(ll i = 0; i < N; i++)
    cin >> a[i];

  ll totalSum = 0;
  for(ll i = 0; i < N; i++)
    totalSum += a[i];

  ll b[N];
  for(ll i = 0; i < N; i++)
    b[i] = a[i];

  sort(b, b + N);
  unordered_map<ll, ll> numberCompression;
  vector<ll> restoreNumber(N + 3, 0);

  for(ll i = 0; i < N; i++) {
    if(i == 0) {
      numberCompression[b[i]] = 1;
      restoreNumber[1] = b[i];
      continue;
    }
    if(b[i] != b[i - 1]) {
      numberCompression[b[i]] = i + 2;
      restoreNumber[i + 2] = b[i];
    }
  }

  for(ll i = 0; i < N; i++) {
    a[i] = numberCompression[a[i]];
  }

  ll maxInLeft[N];

  ll ma = 0;
  llSet s;

  bool hasSameNumber[N];

  ll equalOrGreaterInRight[N];
  equalOrGreaterInRight[N - 1] = 0;

  for(ll i = 0; i < N; i++)
    hasSameNumber[i] = false;

  for(ll i = 0; i < N; i++) {
    if(s.find(a[i]) != s.end())
      hasSameNumber[i] = true;
    maxInLeft[i] = ma;
    ma = max(ma, a[i]);
    s.insert(a[i]);
  }

  for(ll i = N - 1; i >= 0; i--) {
    equalOrGreaterInRight[i] = (N - 1ll - i) - getUpTo(a[i] - 1ll);
    bitSet(1ll, a[i]);
  }
  /*  
  for(ll i = 0; i < N; i++) {
    cout << i << ' ' << hasSameNumber[i] << ' ' << maxInLeft[i]
	 << ' ' << equalOrGreaterInRight[i] << endl;
  }
  */
  vector<ll> ans(N);
  for(ll i = 1; i < N; i++) {
    if(!hasSameNumber[i] && maxInLeft[i] < a[i]) {
      ans[i] =  (restoreNumber[a[i]] - restoreNumber[maxInLeft[i]]) * (equalOrGreaterInRight[i] + 1);
    }else {
      ans[i] = 0;
    }
  }



  ll sum = 0;
  for(ll i = 1; i < N; i++)
    sum += ans[i];

  cout << totalSum - sum << endl;
  for(ll i = 1; i < N; i++)
    cout << ans[i] << endl;


}

