int dat[1<<20];
ll res[100001];

void update(int k,int a){
	k+=n_-1;
	dat[k]+=a;
	while(k>0){
		k=(k-1)/2;
		dat[k]=dat[k*2+1]+dat[k*2+2];
	}
}

int query(int a,int b,int k=0,int l=0,int r=n_){
	if(r<=a || b<=l)return 0;
	if(a<=l && r<=b)return dat[k];
	int vl=query(a,b,k*2+1,l,(l+r)/2);
	int vr=query(a,b,k*2+2,(l+r)/2,r);
	return vl+vr;
}

int main(void){
	scanf("%d",&n);
	for(int i=0;i<n;i++){
		scanf("%d",&a[i]);
		vec.push_back(a[i]);
	}
	sort(vec.begin(),vec.end());
	vec.erase(unique(vec.begin(),vec.end()),vec.end());
	n_=1;
	while(n_<vec.size())n_*=2;
	for(int i=0;i<n;i++){
		a[i]=lower_bound(vec.begin(),vec.end(),a[i])-vec.begin();
		update(a[i],1);
	}
	int now=0;
	for(int i=0;i<n;i++){
		if(vec[a[i]]>now){
			int val=query(a[i],n_);
			res[i]=(ll)val*(vec[a[i]]-now);
			now=vec[a[i]];
		}
		update(a[i],-1);
	}
	for(int i=0;i<n;i++){
		printf("%lld\n",res[i]);
	}
	return 0;
}

