int main() {
    ios_base::sync_with_stdio(0);

    int n;
    cin >> n;

    VI a(n);
    FOR(i,0,n-1) {
        cin >> a[i];
    }

    VB isMax(n,false);
    VI prevMax(n, 0);

    int maxPos = -1;
    FOR(i,0,n-1) {
        if (maxPos == -1 || a[i] > a[maxPos]) {
            if (maxPos != -1) {
                prevMax[i] = a[maxPos];
            }

            maxPos = i;
            isMax[i] = true;
        }
    }

    VL ans(n, 0);

    multiset <int,greater<int>> values;
    int alreadyAbove = 0;
    ll sumAbove = 0;

    int limit = INF;
    ll lastAns = 0;

    FORD(i,n-1,0) {
        values.insert(a[i]);

        if (isMax[i]) {
            limit = prevMax[i];
            while (!values.empty() && *values.begin() > limit) {
                sumAbove += *values.begin();
                alreadyAbove++;

                values.erase(values.begin());
            }

            ll here = sumAbove - (ll) alreadyAbove * limit;

            ans[i] = here - lastAns;
            lastAns = here;
        }
    }

    FOR(i,0,n-1) {
        cout << ans[i] << '\n';
    }

    return 0;
}

