  vector<int> isMax(n + 1, false);
  int tmp = 0;
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    if (tmp < a[i]) {
      tmp = a[i];
      isMax[i] = true;
    }
  }
  map<int, int> mp;
  int prv = n - 1;
  vector<int> ret(n, 0);
  for (int i = n - 1; i >= 0; i--) {
    int crr = a[i];
    mp[crr]++;
    if (isMax[i]) {
      auto bgn = mp.upper_bound(crr);
      for (auto it = bgn; it != mp.end(); it++) {
