        int mlt = it->second;
        ret[prv] += (long long)(val - crr) * mlt;
        mp[crr] += mlt;
      }
      mp.erase(bgn, mp.end());
      prv = i;
    }
  }
  for (auto it = mp.begin(); it != mp.end(); it++) {
    int val = it->first;
    int mlt = it->second;
    ret[prv] += (long long)val * mlt;
  }
