const int N = 2e5 + 7, MAX = 1e9;

int mx_idx[N], a[N], ans[N], ptr = 1, c[N], s[N];

struct node{
	int sum = 0, cnt = 0, l = -1, r = -1;
}t[N * 40];


void update(int v, int l, int r, int x) {
	if(l == r) {
		t[v].sum += x;
		t[v].cnt += 1;
		return;
	}
	t[v].l = t[v].l > 0 ? t[v].l : ++ptr;
	t[v].r = t[v].r > 0 ? t[v].r : ++ptr;
	int mid = (l + r) >> 1;
	if(mid >= x) {
		update(t[v].l, l, mid + 0, x);
	} else {
		update(t[v].r, mid + 1, r, x);
	}
	t[v].sum = t[t[v].l].sum + t[t[v].r].sum;
	t[v].cnt = t[t[v].l].cnt + t[t[v].r].cnt;
} 

pair <int, int> query(int v, int l, int r, int b, int e) {
	if(v < 0 || l > e || r < b) {
		return make_pair(0, 0);
	}
	if(l >= b && r <= e) {
		return make_pair(t[v].sum, t[v].cnt);
	}
	int mid = (l + r) >> 1;
	auto p = query(t[v].l, l, mid, b, e);
	auto q = query(t[v].r, mid + 1, r, b, e);
	return make_pair(p.first + q.first, p.second + q.second);
}

