int findMax(int N, int* a) {

    int res = N - 1;
    int tmp = a[res];
    for(int i=N-2;i>=0;i--) {
        if(a[i]>=tmp) {
            tmp = a[i];
            res = i;
        }
    }

    return res;
}

int calcUpSum(int N, int* a, int div, int val) {
    int res = 0;
    for(int i=div+1;i<N;i++) {
        if(a[i] > val) {
            res += (a[i] - val);
        }
    }

    return res;
}

void valClrUpper(int N, int* a, int div, int val) {
    for(int i=div+1;i<N;i++) {
        if(a[i] > val) {
            a[i] = val;
        }
    }
}

