    }

    int* res;
    res = (int*)malloc(sizeof(int)*N);
    for(int i=0;i<N;i++) {
        res[i] = 0;
    }

    int x,y;
    while(1) {
        x=findMax(N, a);
        if(a[x] == 0) break;
        y=findMax(x, a);
        res[x]=calcUpSum(N, a, x, a[y]);
        res[x]+=(a[x]-a[y]);
        a[x]=a[y];
        valClrUpper(N, a, x, a[y]);
    }

    for(int i=0;i<N;i++) {
        printf("%d\n", res[i]);
    }

    free(a);
    free(res);


    return 0;
}

