struct node {
    int num,pos;
}q[100010];

bool cmp(node &a,node &b)
{
    if(a.num==b.num)
        return a.pos<b.pos;
    else return a.num<b.num;
}

ll lowbit(ll x)
{
    return x&(-x);
}

void update(ll x,ll num)
{
    while(x<=n)
    {
        c[x]+=num;
        x+=lowbit(x);
    }
}

ll getsum(ll x)
{
    ll ans=0;
    while(x>0)
    {
        ans+=c[x];
        x-=lowbit(x);
    }
    return ans;
}
int main()
{
    while(cin>>n)
    {
        ll ans=0;
        memset(t,-1,sizeof(t));
        memset(c,0,sizeof(c));
        long long int premax=0;
        for(int i=1;i<=n;i++)
        {
            scanf("%lld",&s[i]);
            ans+=s[i];
            q[i].num=s[i];
            q[i].pos=i;
            if(premax==0)
            {
                premax=s[1];
                t[1]=s[1];
            }
            else if(s[i]<premax) t[i]=0;
            else
            {
                t[i]=s[i]-premax;
                premax=s[i];
            }
        }
        sort(q+1,q+n+1,cmp);
        for(int i=1;i<=n;i++)
        {
            s[q[i].pos]=i;
        }
        for(int i=n;i>=1;i--)
        {
            r[s[i]]=getsum(s[i]);
            tims[i]=1+n-i-r[s[i]];
            update(s[i],1);
        }
        for(int i=2;i<=n;i++)
        {
            tt[i]=tims[i]*t[i];
            ans-=tt[i];
        }
        tt[1]=ans;
        for(int i=1;i<=n;i++)
            printf("%lld\n",tt[i]);

    }
}

