            exempt[sub[idx]] = query(tree2, 0, 1, n, sub[idx], n) * amt
                - query(tree1, 0, 1, n, sub[idx], n);
        }
    }

    ll last = 0;
    for (int i = n; i >= 1; i--) {
        if (has[i]) {
            ans[i] = suf[i] - 1LL * arr[pre[i]] * (n - i + 1)
                + exempt[i] - last;
            last += ans[i];
        }
    }

    for (int i = 1; i <= n; i++) {
        if (!has[i]) {
            printf("0\n");
        } else {
            printf("%lld\n", ans[i]);
        }
    }

    return 0;
}

