  }
  bit1.init(n);
  bit2.init(n);
  while(!q.empty()) {
    K cur = q.top(); q.pop();
    ll sum = bit1.sum(n+1) - bit1.sum(cur.idx+1);
    ll cnt = bit2.sum(n+1) - bit2.sum(cur.idx+1);
    cs[cur.idx] = sum - cnt * cur.v;
    bit1.add(cur.idx, cur.v);
    bit2.add(cur.idx, 1);
