int N;
int A[100111];
int head[100111];
int name[100111];
LL ans[100111];
map<int, int> S[100111];

int main() {
    scanf("%d", &N);
    REP (i, N) scanf("%d", A+i);

    memset(head, 0x3f, sizeof head);
    const int INF = head[0];
    REP (i, N) {
	int k = lower_bound(head, head+N, A[i]) - head;
	if (head[k] == INF) {
	    head[k] = A[i];
	    name[k] = i;
	}
	S[k][A[i]]++;
    }
    int len = lower_bound(head, head+N, head[N]) - head;
    while (len) {
	len--;
	int left = (len == 0? 0: head[len-1]);
	EACH (e, S[len]) {
	    ans[name[len]] += (LL)(e->first - left) * e->second;
	    if (len) S[len-1][head[len-1]] += e->second;
	}
    }
    REP (i, N) printf("%lld\n", ans[i]);


    return 0;
}

