// numとarrayの値が一致するindexの中で最も小さいものを返す
int scan( const int* array, const int array_size, const int num ) {

	for ( int i = 0; i < array_size; i++ ) {
		if ( array[i] == num ) 
			return i;
	}

	return 0;
}

// numがarrayの中にいくつ含まれるか調べる
int scan2( const int* array, const int array_size, const int num ) {
	int sum = 0;

	for ( int i = 0; i < array_size; i++ ) {
		if ( array[i] == num )
			sum++;
	}

	return sum;
}

bool scan3( const int* array, const int array_size, const int num, const int index_start ) {

	// cout << "num: " << num << endl;
	// cout << "index_start: " << index_start << endl;

	if ( index_start <= 0 )
		return false;

	for ( int i = index_start-1; i >= 0; i-- ) {
		// cout << "c" << endl;
		if ( array[i] < num )
			return true;
	}

	return false;
}


int main() {

	int n;
	int* a;
	int* a_sorted;
	int* a_ans;
	int n_equal;

	int counted = 0;
	int sum = 0;
	int removed = 0;

	cin >> n;

	a = new int[n];
	a_sorted = new int[n];
	a_ans = new int[n];

	for ( int i = 0; i < n; i++ ) {
		cin >> a[i];
		a_sorted[i] = a[i];

		a_ans[i] = 0;
		sum += a[i];
	}

	sort( a_sorted, a_sorted + n, greater<int>() );


	for ( int i = 0; i < n; i += n_equal ) {

		int n_max;
		int n_next;
		int a_index;

		n_max = a_sorted[i];
		n_equal = scan2( a_sorted, n, n_max );

		n_next = a_sorted[i+n_equal];

		a_index = scan( a, n, n_max );



		if ( scan3( a, n, n_max, a_index ) ) {
			a_ans[a_index] = ( n_equal + counted ) * ( n_max - n_next );
			counted += n_equal;
		}
		else {
			a_ans[a_index] = sum - removed + n_max * i;
			break;
		}

		removed += n_equal * n_max;
	}

	for ( int i = 0; i < n; i++ ) {
		cout << a_ans[i] << endl;
	}


	return 0;
}

