struct data {
	int f,cnt;
};
map<int,data> m;
char buf[30];
inline void outll(ll x) {
	if(!x) {
		puts("0");
		return;
	}
	int i=0;
	for(;x;x/=10) buf[i++]='0'+x%10;
	while(i--) putchar(buf[i]);
