}
int main() {
	scanf("%d",&n);
	for(int i=0;i<n;++i) {
		scanf("%d",a+i);
		b[i]=a[i];
		data &d=m[a[i]];
		if(!d.cnt) d.f=i;
		++d.cnt;
	}
	b[n]=0;sort(b,b+n+1);
	c=unique(b,b+n+1)-b;
	for(int i=c-1;i;--i) {
		data &d=m[b[i]],&e=m[b[i-1]];
		ans[d.f]+=d.cnt*ll(b[i]-b[i-1]);
		e.cnt+=d.cnt;
