template<typename Monoid,typename F>
struct SegmentTree{
	int sz;
	vector<Monoid> node;
	const F op;//演算
	const Monoid e;//単位元
	SegmentTree(int n,const F op,const Monoid &e):op(op),e(e){
		sz=1;
		while(sz<n) sz*=2;
		node.assign(2*sz,e);
	}
	void build(const vector<Monoid> &v){
		int n=v.size();
		for(int i=0;i<n;i++) node[i+sz-1]=v[i];
		for(int i=sz-2;i>=0;i--) node[i]=op(node[2*i+1],node[2*i+2]);
	}
	void update(int k,const Monoid &x){
		k+=sz-1;
		node[k]=x;
		while(k>0){
			k=(k-1)/2;
			node[k]=op(node[2*k+1],node[2*k+2]);
		}
	}
	Monoid query(int a,int b,int k=0,int l=0,int r=-1){
		if(r<0) r=sz;
		if(r<=a || b<=l) return e;
		if(a<=l && r<=b) return node[k];
		else{
			Monoid vl=query(a,b,2*k+1,l,(l+r)/2);
			Monoid vr=query(a,b,2*k+2,(l+r)/2,r);
			return op(vl,vr);
		}
	}
	Monoid operator[](const int &k)const{
		return node[k+sz-1];
	}
};

int main(){
	cin.tie(0);ios::sync_with_stdio(false);
	int n;
	cin>>n;
	assert(n<=10000);
	vector<P> a(n);
	rep(i,n){
		cin>>a[i].fi;
		a[i].se=i;
	}
	auto op=[](P a,P b){
		if(a.fi>b.fi) return a;
		else if(a.fi<b.fi) return b;
		else{
			if(a.se<b.se) return a;
			else return b;
		}
	};
	SegmentTree<P,decltype(op)> seg(n,op,P(0,inf));
	seg.build(a);
	P now=seg.query(0,n);
	vector<ll> ans(n,0);
	while(true){
		if(now.se==0){
			rep(i,n){
				ans[0]+=a[i].fi;
			}
			break;
		}
		P ne=seg.query(0,now.se);
		FOR(i,now.se,n){
			ans[now.se]+=max(0ll,a[i].fi-ne.fi);
			chmin(a[i].fi,ne.fi);
		}
		now=ne;
	}
	cout<<ans<<endl;
}

