      p.first++;
      if (p.second > a)
	p.second = a;
    }
  }

  vector<int> r(N + 1, 0);
  auto i = begin(t);
  auto j = next(i);
  while (j != end(t)) {
    r[i->second.second] += (i->first - j->first) * i->second.first;
    j->second.first += i->second.first;
    ++i;
    ++j;
  }
  r[i->second.second] += i->first * i->second.first;

  for (int k = 1; k < N + 1; ++k) {
    cout << r[k] << "\n";
  }

  return 0;
}

