  while(segt[0]){
    if(charnow==0){
      REP(i,n){
	ans[0]+=segt[start+i];
	update(i,0);
      }
    }else{
      int d=charnow;
      int max = 0;
      REP(i,charnow){
	if(segt[start+i]>max){
	  d=i;
	  max=segt[start+i];
	}
      }
      while(best != d){
	ans[charnow]+=segt[best+start]-max;
	update(best,max);
      }
      charnow=d;
    }
  }

  REP(i,n)
    cout<<ans[i]<<endl;
  return 0;
}

