void update(int p,pair<ll,ll> x)
{
    while(p<N)
    {
        b[p].FT+=x.FT;
        b[p].SD+=x.SD;
        p+=(p&-p);
    }
}
pair<ll,ll> query(int p)
{
    pair<ll,ll> ret = MP(0,0);
    while(p>0)
    {
        ret.FT+=b[p].FT;
        ret.SD+=b[p].SD;
        p-=(p&-p);
    }
    return ret;
}
