map<ll, ll> hsh;
set<ll> inp;
void update (ll i, ll v) {
	if (i > 100000) return;
	bit[i] += v;
	update(i + (i & (-i)), v);
}
void update2 (ll i, ll v) {
	if (i > 100000) return;
	bit2[i] += v;
	update2(i + (i & (-i)), v);
}
ll query (ll i) {
	return ((i == 0) ? 0 : bit[i] + query(i - (i & (-i))));
}
ll query2 (ll i) {
	return ((i == 0) ? 0 : bit2[i] + query2(i - (i & (-i))));
}
