int n;
int a[100000];
vector<int>b;
vector<H>ans;
signed main() {
	cin >> n;
	int ma = 0;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		if (a[i] > ma) {
			b.push_back(i);
			ma = a[i];
		}
	}
	priority_queue<int>p;
	int sum = 0;
	for (int i = n - 1; i > b[b.size() - 1]; i--) {
		p.push(a[i]);
	}
	for (int i = b.size() - 1; i > 0; i--) {
		int res = (a[b[i]] - a[b[i - 1]])*sum;
		while (!p.empty() && p.top() >= a[b[i - 1]]) {
			res += p.top() - a[b[i - 1]];
			sum++;
			p.pop();
		}
		for (int j = b[i]; j > b[i - 1]; j--) {
			if (a[j] >= a[b[i - 1]]) {
				res += a[j] - a[b[i - 1]];
				sum++;
			}
			else p.push(a[j]);
		}
		ans.push_back(H{ b[i], res });
	}
	int rep = a[0] * sum;
	p.push(a[0]);
	while (!p.empty()) {
		rep += p.top();
		p.pop();
	}
	ans.push_back(H{ 0,rep });
	for (int i = ans.size() - 1; i >= 0; i--) {
		cout << ans[i].y << endl;
		for (int j = ans[i].x + 1; j < (i == 0 ? n : ans[i - 1].x); j++) {
			cout << 0 << endl;
		}
	}
}

