inline int hs(int x) {
    return lower_bound(tb+1,tb+tot+1,x)-tb;
}

int main() {
    int n;
    read(n);
    REP(i,1,n) read(a[i]),tb[++tot]=a[i];
    PER(i,n,1) {
        while(top && a[i]>a[stk[top]]) top--;
        stk[++top]=i;
    }
    sort(tb+1,tb+tot+1);
    tot=unique(tb+1,tb+tot+1)-tb-1;
    REP(i,1,n) a[i]=hs(a[i]);
    int now=tot,ps=1;stk[top+1]=0;
    PER(i,n,1) {
        cnt[a[i]]++;
        if(stk[ps]==i) {
