                val[stk[ps]]+=1LL*cnt[now]*(tb[now]-tb[a[stk[ps+1]]]);
                now--;cnt[now]+=cnt[now+1];
            } ps++;
        }
    }
    REP(i,1,n) printf("%lld\n",val[i]);
