        top = p.top();
        if( top == 0 ) break;
        while( p.top() == top ) p.pop();


        auto it = m.find(top);
        while( it != m.end() ){
            cnt++;
            ind = min( ind,it->second );
            m.erase(it);
            it = m.find(top);
        }

        diff = top - p.top();

        // printf ("!%llu: %llu*%llu \n", top, cnt, diff );

        ans[ind] += cnt*diff;
    }

    Rep(i,N){
        printf ("%llu\n", ans[i] );
    }

    return 0;
}

