using namespace std;
typedef long long ll;
ll n,s[100010];
ll t[100010];
ll p[100010];
ll c[100010],r[100010];
ll tims[100010];
ll tt[100010];
ll sum[100010];
struct node {
    ll num,pos;
}q[100010];

bool cmp(node &a,node &b)
{
    if(a.num==b.num)
        return a.pos<b.pos;
    else return a.num<b.num;
}

ll lowbit(ll x)
{
    return x&(-x);
}

void update(ll x,ll num)
{
    while(x<=n)
    {
        c[x]+=num;
        x+=lowbit(x);
    }
}

ll getsum(ll x)
{
    ll ans=0;
    while(x>0)
    {
        ans+=c[x];
        x-=lowbit(x);
    }
    return ans;
}

int main()
{
    while(cin>>n)
    {
        ll ans=0;
        memset(t,-1,sizeof(t));
        memset(c,0,sizeof(c));
        memset(tt,0,sizeof(tt));
        ll premax=0;
        ll cmax=0,p1=0,p2=0;
        for(int i=1;i<=n;i++)
        {
            scanf("%lld",&s[i]);
            q[i].num=s[i];
            ans+=s[i];
            q[i].pos=i;
            if(premax==0)
            {
                premax=s[1];
                p2=1;
                t[1]=s[1];
            }
            else if(s[i]<premax)
            {
                t[i]=0;
                if(s[i]>cmax)
                {
                    tt[p2]+=s[i]-cmax;
                }
            }
            else
            {
                t[i]=s[i]-premax;
                cmax=premax;
                p1=p2;
                premax=s[i];
                p2=i;
            }
        }
        sort(q+1,q+n+1,cmp);
        for(int i=1;i<=n;i++)
        {
            s[q[i].pos]=i;
        }
        for(int i=n;i>=1;i--)
        {
            r[s[i]]=getsum(s[i]);
            tims[i]=1+n-i-r[s[i]];
            update(s[i],1);
        }
        for(int i=2;i<=n;i++)
        {
            tt[i]+=1ll*tims[i]*t[i];
            ans-=tt[i];
        }
        tt[1]=ans;
        for(int i=1;i<=n;i++)
            printf("%lld\n",tt[i]);

    }
}

