	template<class T,class U> decltype(auto) operator+(T const& lhs, U const& rhs)
	{
		auto x = lhs;
		x += rhs;
		return x;
	}
	template<class T, class U> decltype(auto) operator-(T const& lhs, U const& rhs)
	{
		auto x = lhs;
		x -= rhs;
		return x;
	}
	template<class T, class U> decltype(auto) operator*(T const& lhs, U const& rhs)
	{
		auto x = lhs;
