	template<class T>struct equality_comparable
	{
		 decltype(auto) operator!=(equality_comparable<T>const& rhs)const
		{
			return !(static_cast<T const&>(*this) == static_cast<T const&>(rhs));
		}

	};
	template<class T>struct less_than_comparable
	{
		 decltype(auto)operator<(equality_comparable<T>const& rhs)const
		{
			return static_cast<T const&>(*this) < static_cast<T const&>(rhs);
		}
		 decltype(auto)operator>(T const& rhs)const
		{
			return rhs < *this;
		}
		 decltype(auto)operator<=(T const& rhs)const
		{
			return !(rhs < *this);
		}
		 decltype(auto)operator>=(T const& rhs)const
		{
			return !(*this < rhs);
		}

	};
	template<class T>struct addable
	{
		 decltype(auto) operator+=(addable<T>const& rhs)
		{
			return static_cast<T const&>(*this) += static_cast<T const&>(rhs);
		}
		friend  decltype(auto) operator+(addable<T>const& lhs, addable<T>const& rhs);
	};
	template<class T>struct subtractable
	{
		 decltype(auto) operator-=(subtractable<T>const& rhs)
		{
			return static_cast<T const&>(*this) -= static_cast<T const&>(rhs);
		}

		friend  decltype(auto) operator-(subtractable<T>const& lhs, subtractable<T>const& rhs);
	};
	template<class T>struct multipliable
	{
		 decltype(auto) operator*=(multipliable<T>const& rhs)
		{
			return static_cast<T const&>(*this) *= static_cast<T const&>(rhs);
		}
		friend  decltype(auto) operator*(multipliable<T>const& lhs, multipliable<T>const& rhs);
	};
	template<class T>struct dividable
	{
		 decltype(auto) operator/=(dividable<T>const& rhs)
		{
			return static_cast<T const&>(*this) /= static_cast<T const&>(rhs);
		}
		friend  decltype(auto) operator/(dividable<T>const& lhs, dividable<T>const& rhs);
	};

	struct nullopt_t
	{

	};
	constexpr nullopt_t nullopt{};
	template<class T>class optional:private equality_comparable<optional<T>>
	{
		union
		{
			T val;
			nullopt_t null;
		};
		bool flag;
	public:
		 optional(nullopt_t n = nullopt) : null(), flag(false)
		{

		}

		 T& operator*()
		{
			if (flag)
			{
				return val;
			}
			throw std::invalid_argument("this optional value has not any value");
		}
		 T const& operator*()const
		{
			if (flag)
			{
				return val;
			}
			throw std::invalid_argument("this optional value has not any value");
		}
		 void reset()
		{
			null = nullopt;
			flag = false;
		}
		 operator bool()const
		{
			return flag;
		}
		template<class... Us>void emplace(Us&&... args)
		{
			val = T(std::forward<Us>(args)...);
			flag = true;
		}
		 auto& operator=(T const& v)
		{
			val = v;
			flag = true;
			return *this;
		}
		 auto& operator=(T&& v)
		{
			val = v;
			flag = true;
			return *this;
		}
		 auto& operator=(nullopt_t)
		{
			null = nullopt;
			flag = false;
			return *this;
		}

		 optional(T const& v) :optional()
		{
			*this = v;
		}
		 optional(T&& v) : optional()
		{
			*this = std::move(v);
		}

		 bool operator==(optional const& rhs)const
		{
			return flag&&rhs.flag ? val == rhs.val : flag == rhs.flag;
		}

		optional(optional const&) = default;
		optional(optional&&) = default;
		optional& operator=(optional const&) = default;
		optional& operator=(optional&&) = default;
		~optional() = default;

	};
}
namespace math
{
	template<class T>constexpr T pow(T val, std::uint64_t p)
	{
		return p == 0 ? T(1) :
			p == 1 ? val :
			p == 2 ? val*val :
			p % 2 == 0 ? pow(pow(val, p / 2), 2) :
			pow(pow(val, p / 2), 2)*val;
	}
	template<class T,class U>constexpr int ilog(T val, U base)
	{
		T v(1);
		for (int i{};;++i)
		{
			if (val <= v)
			{
				return i;
			}
			v *= base;
		}
	}

