	int vr=query(a,b,k*2+2,(l+r)/2,r);
	return vl+vr;
}


void update2(int k,ll a){
	k+=n_-1;
	dat2[k]+=a;
	while(k>0){
		k=(k-1)/2;
		dat2[k]=dat2[k*2+1]+dat2[k*2+2];
	}
}

ll query2(int a,int b,int k=0,int l=0,int r=n_){
	if(r<=a || b<=l)return 0;
	if(a<=l && r<=b)return dat2[k];
	ll vl=query2(a,b,k*2+1,l,(l+r)/2);
	ll vr=query2(a,b,k*2+2,(l+r)/2,r);
	return vl+vr;
}

