long long int addNum(vector<long long int> *nums, int a, long long int secMax)
{
    int add = nums->at(a) - secMax;
    nums->at(a) = secMax;
    return add;
}

int main()
{
    int n;
    cin >> n;
    vector<long long int> nums(n,-1);
    vector<long long int> s(n,0);
    for(int i=0; i < n; ++i)
    {
        long long int num;
        cin >> num;
        nums.at(i) = num;
    }

    bool isClear = false;
    while(!isClear)
    {
        int max = -1;
        int secMax = -1;
        vector<int> sub;
        //最大値を探す
        for(int i = 0; i < n; ++i)
        {
            if(max == -1)
            {
                max = i;
                continue;
            }
            if(nums.at(i) > nums.at(max))
            {
                secMax = max;
                max = i;
                sub.clear();
            }
            else if(secMax != -1 && nums.at(secMax) <= nums.at(i))
            {
                sub.push_back(i);
            }
            else if(secMax == -1)
            {
                sub.push_back(i);
            }
        }
        //計算
        if(max == 0)
        {
            isClear = true;
        }
        long long int add = 0;
        long long int secNum = 0;
        if(secMax != -1)
        {
            secNum = nums.at(secMax);
        }
        add += addNum(&nums, max, secNum);

        for(int su : sub)
        {
            add += addNum(&nums, su, secNum);
        }

        s.at(max) += add;
    }

    for(long long int snum : s)
    {
        cout << snum << endl;
    }
}

