#include<bits/stdc++.h>
using namespace std;

typedef pair<int, int> pii;
typedef long long ll;

int N;
vector<int> arr;

struct BIT {
    vector<pii> tree;
    void init() {
        tree = vector<pii>(4*N, pii(-1, -1));
    }
    void upd(int idx, pii val, int l, int r, int n) {
        if(idx < l || r < idx) return;
        if(l == r) {
            tree[n] = val;
            return;
        }
        int m = (l + r)>>1;
        upd(idx, val, l, m, 2*n);
        upd(idx, val, m + 1, r, 2*n + 1);
        tree[n] = max(tree[2*n], tree[2*n + 1]);
    }
    pii quer(int a, int b, int l, int r, int n) {
        if(b < l || r < a) return pii(0, 0);
        if(a <= l && r <= b) return tree[n];
        int m = (l + r)>>1;
        pii L = quer(a, b, l, m, 2*n);
        pii R = quer(a, b, m + 1, r, 2*n + 1);
        return max(L, R);
    }
} bit;

vector<ll> S;
int main() {
    scanf("%d", &N);
    arr.resize(N);
    bit.init();
    for(int i = 0; i < N; i++) {
        scanf("%d", &arr[i]);
        bit.upd(i, pii(arr[i], -i), 0, N - 1, 1);
    }
    pii t = bit.quer(0, N - 1, 0, N - 1, 1);
    S = vector<ll>(N, 0);
    while(1) {
        if(t == pii(0, 0)) break;
        pii x = bit.quer(0, -t.second - 1, 0, N - 1, 1);
        while(x < bit.quer(-t.second + 1, N - 1, 0, N - 1, 1)) {
            pii d = bit.quer(-t.second + 1, N - 1, 0, N - 1, 1);
            S[-t.second] += d.first - x.first;
            d.first = x.first;
            bit.upd(-d.second, d, 0, N - 1, 1);
        }
        S[-t.second] += t.first - x.first;
        t.first = x.first;
        bit.upd(-t.second, t, 0, N - 1, 1);
        t = bit.quer(0, N - 1, 0, N - 1, 1);
    }
    for(int i = 0; i < S.size(); i++) {
        printf("%lld\n", S[i]);
    }
}

