ll N_ = 1;
ll seg[(1 << 20) - 1], lazy[(1 << 20) - 1];

void eval(ll k, ll l, ll r){
  if(lazy[k] == 0) return;
  seg[k] += lazy[k] * (r - l);
  if(r - l > 1){
    lazy[2 * k + 1] += lazy[k];
    lazy[2 * k + 2] += lazy[k];
  }
  lazy[k] = 0;
}

void update(ll a, ll b, ll x, ll k, ll l, ll r){
  eval(k, l, r);
  if(r <= a || b <= l) return;
  if(a <= l && r <= b){
    lazy[k] += x;
    eval(k, l, r);
    return;
  }
  update(a, b, x, 2 * k + 1, l, (l + r) / 2);
  update(a, b, x, 2 * k + 2, (l + r) / 2, r);
  seg[k] = seg[2 * k + 1] + seg[2 * k + 2];
  return;
}

ll sum(ll a, ll b, ll k, ll l, ll r){
  if(r <= a || b <= l) return 0;
  eval(k, l, r);
  if(a <= l && r <= b) return seg[k];
  ll res = 0;
  res += sum(a, b, 2 * k + 1, l, (l + r) / 2);
  res += sum(a, b, 2 * k + 2, (l + r) / 2, r);
  return res;
}


