      ans[curi] += ((*itr).first - nxM)*(*itr).second;
      mp[nxM] += (*itr).second;
      mp.erase(itr++);
    }
    for (ll i = curi - 1; i > nxi; i--){
      mp[as[i]]++;
    }
    curM = nxM;
    curi = nxi;
  }
  for(auto [k, v] : mp) ans[0] += v;
