const int M = 18;
const ll MAP = 202020;
map<ll,ll> zip;
ll unzip[MAP];

template<class V, int ME> class BIT {
public:
    V bit[1<<ME];
    V total(int e) {V s=0;e++;while(e) s+=bit[e-1],e-=e&-e; return s;}
    void add(int e, V val) {e++; while(e<=1<<ME) bit[e-1]+=val,e+=e&-e;}
};

BIT<ll, M> bit;

ll compress(vector<ll> &x) {
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    for(int i = 0; i < x.size(); i++){
        zip[x[i]] = i;
        unzip[i] = x[i];
    }
    return x.size();
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;
    vector<ll> A(N);
    REP(i, N) cin >> A[i];
    vector<ll> AA(N);
    REP(i, N) AA[i] = A[i];
    compress(AA);

    vector<ll> X(N), Y(N);
    REP(i, 1ll<<M) bit.bit[i] = 0;
    const ll MA = (1ll<<M)-1;

    for(int i=N-1;i>=0;i--){
    	bit.add(zip[A[i]], 1);
    	X[i] = bit.total(MA) - bit.total(zip[A[i]]-1);
    }

    const ll INF = (1ll<<60);
    set<ll> st;
    map<ll, ll> mp;
    mp[0] = -1;
    st.insert(0);
    st.insert(INF);
    REP(i, N){
    	auto itr = st.lower_bound(A[i]);
    	itr--;
    	ll val = *itr;
    	Y[i] = mp[val];
    	st.insert(A[i]);
    	if(mp.find(A[i]) == mp.end()) mp[A[i]] = i;
    }

    vector<ll> res(N, 0);
    ll idx = mp[*(--(--st.end()))];

    while(idx >= 0){
    	ll mae = (Y[idx] == -1 ? 0 : A[Y[idx]]);
    	res[idx] = X[idx] * (A[idx] - mae);
    	idx = Y[idx];
    }

    //cout << X << endl;
    //cout << Y << endl;
    REP(i, N) cout << res[i] << endl;
    return 0;
}

