template<class Monoid>
class SegmentTree {

public:
    /**
     * @param N size
     * @param e identity element
     * @param operation operation to merge `data`
     * @param updater operation to update `data`
     */
    SegmentTree(size_t N, Monoid e, function<Monoid(Monoid, Monoid)> operation,
                function<Monoid(Monoid, Monoid)> updater)
            : e(e), operation(operation), updater(move(updater)) {
        n = 1;
        while (n < N) {
            n *= 2;
        }
        data = vector<Monoid>(2 * n - 1, e);
        for (int i = n - 2; i >= 0; i--) {
            data[i] = operation(data[2 * i + 1], data[2 * i + 2]);
        }
    }

    /**
     * iの値をxに更新 ( 0-indexed )
     */
    void update(int i, Monoid x) {
        i += n - 1;
        data[i] = updater(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    /**
     * [a, b)の区間でクエリを実行
     */
    Monoid query(int a, int b) {
        return query(a, b, 0, 0, n);
    }

    /**
     * 添字でアクセス( 0-indexed )
     */
    Monoid operator[](int i) {
        return data[i + n - 1];
    }

private:
    int n;
    vector<Monoid> data;
    Monoid e;
    function<Monoid(Monoid, Monoid)> operation;
    function<Monoid(Monoid, Monoid)> updater;

    Monoid query(int a, int b, int k, int l, int r) {
        // 交差しない
        if (r <= a || b <= l) return e;
        // 区間 [a, b) に l, r が含まれる
        if (a <= l && r <= b) return data[k];
        // 左の子
        Monoid c1 = query(a, b, 2 * k + 1, l, (l + r) / 2);
        // 右の子
        Monoid c2 = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return operation(c1, c2);
    }
};


void solve() {
    ll N;
    cin >> N;
    vector<ll> A(N);
    rep(i, N) cin >> A[i];
    ll s = accumulate(A.begin(), A.end(), 0LL);
    SegmentTree<P> segmentTree(N + 1, {0, 0}, [](P a, P b) {
        if (a.first == b.first) {
            if (a.second < b.second) {
                return a;
            } else {
                return b;
            }
        } else {
            if (a.first > b.first) {
                return a;
            } else {
                return b;
            }
        }
    }, [](P a, P b) { return b; });
    rep(i, N) {
        ll a = A[i];
        segmentTree.update(i, {a, i});
    }
    sort(A.begin(), A.end());
    vector<ll> ans(N);
    ll idx = N;
    while (s != 0) {
        P m = segmentTree.query(0, idx);
        print(s);
        print(m);
        if (m.second == 0) {
            ans[0] = s;
            s = 0;
        } else {
            P m2 = segmentTree.query(0, m.second);
            ll a = m.first;
            ll cnt = A.end() - lower_bound(A.begin(), A.end(), a);
            ans[m.second] += (m.first - m2.first) * cnt;
            s -= ans[m.second];
            idx = m.second;
        }
    }
    rep(i, N) {
        cout << ans[i] << '\n';
    }
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    solve();
    return 0;
}

