using namespace std;
typedef long long ll;
struct mount {
	ll a, i;

	bool operator<(const mount& m)const {
		return a == m.a ? i < m.i : a < m.a;
	}
};

ll n, N, a[100000], ans[100000];
mount seg[100000 * 2 - 1], b[100000];

void init(ll n_){
	n = 1;
	while (n < n_)n *= 2;

	for (int i = 0; i < 2 * n - 1; i++)seg[i] = mount{ 0, -1 };
}

void update(ll k, mount a) {
	k += n - 1;
	seg[k] = a;

	while (k > 0) {
		k = (k - 1) / 2;
		seg[k] = max(seg[k * 2 + 1], seg[k * 2 + 2]);
	}
}

mount query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l)return mount{ 0, -1 };

	if (a <= l && r <= b)return seg[k];
	else {
		mount ml = query(a, b, k * 2 + 1, l, (l + r) / 2);
		mount mr = query(a, b, k * 2 + 2, (l + r) / 2, r);

		return max(ml, mr);
	}
}

int main() {
	cin >> N;
	for (int i = 0; i < 100000; i++) {
		if (i < N) {
			cin >> a[i];
			b[i] = mount{ a[i], i };
		}
		else b[i] = mount{ 0, -1};
	}

	//セグメント木の初期化
	init(N);
	for (int i = 0; i < n; i++) {
		update(i, b[i]);
	}

	//全体のソート
	sort(b, b + N);
	int r = N-1, mr = N, i = N-1;
	mount m = query(0, n, 0, 0, n);

	while (true) {
		mount x = query(0, m.i, 0, 0, n);
		//cout << "m.i:" << m.i << " m.a:" << m.a << endl;
		//cout << "x.i:" << x.i << " x.a:" << x.a << endl;

		while(b[i].a >= x.a && m.i <= b[i].i && i >= 0) {
			//cout << "i:" << i << endl;
			ans[m.i] += b[i].a - x.a;
			i--;
		}

		//cout << "(N - mr):" << (N - mr) << " (m.a - x.a):" << (m.a - x.a) << endl;
		ans[m.i] += (N - mr)*(m.a - x.a);
		if (i == -1)break;
		mr = i+1;
		m = x;
	}

	for (int i = 0; i < N; i++) {
		cout << ans[i] << endl;
	}
}

