const int INF = 1e+9 + 10;

struct node_t {
  int l, r, val;

  node_t(int l, int r, int val) : l(l), r(r), val(val) {
  }
};

struct segment_tree_t {
  vector<node_t> data;
  int sz = INF;
  int root = 0;

  segment_tree_t() {
    data.emplace_back(-1, -1, 0);
  }

  void inc(int pos) {
    inc(root, 0, sz, pos);
  }

  void inc(int v, int l, int r, int pos) {
    if (l == r) {
      ++data[v].val;
      return;
    }

    if (data[v].l == -1) {
      data[v].l = data.size();
      data.emplace_back(-1, -1, 0);
    }
    if (data[v].r == -1) {
      data[v].r = data.size();
      data.emplace_back(-1, -1, 0);
    }
    int m = (r + l) / 2;
    if (pos <= m)
      inc(data[v].l, l, m, pos);
    else
      inc(data[v].r, m + 1, r, pos);
    data[v].val = data[data[v].l].val + data[data[v].r].val;
  }

  int get(int val) {
    return get(root, 0, sz, val, sz);
  }

  int get(int v, int l, int r, int ql, int qr) {
    if (ql == l && qr == r)
      return data[v].val;

    int m = (r + l) / 2;
    if (qr <= m)
      return get(data[v].l, l, m, ql, qr);
    if (ql > m)
      return get(data[v].r, m + 1, r, ql, qr);
    return get(data[v].l, l, m, ql, m) + get(data[v].r, m + 1, r, m + 1, qr);
  }
};

int main() {
  auto start = high_resolution_clock::now();

  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n;
  cin >> n;
  vector<int> a(n + 1);
  a[0] = 0;
  for (int i = 1; i <= n; ++i)
    cin >> a[i];
  vector<long long> ans(n + 1, 0);

  map<int, int> mp;
  for (int i = n; i >= 0; --i)
    mp[a[i]] = i;

  auto iter = mp.rbegin();
  int cval = iter->first;
  int pos = iter->second;

  segment_tree_t st;
  for (int i = n; i >= pos; --i)
    st.inc(a[i]);

  while (cval > 0) {
    ++iter;
    while (iter->second >= pos)
      ++iter;
    const int nval = iter->first;
    const int npos = iter->second;

    ans[pos] = 1LL * (a[pos] - a[npos]) * st.get(cval);

    while (pos > npos)
      st.inc(a[--pos]);

    cval = nval;
  }

  for (int i = 1; i <= n; ++i)
    cout << ans[i] << '\n';

  cerr << "Total execution time : " << duration_cast<milliseconds>(high_resolution_clock::now() - start).count() << " ms" << endl;

  return 0;
}

