using namespace std;

typedef	pair<int, int>	P;

struct CustomCompare
{
	bool operator()(const P& a1, const P& a2)  const
	{
		// first: id, second: num
		if (a1.second < a2.second) {
			return true;
		}
		if ((a1.second == a2.second) && (a1.first > a2.first)) {
			return true;
		}
		return false;
	}
};

priority_queue<P, vector<P>, CustomCompare> que;
map<int, int> ll;
vector<int> seq;

void print_que(void) {
	cout << "----------------------------------------v" << endl;
	priority_queue<P, vector<P>, CustomCompare> tmp = que;
	for (int i = 0; !tmp.empty(); i++) {
		P pile = tmp.top();
		tmp.pop();
		cout << "[" << i << "] " << pile.first << ", " << pile.second << endl;
	}
	cout << "----------------------------------------^" << endl;
}

void removeStone()
{
	int num = que.top().second;
	queue<P> tmp;
	while (!que.empty()) {
		P pile = que.top();
		if (num != pile.second) {
			break;
		}
		que.pop();
		tmp.push(pile);
	}
	while (tmp.size() > 1) {
		P pile = tmp.front();
		tmp.pop();
		que.push(pile);
	}
	P pile = tmp.front();
	pile.second--;
	if (pile.second > 0) {
		que.push(pile);
	}
}

void addResult(int num)
{
	// add into vector for making result
	if (ll.count(num) == 0) {
		ll[num] = 1;
	} else {
		ll[num] += 1;
	}
	//cout << "ll: " << num << " count: " << ll[num] << endl;
}

void addQue(int index, int num)
{
	que.push(make_pair(index, num));
}

bool solve(int N)
{
	int sz = que.size();
	while (!que.empty()) {
		//print_que();
		// get the largest pile
		P pile = que.top();
		que.pop();
		int num = pile.first;	// first == index
		que.push(pile);	// restore
		// add into sequence
		seq.push_back(num);
		// remove 1 from a pile
		removeStone();
		//
		addResult(num);
	}
	//
	for (int i = 1; i < N+1; i++) {
		if (ll.count(i) == 0) {
			//cout << i << " " << 0 << endl;
			cout << 0 << endl;
		} else {
			//cout << i << " " << ll[i] << endl;
			cout << ll[i] << endl;
		}
	}
	#if 0
	cout << "seq: ";
	for (vector<int>::iterator it = seq.begin(); it != seq.end(); it++) {
		cout << *it;
	}
	cout << endl;
	#endif
	return false;
}

int main(int argc, char** argv, char** opt) {
#if 1
