int main() {
    cin >> N;

    using X = pair<ll, int>;
    auto fx = [](X x1, X x2) -> X {
        if (x1.first >= x2.first) {
            return x1;
        } else {
            return x2;
        }
    };
    X ex = make_pair(-INF, -1);
    SegTree<X> rmq(N, fx, ex);

    vector<ll> a(N);
    for (int i = 0; i < N; i++) {
        cin >> a.at(i);
        rmq.set(i, make_pair(a[i], i));
    }
    rmq.build();

    vector<ll> S(N + 1);
    vector<ll> b = a;
    sort(ALL(b));
    for (int i = 0; i < N; i++) {
        S[i + 1] = S[i] + b[i];
    }

    vector<ll> ans(N, 0);
    X now = rmq.query(0, N);
    ll tmp = 0;
    while (now.second > 0) {
        X next = rmq.query(0, now.second);
        int id = lower_bound(ALL(b), next.first) - b.begin();
        ll sum = (S[N] - S[id]) - next.first * (N - id);
        ans[now.second] += sum - tmp;
        tmp = sum;
        now = next;
    }
    ans[0] = now.first * N;

    for (auto i : ans) {
        cout << i << endl;
    }

    return 0;
}

