ll ans[N],a[N],lazy[N];
vector <pll> v;

int main(){
	ll n,x;
	scanf("%lld",&n);
	REP(i,n){
		scanf("%lld",&a[i]);
		if (!i){
			v.pb(mp(a[i],i));
			ans[i]+=a[i];
		}
		else{
			if (a[i]>v.back().X){
				v.pb(mp(a[i],i));
				lazy[sz(v)-1]+=1;
			}
			else{
				if (a[i]<=a[0]){
					ans[0]+=a[i];
					continue;
				}
				x=lower_bound(all(v),mp(a[i],-1ll))-v.begin();				
				if (a[i]<v[x].X){
					ans[x]+=a[i]-v[x-1].X;
					a[i]=v[x-1].X;
					x--;
				}
				lazy[x]+=1;
			}
		}
	}
	for(int i=sz(v)-1;i>=0;i--){
		ans[v[i].Y]+=lazy[i]*(v[i].X);
		if (i) ans[v[i].Y]-=lazy[i]*v[i-1].X;
		lazy[i-1]+=lazy[i];
	}
	REP(i,n) printf("%lld\n",ans[i]);
	return 0;
}

