void solve(ll N, vector<ll> a) {
  vector<pair<ll,ll>> vec;
  REP(i,N) vec.emplace_back(a[i], i);
  sort(vec.rbegin(), vec.rend());
  vector<ll> res(N);
  ll now = vec.front().second, val = vec.front().first, cnt = 0;
  for (auto p: vec) {
    // cout << now << " " << val << " " << cnt << endl;
    if (p.second >= now) {
      res[now] += (val - p.first) * cnt;
      ++cnt;
      val = p.first;
    }
    else {
      res[now] += (val - p.first) * cnt;
      now = p.second;
      val = p.first;
      ++cnt;
    }
    // for (ll i: res) cout << i << " ";
    // cout << endl;
  }
  res[0] += val * cnt;
  for (ll i: res) cout << i << endl;
}

