int n, a[100010];
vi solve_naive(){
	vi ans(n),  aprev(n); rep(i, n) aprev[i] = a[i];
	rep(it, n){
		int mx = -1, mxi, mx2 = -1, mx2i;
		rep(i, n) if(a[i] > mx) mx = a[i], mxi = i;
		rep(i, mxi) if(a[i] > mx2) mx2 = a[i], mx2i = i;
		if(mx2 < 0){
			rep(i, n) ans[mxi] += a[i];
			break;
		}
		int cnt = 0;
		for(int i = mxi; i < n; i++){
			cnt += max(0, a[i] - mx2);
			a[i] = min(a[i], mx2);
		}
		ans[mxi] += cnt;
	}
	rep(i, n) a[i] = aprev[i];
	return ans;
}
int main(){
	cin.tie(0); cin.sync_with_stdio(0);

	cin >> n;
	rep(i, n) cin >> a[i+1];
	//dbg(solve_naive());
	n++;
	vi idx;
	int prev = -1;
	rep(i, n) if(a[i] > prev){
		prev = a[i];
		idx.pb(i);
	}
	set<pi> vals;
	vector<ll> ans(n);
	for(int ii = idx.size() - 1, j = n - 1; ii > 0; ii--){
		int i = idx[ii - 1];
		while(j > i){
			if(a[j] >= a[i]) ans[i] += a[j] - a[idx[ii]];
			else vals.emplace(-a[j], j);
			j--;
		}
		set<pi> dels;
		for(auto it = vals.begin(); it != vals.end() && -it->first >= a[i]; it++){
			dels.insert(*it);
			ans[idx[ii]] += -it->first - a[idx[ii]];
		}
		for(auto it : dels) vals.erase(it);

		ans[idx[ii]] += (n - 1 - i - vals.size()) * (a[idx[ii]] - a[i]);
	}
	rep(i, n-1) cout << ans[i+1] << endl;

	return 0;
}

