        if(x > rhs.x) return true;return false;
    }
} p[maxn];

int main() {
    int n;
    int a;
    LL sum, ans;
    sum = ans = 0;
    bool check = true;
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) {
        scanf("%d", &a);
        p[i].num = i;
        p[i].x = a;
        sum += a;
    }
    sort(p + 1, p + n + 1);
    int s = 0;
    for(int i = 1; i <= n; i++) {
        if(p[i].x == p[i - 1].x) t[p[i].num] = 0;
        else {
            if(s == 0) s = i;
            else if(p[s].num < p[i].num) t[p[i].num] = 0;
            else {
                t[p[s].num] = (p[s].x - p[i].x) * (i - 1);
                s = i;
