char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}


void solve(int N, vi& a) {
    map<int,vi> st;
    rep(i,N) {
        st[a[i]].pb(1+i);
    }
    // cerr << st << endl;

    vector<ll> b(N+1, 0);

    // ai <= 1e9
    priority_queue<int> pq;

    ll last_w=0, last_ai=INT_MAX;
    for (auto it=st.rbegin(); it!=st.rend(); ++it) {
        int ai = it->first; // vi is = z.second;
        if (!pq.empty()) {
            int top = -pq.top();
            b[top] += last_w * (last_ai - ai);
            // fprintf(stderr, "b[%d] = %d x (%d - %d) = %d\n",
            //     last_top, last_w, last_ai, ai, b[last_top]);
        }

        pq.push(-it->second[0]);
        last_w += it->second.size();
        last_ai = ai;
    }

    b[-pq.top()] += last_w * (last_ai - 0);

    rep1(i,N) {
        printf("%lld\n", b[i]);
    }
}

