using namespace std;
typedef long long lint;
typedef pair<int, int> pii;
typedef pair<int, lint> pil;

typedef struct SegTree{
    int n = 1;
    vector<pil> node;

    SegTree(int n_){
        while(n < n_) n *= 2;
        node.resize(2*n-1, pil(0, 0));
    }

    void update(int i, int x){
        i += n-1;
        node[i] = pil(i-n+1, x);
        while(i){
            i = (i-1) / 2;
            if(node[2*i+1].se >= node[2*i+2].se) node[i] = node[2*i+1];
            else node[i] = node[2*i+2];
        }
    }

    pil query(int a, int b, int i, int l, int r){
        if(r<=a || b<=l) return pil(0, 0);
        if(a<=l && r<=b) return node[i];
        pil pl = query(a, b, 2*i+1, l, (l+r)/2);
        pil pr = query(a, b, 2*i+2, (l+r)/2, r);
        if(pl.se >= pr.se) return pl;
        else return pr;
    }
}ST;

int main(){
    int n;
    scanf("%d", &n);
    ST st(n+1);
    map<lint, lint> mp;
    lint asum = 0;
    rep(i, n){
        lint a;
        scanf("%lld", &a);
        st.update(i+1, a);
        ++mp[a];
        asum += a;
    }
    lint ans[n+1];
    rep(i, n+1) ans[i] = 0;
    pil p = st.query(0, n+1, 0, 0, st.n);
    pil np = st.query(0, p.fi, 0, 0, st.n);
    while(p.fi){
        ans[p.fi] = (lint)(p.se - np.se) * mp[p.se];
        mp[np.se] += mp[p.se];
        mp.erase(p.se);
        p = np;
        np = st.query(0, p.fi, 0, 0, st.n);
    }
    for(auto itr=mp.begin(); itr!=mp.end(); ++itr) ans[1] += itr->fi;
    rep(i, n) asum -= ans[i+1];
    assert(asum == 0);
    rep(i, n) printf("%lld\n", ans[i+1]);
}

