    int n; cin >> n;
    vector<ll> arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];
    ll sum = accumulate(arr.begin(), arr.end(), 0LL);
    // if (arr[0] == *max_element(arr.begin(), arr.end())){
    //     cout << sum << endl;
    //     for (int i = 0; i < n-1; i++) cout << 0 << endl;
    //     return 0;
    // }

    vector<ll> ans(n);

    vi high(n, n);
    stack<int> stk;
    for (int i = n-1; i >= 0; i--){
        while (!stk.empty() && arr[stk.top()] <= arr[i]){
            stk.pop();
        }

        if (!stk.empty())
            high[i] = stk.top();
        stk.push(i);
    }
    //debug(high);
    vi chain = {0};
    while (high[chain.back()] != n) chain.push_back(high[chain.back()]);
    //debug(chain);

    int m = (int)chain.size();
    chain.push_back(n);
    priority_queue<ll> pq;
    ll carry = 0;
    for (int i = m-1; i > 0; i--){
        int x = chain[i];
        for (int j = chain[i+1]-1; j > x; j--) pq.push(arr[j]);
        ll nxt = arr[chain[i-1]], d = arr[x] - nxt;
        carry++;
        ans[x] += carry * d;
        while (!pq.empty() && pq.top() >= nxt) {
            ans[x] += pq.top() - nxt;
            carry++;
            pq.pop();
        }
    }
    ans[0] = sum - accumulate(ans.begin(), ans.end(), 0LL);
    for (ll x : ans)
        cout << x << endl;
}

