typedef unordered_set<int> llSet;

ll sz = (1ll << 25);
ll tree[(1ll << 25) + 1ll];

void bitSet(ll v, ll x) {
  while(x <= sz) {
    tree[x] += v;
    x += (x & -x);
  }
}
ll getUpTo(ll x) {
  ll ret = 0;
  while(x >= 1) {
    ret += tree[x];
    x -= (x & -x);
  }
  return ret;
}



