struct segment_tree {
	int t[N << 2];
	segment_tree() {
		fill(t, t + (N << 2), -inf);
	}
	void update(int v, int tl, int tr, int pos, int val){
		if(tl == tr)
			t[v] = val;
		else {
			int mid = tl + tr >> 1;
			if(pos <= mid)
				update(v << 1, tl, mid, pos, val);
			else
				update(v << 1 | 1, mid + 1, tr, pos, val);
			t[v] = max(t[v << 1], t[v << 1 | 1]);
		}
	}
	int get(int v, int tl, int tr, int l, int r) {
		if(tl > r || tr < l)
			return -inf;
		if(tl >= l && tr <= r)
			return t[v];
		int mid = tl + tr >> 1;
		return max(get(v << 1, tl, mid, l, r), get(v << 1 | 1, mid + 1, tr, l, r));
	}
} t;

inline int getf() {
	int l = 1, r = n, res = -1;
	while(l <= r) {
		int mid = l + r >> 1;
		if(t.get(1, 1, n, 1, mid) <= 0)
			l = mid + 1;
		else
			r = mid - 1, res = mid;
	}
	assert(res != -1);
	return res;
}

inline int getlast() {
	int l = 1, r = n, res = -1;
	while(l <= r) {
		int mid = l + r >> 1;
		if(t.get(1, 1, n, mid, n) <= 0)
			r = mid - 1;
		else
			l = mid + 1, res = mid;
	}
	assert(res != -1);
	return res;
}

inline int get_last_with_val(int x) {
	int l = 1, r = n, res = -1;
	while(l <= r) {
		int mid = l + r >> 1;
		if(t.get(1, 1, n, mid, n) == x)
			l = mid + 1, res = mid;
		else
			r = mid - 1;
	}
	assert(res != -1);
	return res;
}

inline void del(int i) {
	is.erase({-a[i], i});
	t.update(1, 1, n, i, --a[i]);
	if(a[i])
		is.insert({-a[i], i});
}

main() {
	ios_base::sync_with_stdio(0); cout.tie(0); cin.tie(0);
	// setin("input.txt");
	cin >> n;
	for(int i = 1; i <= n; ++i) {
		cin >> a[i];
		is.insert({-a[i], i});
		t.update(1, 1, n, i, a[i]);
	}
	while(!is.empty()) {
		int i = is.begin()->se;
		++cnt[i];

		int f = getf();
		if(i == f)
			del(getlast());
		else
			del(get_last_with_val(a[i]));
	}
	for(int i = 1; i <= n; ++i)
		cout << cnt[i] << endl;
	return 0;
}

