struct heap {
   priority_queue<int> q;
   ll sum = 0;
   int cnt = 0;
   int cutoff = 2e9;
   void recalc() {
      while (q.size() && q.top() >= cutoff) {
         ++cnt;
         sum += q.top();
         q.pop();
      }
   }
   void modify(int __cutoff) {
      cutoff = __cutoff;
      recalc();
   }
   void push(int v) {
      q.push(v);
      recalc();
   }
   ll get() { return sum - ll(cnt) * cutoff; }
} hp;

int main() {
   ios_base::sync_with_stdio(false);
   int N;
   cin >> N;
   vector<int> A(N);
   vector<ll> ans(N);
   for (int i = 0; i < N; ++i) cin >> A[i];
   vector<int> st;
   for (int i = N - 1; i >= 0; --i) {
      while (st.size() && A[st.back()] <= A[i]) {
         st.pop_back();
      }
      st.emplace_back(i);
   }
   ll last = 0;
   int ptr = N - 1;
   for (int i = 0; i + 1 < int(st.size()); ++i) {
      hp.modify(A[st[i + 1]]);
      while (ptr > st[i + 1]) {
         hp.push(A[ptr--]);
      }
      ans[st[i]] = hp.get() - last;
      last = hp.get();
   }
   assert(st.back() == 0);
   last = -last;
   for (int i = 0; i < N; ++i) {
      last += A[i];
   }
   ans[0] = last;
   for (int i = 0; i < N; ++i) cout << ans[i] << "\n";
}

