    vector<pair<pll, ll>> elements;
    map<ll, ll> freq, leftmostindex;

    for (auto x : a) {
        freq[x]++;
        leftmostindex[x] = n + 1;
    }

    for (ll i = 0; i < n; i++) {
        amin(leftmostindex[a[i]], i);
    }

    elements.reserve(freq.size());
    for (auto x : freq) {
        elements.emplace_back(x, leftmostindex[x.first]);
    }

    sort(all(elements));

    ll sum = 0, idx = sz(elements) - 1;
    v printed(n, 0);

    while (true) {
        sum += elements[idx].first.second;

        ll next = idx - 1;
        while (next >= 0 && elements[next].second > elements[idx].second) {
            next--;
        }
        if (next == -1)break;

        ll val1 = elements[idx].first.first;
        ll val2 = elements[next].first.first;
        ll diff = val1 - val2;
        ll add = sum * diff;

        for (ll k = next + 1; k < idx; k++) {
            sum += elements[k].first.second;
            add += elements[k].first.second * (elements[idx].first.first - val2);
        }

        printed[leftmostindex[val1]] = add;
        idx = next;
    }

    ll val1 = elements[idx].first.first;

    printed[leftmostindex[val1]] = val1 * n;

    pa(printed);
}

