using namespace std;

struct tree
{
    int x, y;
    int size;
    long long sum = 0;
    tree *l, *r;

    tree(int _x) {
        x = _x;
        y = rand();
        l = r = 0;
        size = 1;
        sum = x;
    }
};

typedef tree *ptree;

inline int si(ptree r)
{
    return r ? r->size : 0;
}

inline long long sum(ptree r) {
    return r ? r->sum : 0ll;
}

inline void update(ptree r)
{
    if (!r) {
        return;
    }
    r->size = si(r->l) + si(r->r) + 1;
    r->sum = sum(r->l) + sum(r->r) + r->x;
}

ptree merge(ptree l, ptree r)
{
    if (!l) {
        return r;
    }
    if (!r) {
        return l;
    }
    if (l->y > r->y) {
        l->r = merge(l->r, r);
        update(l);
        return l;
    } else {
        r->l = merge(l, r->l);
        update(r);
        return r;
    }
}

void split(ptree root, ptree &l, ptree &r, int key)
{
    if (!root) {
        return (void)(l = r = 0);
    }

    if (root->x > key) {
        split(root->l, l, root->l, key);
        r = root;
    } else {
        split(root->r, root->r, r, key);
        l = root;
    }
    update(l);
    update(r);
}

inline void add_to_tree(ptree &root, int x)
{
    ptree l, r;
    split(root, l, r, x);
    root = merge(l, merge(new tree(x), r));
}


