void add1(int x,int w){
	for (;x;x-=x&-x) f[x]+=w;
}

int query1(int x){
	int s=0;
	for (;x<=n;x+=x&-x) s+=f[x];
	return s;
}

void update(int k){
	t[k].s=t[k<<1].s+t[k<<1|1].s;
}

void build(int k,int l,int r){
	t[k].l=l; t[k].r=r;
	t[k].tag=0; t[k].s=0;
	if (l==r) return;
	int mid=(l+r)>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
}

void cov(int k){
	t[k].tag=1;
	t[k].s=0;
}

void pushdown(int k){
	if (t[k].tag){
		cov(k<<1);
		cov(k<<1|1);
		t[k].tag=0;
	}
}

ll query(int k,int L,int R){
	if (L<=t[k].l&&t[k].r<=R) return t[k].s;
	pushdown(k);
	int mid=(t[k].l+t[k].r)>>1;
	if (R<=mid) return query(k<<1,L,R);
	else if (L>mid) return query(k<<1|1,L,R);
	else return query(k<<1,L,R)+query(k<<1|1,L,R);
}

void modifyc(int k,int L,int R){
	if (L<=t[k].l&&t[k].r<=R){
		cov(k);
		return; 
	}
	pushdown(k);
	int mid=(t[k].l+t[k].r)>>1;
	if (L<=mid) modifyc(k<<1,L,R);
	if (R>mid) modifyc(k<<1|1,L,R);
	update(k);
}

void modifyp(int k,int p,ll w){
	if (t[k].l==t[k].r){
		t[k].s=w;
		return;
	}
	pushdown(k);
	int mid=(t[k].l+t[k].r)>>1;
	if (p<=mid) modifyp(k<<1,p,w);
	else modifyp(k<<1|1,p,w);
	update(k);
}

void dfs(int k,int l,int r){
	if (l==r){
		printf("%lld\n",t[k].s);
		return;
	}
	pushdown(k);
	int mid=(l+r)>>1;
	dfs(k<<1,l,mid);
	dfs(k<<1|1,mid+1,r);
}

