struct segment_tree_t {
  vector<node_t> data;
  int sz = INF;
  int root = 0;

  segment_tree_t() {
    data.emplace_back(-1, -1, 0);
  }

  void inc(int pos) {
    inc(root, 0, sz, pos);
  }

  void inc(int v, int l, int r, int pos) {
    if (l == r) {
      ++data[v].val;
      return;
    }

    if (data[v].l == -1) {
      data[v].l = data.size();
      data.emplace_back(-1, -1, 0);
