template<typename T>
class BIT {
public:
	int N;
	vector<T> seg;
	BIT(int N) : N(N) {
		seg.resize(N + 1);
		for (int i = 0; i < N + 1; ++i) seg[i] = 0;
	}

	//i番目にxを加算
	void add(int i, T x) {
		++i;
		while (i <= N) {
			seg[i] += x;
			i += i & (-i);
		}
	}

	//[0,i)の和
	T cumulative(int i) {
		T s = 0;
		while (i > 0) {
			s += seg[i];
			i -= i & (-i);
		}
		return s;
	}

	//[a,b)の和
	T sum(int a, int b) {
		return cumulative(b) - cumulative(a);
	}

	//i番目の要素
	T elem(int i) {
		return sum(i, i + 1);
	}

	//i番目に代入
	void assign(int i, T x) {
		add(i, -elem(i));
		add(i, x);
	}
};


int main() {
	int N; cin >> N;
	vector<ll> A(N); REP(i, 0, N) cin >> A[i];
	vector<pair<ll, int>> P(N); REP(i, 0, N) P[i] = { A[i], i };
	sort(P.begin(), P.end(), [&](pair<ll,int> a, pair<ll,int> b) {
		if (a.first == b.first) {
			return a.second < b.second;
		}
		else return a.first < b.first; });
	vector<int>I(N); REP(i, 0, N) I[P[i].second] = i;
	BIT<ll> tree{ N };
	BIT<ll> tree_sum{ N };
	vector<ll> T(N);
	for (int i = N - 1; i >= 0; --i) {
		int rank = I[i];
		ll high_rank_n = tree.sum(rank, N);
		ll sum = tree_sum.sum(rank, N);
		T[i] = sum - A[i] * high_rank_n;
		tree.add(rank, 1);
		tree_sum.add(rank, A[i]);
	}
	ll sum = 0;
	REP(i, 0, N) sum += A[i];
	ll curmax = 0;
	REP(i, 0, N) {
		if (A[i] > curmax) {
			ll ans = sum - T[i];
			sum = T[i];
			PRI(ans);
			curmax = A[i];
		}
		else PRI(0);
	}
	return 0;
}

