int N;
long long int num[100000];
bool flag[100000];
long long int ma;
int m_num[100000];
long long int box[100000];
long long int ans[100000];
long long int sum[100001];
int bag;

int Check(int l, int r, long long int x[], long long int m) {
	int mid = (l + r) / 2;
	if (r - l < 2) {
		if (x[l] > m)return l - 1;
		if (x[r] > m)return r - 1;
		return r;
	}
	if (x[mid] > m)return Check(l, mid, x, m);
	else return Check(mid, r, x, m);
}

int main() {
	cin >> N;
	cin >> num[0];
	ma = num[0];
	m_num[0] = 1;
	flag[0] = true;
	box[bag++] = num[0];
	for (int i = 1; i < N; i++) {
		cin >> num[i];
		m_num[i] = m_num[i - 1];
		if (num[i] > ma) {
			flag[i] = true;
			ma = num[i];
			box[bag++] = num[i];
			m_num[i]++;
		}
	}
	for (int i = N - 1; i > 0; i--) {
		if (num[i] >= num[0]) {
			sum[0]++;
			sum[Check(0, m_num[i] - 1, box, num[i]) + 1]--;
		}
	}
	for (int i = 1; i < m_num[N - 1]; i++) {
		sum[i] += sum[i - 1];
	}
	//cout << num[0] + sum[0] << endl;
	bag = 1;
	for (int i = 1; i < N; i++) {
		if (!flag[i])ans[i] = 0;
		else {
			ans[i] = (box[bag] - box[bag - 1]) *sum[bag];
			bag++;
			//cout << box[bag] - box[bag-1] + sum[bag++]-1 << endl;
		}
	}
	for (int i = 0; i < N; i++) {
		ans[0] += num[i];
		if (i)ans[0] -= ans[i];
	}
	for (int i = 0; i < N; i++) {
		cout << ans[i] << endl;
	}
	return 0;
}

