int main()
{
    int n;
    scanf(" %d", &n);
    vector<int> a(n);
    rep(i,n) scanf(" %d", &a[i]);

    map<int,int> count, most_left;
    for(int i=n-1; i>=0; --i)
    {
        ++count[a[i]];
        most_left[a[i]]=i;
    }

    vector<int> k,ct,ml;
    for(const auto &x:count)
    {
        int key = x.fi;
        k.pb(key);
        ct.pb(count[key]);
        ml.pb(most_left[key]);
    }

    int S = k.size();
    // rep(i,S) printf(" %d: count = %d, most_left = %d\n", k[i],ct[i],ml[i]);

    vector<ll> ans(n);

    for(int i=S-1; i>0; --i)
    {
        if(ml[i]==0) break;

        ll diff = k[i]-k[i-1];
        ans[ml[i]] += diff*ct[i];
        ct[i-1] += ct[i];
        ct[i]=0;
    }

    rep(i,S) ans[0]+=(ll)k[i]*ct[i];

    rep(i,n) printf("%lld\n", ans[i]);
    return 0;
}

