    vector<pair<pll, ll>> elements;
    map<ll, ll> freq, leftmostindex;

    for (auto x : a) {
        freq[x]++;
        leftmostindex[x] = n + 1;
    }

    for (ll i = 0; i < n; i++) {
        amin(leftmostindex[a[i]], i);
    }

    for (auto x : freq) {
        elements.push_back({x, leftmostindex[x.first]});
    }

    sort(all(elements));

    ll sum = 0, idx = sz(elements) - 1;
    v printed(n, 0);

    while (true) {
        ll next = idx - 1;
        sum += elements[idx].first.second;
        while (next >= 0 && elements[next].second > elements[idx].second) {
            sum += elements[next].first.second;
            next--;
