        ll val1 = elements[idx].first.first;
        ll diff = val1 - elements[next].first.first;

        printed[leftmostindex[val1]] = sum * diff;
        idx = next;
    }

    ll val1 = elements[idx].first.first;

    printed[leftmostindex[val1]] = val1 * n;

    pa(printed);
}

