void solve(std::istream &in, std::ostream &out) {
  int n;
  in >> n;
  vector<pair<int, int>> a(n);
  for (int i = 0; i < n; ++i) {
    in >> a[i].first;
    a[i].second = i;
  }
  vector<int64_t> cnt(n, 0);

  sort(a.rbegin(), a.rend());
  int index = n;
  for (int i = 0; i < n; ++i) {
    int j = i;
    while (j + 1 < n && a[i].first == a[j + 1].first) ++j;
    index = min(index, a[j].second);
    int nextval = j == n - 1 ? 0 : a[j + 1].first;
    int cc = j + 1;
    cnt[index] += (int64_t) cc * (a[j].first - nextval);
    i = j;
  }

  for (int64_t i : cnt) out << i << '\n';
}

