int fd(const vector<int>& vec, int a) {
	return lower_bound(all(vec), a) - vec.begin();
}

void solve() {
	cin >> N;
	vector<int> vec;
	rep(i, 0, N) {
		cin >> A[i];
		vec.push_back(A[i]);
	}
	vec.push_back(0);
	sort(all(vec));
	vec.erase(unique(all(vec)), vec.end());
	rep(i, 0, (int)vec.size()) {
		G[i].fst = inf;
	}
	rep(i, 0, N) {
		int n = fd(vec, A[i]);
		G[n].sec++;
		MIN(G[n].fst, i); 
	}
	ll sum = 0; int n = inf;
	for(int i = (int)vec.size() - 1; i > 0; i--) {
		sum += G[i].sec;
		MIN(n, G[i].fst);
		ans[n] += sum * (vec[i] - vec[i - 1]);
	}
	rep(i, 0, N) {
		cout << ans[i] << "\n";
	}
}

