template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }

template <typename T=int>
struct BIT {
    const int n;
    vector<T> v;

    BIT(int n): n(n), v(n+1,0) {}

    void add(int i, int x) {
        i += 1;
        while (i <= n) {
            v[i] += x;
            i += i & -i;
        }
    }
    T sum(int i) {
        i += 1;
        T ret = 0;
        while (i > 0) {
            ret += v[i];
            i -= i & -i;
        }
        return ret;
    }
    T sum(int l, int r) {
        return sum(r) - sum(l-1);
    }
};

void solve() {
    int n;
    cin >> n;
    VI a(n);
    REP(i,0,n) cin >> a[i];

    LL sum = 0;
    REP(i,0,n) sum += a[i];

    VLL ans(n);
    VI mv(n);
    REP(i,1,n) mv[i] = max(a[i-1], mv[i-1]);

    VI cnt(n);
    BIT<> bit(n);
    VP ps(n);
    REP(i,0,n) {
        ps[i] = MP(i,a[i]);
    }
    sort(all(ps), [](auto &l, auto &r) {
        if (l.second == r.second) return l.first > r.first;
        return l.second > r.second;
    });
    for (auto &p: ps) {
        int idx = p.first;
        bit.add(idx,1);
        cnt[idx] = bit.sum(idx, n-1);
    }

    // REP(i,0,n) cerr << i << ": " << mv[i] << ", " << cnt[i] << endl;

    RREP(i,0,n) {
        if (a[i] <= mv[i]) continue;
        ans[i] = 1LL * (a[i] - mv[i]) * cnt[i];
    }

    REP(i,0,n) {
        if (a[i] == 0) continue;
        REP(j,i+1,n) sum -= ans[j];
        ans[i] = sum;
        break;
    }

    REP(i,0,n) cout << ans[i] << endl;
}

signed main() {
    solve();

    return 0;
}

