  int n;
  cin >> n;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }

  int heightest = 0;
  for (int i = 0; i < n; i++) {
    if (a[i] > a[heightest]) {
      heightest = i;
    }
  }
  vector<int> stack;
  for (int i = heightest; i >= 0; i--) {
    while (stack.size() && a[stack.back()] <= a[i]) stack.pop_back();
    stack.push_back(i);
  }

  map<int,long long> cnt;
  for (auto i : a) cnt[i]++;
  vector<long long> ans(n);

  for (int i = 1; i < (int) stack.size(); i++) {
    int high = a[stack[i - 1]];
    int low = a[stack[i]];
    ans[stack[i - 1]] = cnt[high] * (high - low);
    cnt[low] += cnt[high];
    cnt[high] = 0;
  }
  ans[0] += cnt[a[0]];

  for (auto i : ans) {
    cout << i << '\n';
  }
  return 0;
}

#include <bits/stdc++.h>

typedef long long LL;

