#define INF_LL_YJ 1145141919810364364

using namespace std;

#define MAX_N 100005

int N;
LL A[MAX_N];

void input()
{
  cin >> N;
  for (int i = 0; i < N; i++) {
    cin >> A[i];
  }
}

map<LL, LL> mapS;
map<LL, int> indexS;
priority_queue<LL> kindS;
set<LL> SetS;

LL ans[MAX_N];
void solve()
{
  for (int i = 0; i < N; i++) {
    mapS[A[i]]++;
    if(indexS.find(A[i]) == indexS.end()){
      indexS[A[i]] = i;
    }
    if(SetS.insert(A[i]).second){
      kindS.push(A[i]);
    }
  }
  kindS.push(0);

  LL nextKind = kindS.top();
  kindS.pop();

  int index = indexS[nextKind];
  LL m = mapS[nextKind];

  while(kindS.size()){

    int k = kindS.top();
    int nextIndex = indexS[k];
    kindS.pop();

    ans[index] += m*(nextKind - k);

    if(k == 0){
      break;
    }

    index = min(index, nextIndex);
    m += mapS[k];
    nextKind = k;
  }

  for (int i = 0; i < N; i++) {
    cout << ans[i] << endl;
  }
}

int main()
{
  input();

  solve();

  return 0;
}

