struct Data {
  int pos,v;
  bool operator < ( const Data &data ) const {
    if( v != data.v ) return v < data.v;
    return pos > data.pos;
  }
};

int getPos(priority_queue<Data> &Q) {
  while( !Q.empty() ) {
    Data d = Q.top(); 
    if( a[d.pos] != d.v ) {
      Q.pop();
      continue;
    } else if( a[d.pos] == 0 ) {
      Q.pop();
      continue;
    } else break;
  }
  return Q.top().pos;
}


int getNextPos(priority_queue<Data> &Q) {
  while( !Q.empty() ) {
    Data d = Q.top(); 
    if( a[d.pos] != d.v ) {
      Q.pop();
      continue;
    } else if( a[d.pos] == 0 ) {
      Q.pop();
      continue;
    } else break;
  }
  Data tmp = Q.top(); Q.pop();
  while( !Q.empty() ) {
    Data d = Q.top(); 
    if( a[d.pos] != d.v ) {
      Q.pop();
      continue;
    } else if( a[d.pos] == 0 ) {
      Q.pop();
      continue;
    } else break;
  }
  int next = -1;
  if( !Q.empty() ) next = Q.top().pos;

  Q.push(tmp);
  return next;
}

