    rep(i,n) {
      if( a[i] == 0 ) continue;
      if( i == maxi_p ) continue;
      if( bb == -1 ) bb = i;
      else if( a[bb] < a[i] ) bb = i;
    }
    */
    next_p = getNextPos(Q);

    if( next_p == -1 ) {
	h[maxi_p] += (ll)a[maxi_p];
	a[maxi_p] = 0;
	Q.push((Data){maxi_p,0});
	sum = 0;
    } else {
      if( next_p < maxi_p ) {
	ll diff = a[maxi_p] - a[next_p];
	if(diff) {
	  h[maxi_p] += diff;
	  a[maxi_p] -= diff;
	  sum -= diff;
	  Q.push((Data){maxi_p,a[maxi_p]});
	}
      } else {
	int prev_p = -1;
	rep(i,maxi_p) {
	  if( a[i] == 0 ) continue;
	  if( a[prev_p] < a[i] ) prev_p = i;
	}
	if( prev_p == -1 ) {
	  REP(i,maxi_p+1,n) {
	    if( a[i] == 0 ) continue;
	    h[maxi_p] += a[i];
	    sum -= a[i];
	    a[i] = 0;
	    Q.push((Data){i,a[i]});
	  }
	} else {
	  REP(i,maxi_p+1,n) {
