	      sum -= ( llabs(a[i]-a[prev_p]) );
	      a[i] -= ( llabs(a[i]-a[prev_p]) );
	      assert( a[i] >= 0LL );
	      Q.push((Data){i,a[i]});
	    }
	  }
	}
      }
    }
  }
}

