using I = long long;

int main() {
  int N;
  cin >> N;
  vector<int> A(N);
  for(auto& i: A) cin >> i, --i;

  map<int, int, greater<int>> left;
  for(auto i=0; i<N; ++i) if(!left.count(A[i])) left[A[i]] = i;

  map<int, I, greater<int>> cnt;
  for(auto i: A) ++cnt[i];

  vector<I> ans(N);
  deque<int> q;
  for(auto i: left) if(q.empty() || i.second < q.back()) q.emplace_back(i.second);
  auto pa = -1;
  for(auto i: cnt) {
    auto a = i.first;
    auto c = i.second;
    if(a == A[q.front()]) {
      q.pop_front();
      if(q.empty()) {
        ans[a] += c;
      } else {
        auto d = a - A[q.front()];
        ans[left[a]] += c * d;
        cnt[A[q.front()]] += c;
      }
      pa = a;
    } else {
      auto d = a - A[q.front()];
      ans[left[pa]] += c * d;
      cnt[A[q.front()]] += c;
    }
  }
  for(auto i: ans) cout << i << endl;
}

