void solve() {
  int n;
  cin >> n;
  vi32 a(n);
  cin >> a;
  vi32 indices(n);
  iota(all(indices), 0);
  vi32 ord(n);
  iota(all(ord), 0);
  sort(all(ord), [&](int i, int j) {
    if (a[i] != a[j]) return a[i] < a[j];
    return indices[i] < indices[j];
  });
  pqdesc<pair<int, int>> q;
  rep(i, n) {
    q.emplace(a[i], i);
  }
  vi64 ans(n);
  int cnt = 0;
  int ma = q.top().first;
  do {
    int idx;
    while (sz(q) && q.top().first == ma) {
      cnt += 1;
      idx = q.top().second;
      q.pop();
    }
    int next = 0;
    if (sz(q)) {
      next = q.top().first;
    }
    ans[idx] += (ma - next) * cnt;
    if (sz(q)) {
      ma = q.top().first;
    }
  } while (sz(q));
  rep(i, n) {
    cout << ans[i] << endl;
  }
}

