        if (bi[j - 1] < ai[shed[i - 1]])
        {
            if (i >= 2) ans[shed[i - 1]] += 1ll * (n - j + 1) * (ai[shed[i - 1]] - ai[shed[i - 2]]);
            i --;
        }
    }
    for (int i = 1; i <= n; ++ i) cout << ans[i] << "\n";
}

