  for(auto& i: A) cin >> i;

  map<I, P> m;
  for(auto i=N-1; 0<=i; --i) ++m[A[i]].first, m[A[i]].second = i;
  priority_queue<Node> q;
  for(auto i: m) q.emplace(i.first, i.second.first, i.second.second);

  vector<I> ans(N);
  while(!q.empty()) {
    if(q.size() == 1) {
      I a, n, x;
      tie(a, n, x) = q.top(); q.pop();
      ans[x] += a * n;
    } else {
      I a1, n1, x1;
      I a2, n2, x2;
      tie(a1, n1, x1) = q.top(); q.pop();
      tie(a2, n2, x2) = q.top(); q.pop();
      ans[x1] += (a1 - a2) * n1;
      q.emplace(a2, n1 + n2, min(x1, x2));
    }
  }
  for(auto i: ans) cout << i << endl;
}

