bool comp(PII a, PII b){
  if(a.snd > b.snd){
    return true;
  } else if(a.snd < b.snd){
    return false;
  } else if(a.fst > b.fst){
    return true;
  }
  return false;
}

int main(){
  int N;
  cin >> N;
  vector<PII> a(N);
  VI ans = VI(N+1, 0);
  REP(i, 0, N){
    int tmp;
    cin >> tmp;
    a[i] = {i, tmp};
  }

  sort(a.begin(), a.end(), comp);

  int step = 1;
  PII cur = a[0];

  while(step < N){
    PII next = a[step];
    int diff = cur.snd - next.snd;
    ans[cur.fst] += diff * step;
    cur.snd -= diff;
    if(cur.fst > a[step].fst){
      cur = a[step];
    }
    step++;
  }
  ans[cur.fst] += step * cur.snd;

  REP(i, 0, N){
    cout << ans[i] << endl;
  }

  return 0;
}

