	for (int i=0; i<mx; i++) b[i]=0;
	for (int i=0; i<n; i++) b[a[i]-1]++;
	int c[mx];
	for (int i=0; i<mx; i++) c[i]=-1;
	for (int i=0; i<n; i++){
		if (c[a[i]-1]==-1) c[a[i]-1] = i+1;
	}
	for (int i=mx-2; i>=0; i--) if (c[i]==-1) c[i]=c[i+1];
