int main(){
	int n;
	cin>>n;
	vector<long long int> a(n);
	for(int i=0;i<n;i++) cin>>a[i];
	vector<int> seq;
	priority_queue<long long int> mount;
	for(int i=0;i<n;i++){
		if(i==0){
			seq.push_back(0);
		}
		else if(seq[seq.size()-1]<a[i]){
			seq.push_back(i);
		}
		mount.push(a[i]);
	}
	vector<long long int> res(n,0LL);
	int flatted=0;
	for(int i=seq.size()-1;i>0;i--){

		if(flatted!=0){
			res[seq[i]]+=(a[seq[i]]-a[seq[i-1]])*flatted;
		}
		while(true){
			long long int val=mount.top();
			if(val<=a[seq[i-1]]){
				break;
			}
			mount.pop();
			res[seq[i]]+=(val-a[seq[i-1]]);
			flatted++;
		}
		if(i==1) break;
		while(true){
			int val=mount.top();
			if(val==a[seq[i-1]]){
				flatted++;
				mount.pop();
			}
			else{
				break;
			}
		}
	}
	res[0]=accumulate(a.begin(),a.end(),0LL)-accumulate(res.begin(),res.end(),0LL);
	for(int i=0;i<n;i++)cout<<res[i]<<endl;
	return 0;

}

