        else diff = op.first;
        //diff*(これまで取り出したものの数)だけans[op.second]に加算
        //op.secondではない
        ans[idx] += diff*(N-pq.size());
    }
    for(int i = 1; i <= N; i++){
        cout << ans[i] << endl;
    }
    return 0;
}

