signed main(int argc, char *argv[]) {
  int n = in();

  vector<bool> use(n, false);
  int max_a = -1;
  map<int, pair<int, int64_t>, greater<int>> m;
  m[0] = mp(-1, 0);

  for (int i = 0; i < n; ++i) {
    int a = in();
    use[i] = chmax(max_a, a);

    if (m.count(a)) {
      m[a].sc++;
    } else {
      m[a] = mp(i, 1);
    }
  }

  vector<int64_t> ans(n + 1, 0);
  int64_t cnt = 0;
  int idx = n;
  for (auto itr = m.begin();; ++itr) {
    auto nitr = itr;
    ++nitr;
    if (nitr == m.end()) break;

    if (use[itr->sc.fs]) {
      ans[idx] = cnt;
      idx = itr->sc.fs;
      cnt = 0;
    }

    cnt += 1ll * (itr->fs - nitr->fs) * itr->sc.sc;
    nitr->sc.sc += itr->sc.sc;
  }

  ans[0] = cnt;

  for (int i = 0; i < n; ++i) cout << ans[i] << endl;
}

