class FenwickTree {
public:
    FenwickTree(int n):
        tree(n + 1, 0) {}

    void update(int pos, T value) {
        for (++pos; pos < SZ(tree); pos += pos & -pos) {
            tree[pos] += value;
        }
    }
    T query(int pos) {
        T ret = 0;
        for (++pos; pos > 0; pos -= pos & -pos) {
            ret += tree[pos];
        }
        return ret;
    }
    T query(int left, int right) {
        return query(right) - query(left - 1);
    }
private:
    vector<T> tree;
};

