	map<ll, priority_queue<ll, vector<ll>, greater<ll>>> mpq;
	ll total = 0;
	rep( i, n )
	{
		cin >> a[i];
		pq.push( a[i] );
		mpq[a[i]].push( i );
		total += a[i];
	}

	ll x = pq.top();
	ll idx = mpq[x].top();
	map<ll, ll> mcnt;
	rep( i, n ) mcnt[a[i]]++;
	vector<ll> ans( n );
	while ( pq.empty() == false )
	{
		pq.pop();
		ll y;
