			break;
		}

//		cout << x << " : " << mcnt[x] << ", " << y << " : " << mcnt[y] << endl;

		if ( x != y )
		{
			ans[idx] += ( x - y ) * mcnt[x];
			mcnt[y] += mcnt[x];
			mpq[y].push( idx );
			if ( y != 0 )
				idx = mpq[y].top();
		}
