		{
			ans[idx] += mcnt[x];
			mcnt[mpq[pq.top()].top()] += mcnt[x];
			idx = mpq[pq.top()].top();
		}
		mcnt[x] = 0;
		x = y;
	}

	rep( i, n ) cout << ans[i] << endl;

	return ( 0 );
