long long int getv(long long int *idx, int a, int b)
{
    a += MAXN; b += MAXN;
    long long ans = 0;
    while(a<=b)
    {
        if(a%2==1) ans += idx[a++];
        if(b%2==0) ans += idx[b--];
        a /= 2; b /= 2;
    }
    return ans;
}
void setv(long long int *idx, int a, int v)
{
    a += MAXN; idx[a] = v;
    while(a = a/2)
    {
        idx[a] = idx[2*a] + idx[2*a+1];
    }
}
