int n;
int x[MAXN];
pair<int,int> o[MAXN];
ll ret[MAXN];

void run() {
	scanf("%d",&n); REP(i,n) scanf("%d",&x[i]);
	REP(i,n) o[i]=MP(-x[i],i); sort(o,o+n);
	REP(i,n) ret[i]=0;

	int at=o[0].second,h=x[at],cnt=1;
	FOR(i,1,n) {
		int to=o[i].second,nh=x[to];
		ret[at]+=(ll)cnt*(h-nh);
		h=nh; if(to<at) at=to; ++cnt;
	}
	ret[at]+=(ll)cnt*h;
	REP(i,n) printf("%lld\n",ret[i]);
}

int main() {
	run();
	return 0;
}

