void solve(){
	//key:値		最小index,要素数
	map< int, vector<LL> > numMap;
	int N;
	cin >> N;
	vector<LL> temp(2);
	for(int i=0;i<N;++i){
		int a;
		cin >> a;
		if( numMap.find( a ) != numMap.end() ){
			//indexがあるなら、それはより小さいi
			temp = numMap[ a ];
			temp[1]++;
			numMap[a] = temp;

		}else{
			temp[0] = i;
			temp[1] = 1;
			numMap[ a ] = temp;
		}
	}
	map<int,vector<LL> >::iterator itr,begin,next;
	itr = numMap.end();
	--itr;
	begin = numMap.begin();
	vector<LL> ans(N,0);
	while(1){
		if( itr == begin ){
			//LL Aval = 0;
			LL Bval = itr->first;
			int index = (itr->second)[0];
			LL num = (itr->second)[1];
			ans[ index ] += Bval*num;
			break;
		}
		next = itr;
		next--;
		LL Aval = next->first;
		LL Bval = itr->first;
		int index = (itr->second)[0];
		LL num = (itr->second)[1];

		//indexが呼び出される回数。
		ans[index] += (Bval-Aval)*num;

		(next->second)[0] = min((next->second)[0],(LL)index);
		(next->second)[1] += num;

		--itr;
	}

	for(int i=0;i<N;++i){
		cout << ans[i] << endl;
	}
}

