  ll maxi = a[0];
  ll sum = a[0];
  FOR(i, 1, n){
    if(maxi < a[i]){
      ma[i] = true;
      maxi = a[i];
    }else{
      ma[i] = false;
    }
    sum += a[i];
  }
  SegmentTree<ll, ll> segtree = SegmentTree<ll, ll>(n, [](ll a, ll b){return a + b;},
      [](ll a,ll b){return b;}, 0, vector<ll>());
  SegmentTreeI seg = SegmentTreeI(n, [](int a, int b){return a + b;},
      [](int a,int b){return b;}, 0, vector<int>());
  vector<ll> b = a;
  sort(all(b));
