                if(maxa < a[i]) {
                        maxa = a[i];
                        rank[m] = i;
                        m++;
                }
        }
        LSTEP(i,0,m) {
                long int first = rank[m-1-i];
                if (i != m-1) {
                        long int second = rank[m-2-i];
                        LSTEP(j,first,n) {
                                if (a[j] > a[second]) {
                                        count[first] += a[j] - a[second];
                                        a[j] = a[second];
                                }
                        }
                } else {
                        LSTEP(j,first,n) {
                                count[first] += a[j];
                        }
                }
        }
        LSTEP(i,0,n) {
                std::cout << count[i] << std::endl;
        }
