	ll max_ = 0;
	for (int i = 0; i < n; i++) {
		if (m.find(a[i]) == m.end()) {
			if(max_ < a[i])min_index.push_back(make_pair(a[i], i));
			else min_index.push_back(make_pair(a[i], -1));
			max_ = max(max_,a[i]);
			m[a[i]]=1;
		}else{
			m[a[i]]++;
		}
	}
	sort(min_index.begin(), min_index.end(), greater<pair<ll, int>>());
	vector<pair<ll,ll>>sum;
	for (auto it = --m.end();; it--) {
		sum.push_back(make_pair(it->first,it->second));
		if (it == m.begin())break;
	}

	for (int i = 1; i < sum.size(); i++) {
		sum[i].second += sum[i - 1].second;
	}

	min_index.push_back(make_pair(0,-1));
	sum.push_back(make_pair(0, 0));
