void read_input()
{
    cin >> n;
    for(int i = 1; i <= n; ++i)
    {
        cin >> piles[i].first;
        piles[i].second = i;
    }
    sort(piles + 1, piles + n + 1, [](const pii&p, const pii&q)
         {
             return p.first > q.first;
         });
