void solve(long long N, vector<long long> a){
	long long ans[100001] = {0};

  vector<int> memov;
  vector<long long> ad = a;
  sort(ad.begin(), ad.end());
  reverse(ad.begin(), ad.end());
  for (int i = 0; i < N; i++) {
    if (i == 0) {
      memov.push_back(ad[i]);
    } else {
      if (ad[i] == ad[i-1]) { continue; }
      memov.push_back(ad[i]);
    }
  }

  int p = 0;
  int g = 0;
  for (int i = N - 1; i >= 0; i--) {
    vector<long long>::iterator it = find(a.begin(), a.end(), memov[p]);
    size_t maxIndex = distance(a.begin(), it);
    while (i >= 0 && i > maxIndex) {
      ans[i] = 0;
      i--;
    }
    vector<long long>::iterator ab = a.begin();
    while (true) {
      ab = find(ab, a.end(), memov[p]);
      if (ab != a.end()) {
        g++;
        ab += 1;
      } else { break; }
    }
    ans[i] = (memov[p] - memov[p+1]) * g;
    p++;
  }

  for (int i = 0; i < N; i++) {
    cout << ans[i] << endl;
  }
}

