// accessible for range [0, n)
template <typename T> struct BinaryIndexedTree0 {
  const int N;
  vector<T> val;

  BinaryIndexedTree0(int N) : N(N), val(N) {}

  // sum of [0, i)
  // v[0] + v[1] + ... + v[i-1]
  T sum(int i) const {
    T s = 0;
    --i;
    if (i >= N) i = N - 1;
    for (; i >= 0; i = (i & (i + 1)) - 1) s += val[i];
    return s;
  }

  // sum of [l, r)
  // v[l] + v[l+1] + ... + v[r-1]
  T sum(int l, int r) const {
    return sum(r) - sum(l);
  }

  // v[i] += x
  void add(int i, T x) {
    for (; i < N; i |= i + 1) val[i] += x;
  }

  // v[i] = x
  void set(int i, T x) {
    T c = sum(i, i + 1);
    add(i, x - c);
  }
};

void Main() {
