using namespace std;

const int maxn = 1e5 + 10;

int N;

int a[maxn];
long long tree[maxn];
int cnt[maxn];
pair<int, int> p[maxn];
long long ans[maxn];
long long q[maxn];

void add(int x, long long val)
{
	while (x <= N)
	{
		tree[x] += val;
		++cnt[x];
		x += x & -x;
	}
}

long long query(int x, int &c)
{
	c = 0;
	long long ret = 0;
	while (x > 0)
	{
		ret += tree[x];
		c += cnt[x];
		x -= x & -x;
	}
	return ret;
}

int main()
{
	scanf("%d", &N);
	for (int i = 0; i < N; ++i)
		scanf("%d", &a[i]);
	long long sum = 0;
	for (int i = 0; i < N; ++i)
		p[i] = make_pair(a[i], i), sum += a[i];
	sort(p, p + N);
	for (int i = N - 1; i >= 0; --i)
	{
		int x = N - p[i].second;
		int c;
		ans[p[i].second] = query(x, c);
		ans[p[i].second] -= 1ll * c * p[i].first;
		add(x, p[i].first);
	}
	q[0] = sum - ans[0];
	for (int i = 1, j = 0; i < N; ++i)
	{
		if (a[i] > a[j])
			q[i] = ans[j] - ans[i], j = i;
		else
			q[i] = 0;
	}
	for (int i = 0; i < N; ++i)
		printf("%lld\n", q[i]);
	return 0;
}

