}

int N;
int a[1000000];

int zaatu_num;
int zaatu_table[1000000];

int get_id(int num) {
	int left, right, mid;
	left = 0; right = zaatu_num;
	while (left <= right) {
		mid = (left + right) / 2;
		if (zaatu_table[mid] == num) {
			return mid;
		} else if (zaatu_table[mid] < num) {
			left = mid + 1;
		} else {
			right = mid - 1;
		}
	}
	printf("%d not found!\n", num);
	exit(1);
}

int isi_count[1000000];

int main(void) {
	int i;
	int prev_count = 0;
	if (scanf("%d", &N) != 1) return 1;
	for (i = 0; i < N; i++) {
		if (scanf("%d", &a[i]) != 1) return 1;
		zaatu_table[i] = a[i];
	}
	/* 座標圧縮 */
	qsort(zaatu_table, N, sizeof(int), cmp);
	zaatu_num = 0;
	for (i = 1; i < N; i++) {
		if (zaatu_table[i] != zaatu_table[zaatu_num]) {
			zaatu_table[++zaatu_num] = zaatu_table[i];
		}
	}
	/* 各種類が何個あるかを調べる */
	for (i = 0; i < N; i++) {
		isi_count[get_id(a[i])]++;
	}
	/* その数以上のところをその数に含める */
	for (i = N - 1; i > 0; i--) {
		isi_count[i - 1] += isi_count[i];
	}
	/* 計算する */
	for (i = 0; i < N; i++) {
		if (prev_count < a[i]) {
			/* この階層を全部削るまで出せる */
			printf("%"PRIu64"\n", (uint64_t)(a[i] - prev_count) * isi_count[get_id(a[i])]);
			prev_count = a[i];
		} else {
			puts("0");
		}
	}
	return 0;
}

