typedef struct indexode{
  int a;
  int index;
} node;

int cmp(const void *a,const void *b){
  node *p=(node *)a;
  node *q=(node *)b;
  if(p->a!=q->a) return p->a-q->a;
  return p->index-q->index;
}

void run(void){
  int n;
  scanf("%d",&n);
  node *a=(node *)malloc(sizeof(node)*n);
  int i;
  for(i=0;i<n;i++){
    int b;
    scanf("%d",&b);
