  int64 *ans=(int64 *)calloc(n,sizeof(int64));
  int before=0;
  i=0;
  while(i<n){
    ans[a[i].index-1]+=(int64)(n-i)*(a[i].a-before);
    before=a[i].a;
    int k=i;
    while(k<n && a[k].a==a[i].a) k++;
    i=k;
  }
  for(i=0;i<n;i++){
    printf("%lld\n",ans[i]);
  }
}

