//プラキュー（二分ヒープ）（最低限バージョン）
ll heapN,heap[1<<20];
//int PQhikaku(int i,int j);//jの方が優先度が高いならtrueを返す
int PQhikaku(int i,int j){return heap[i]<heap[j];}
void heap_utod(int n){
	if(2*n>heapN)return;
	int rflag=(2*n+1<=heapN)&&(PQhikaku(2*n,2*n+1));
	if(PQhikaku(n,2*n+rflag)){
		ll temp=heap[2*n+rflag];
		heap[2*n+rflag]=heap[n];
		heap[n]=temp;
		heap_utod(2*n+rflag);
	}
}
void heap_dtou(int n){
	if(n==1||PQhikaku(n,n/2))return;
	ll temp=heap[n];
	heap[n]=heap[n/2];
	heap[n/2]=temp;
	heap_dtou(n/2);
}
ll PQpop(){
	ll rr=heap[1];
	heap[1]=heap[heapN--];
	heap_utod(1);
	return rr;
}
void PQpush(ll n){
	heap[++heapN]=n;
	heap_dtou(heapN);
}

