class BinaryIndexedTree(val n: Int) {
  var bit: IntArray
  init { bit = IntArray(n + 1) { 0 } }
  fun sum(k: Int): Int {
    var s = 0
    var t = k
    while (t > 0) {
      s += bit[t]
      t -= t and -t
    }
    return s;
  }
  fun add(k: Int, x: Int) {
    var t = k
    while (t <= bit.size) {
      bit[t] += x
      t += t and -t
    }
  }
}

fun compress(unzip: List<Int>): Map<Int, Int> {
  var zip = mutableMapOf<Int, Int>();
  for (x in unzip) zip[x] = -1
  var idx = 1
  for (k in zip.keys) {
    zip[k] = idx;
    idx++
  }
  return zip;
}

