        public Pair(int id, long cnt) {
            super();
            this.id = id;
            this.cnt = cnt;
        }

        @Override
        public int compareTo(Pair arg0) {
            if (this.cnt == arg0.cnt) {
                return arg0.id - this.id;
            }
            return this.cnt > arg0.cnt ? 1 : -1;
        }

        void show() {
