        for (int i = 0; i < n; i++) {
            while (!map.isEmpty() && map.lastEntry().getKey() <= a[i]) {
                s += map.lastEntry().getValue() * (map.lastEntry().getKey() - last);
                last = map.lastEntry().getKey();
                map.pollLastEntry();
            }
            out.println(s);
            s = 0;
        }
    }

