import java.io.*;
import java.util.*;

public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		Map<Integer, Integer> tmc = new TreeMap<>();
		Map<Integer, Integer> tml = new TreeMap<>();
		for (int i = 0; i < n; i++) {
			int a = sc.nextInt();

			if (!tmc.containsKey(a)) {
				tmc.put(a, 0);
				tml.put(a, i);
			}
			tmc.put(a, tmc.get(a) + 1);
			if (i < tml.get(a)) {
				tml.put(a, i);
			}
		}

		tmc.put(0, 0);
		tml.put(0, 0);
		List<Integer> as = new ArrayList<>(tmc.keySet());
		long[] ans = new long[n];
		for (int i = as.size() - 1; i > 0; i--) {
			int key = as.get(i);
			int keyc = tmc.get(key);
			int keyl = tml.get(key);
			int nkey = as.get(i - 1);
			int nkeyc = tmc.get(nkey);
			int nkeyl = tml.get(nkey);

			ans[keyl] += (long)(key - nkey) * keyc;

			tmc.put(nkey, nkeyc + keyc);
			if (keyl < nkeyl) {
				tml.put(nkey, keyl);
			}
		}

		for (long e : ans) {
			pr.println(e);
		}
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	private static class Printer extends PrintWriter {
		Printer(PrintStream out) {
			super(out);
		}
	}
}

import java.util.*;

class Main {
	static int N;
	static long[] a;
	static long[][] is;
	static long[] freq;
	static long[] cum;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		a = new long[N];
		is = new long[2][N];
		freq = new long[N + 1];
		cum = new long[N];
		Arrays.fill(is[0], -1);
		Arrays.fill(is[1], -1);
		Arrays.fill(freq, -1);
		for (int i = 0; i < N; ++i) {
			a[i] = sc.nextInt();
		}

		int p = 0;
		for (int i = 0; i < N; ++i) {
			if (i == 0 || is[0][p - 1] < a[i]) {
				is[0][p] = a[i];
				is[1][p] = i + 1;
				++p;
			}
		}
		is[0] = Arrays.copyOf(is[0], p);
		is[1] = Arrays.copyOf(is[1], p);
		Arrays.sort(a);
		for (int i = 0; i < N; ++i) {
			cum[i] = (i > 0 ? cum[i - 1] : 0) + a[i];
		}
		for (int i = p - 1; i >= 1; --i) {
			int t = binarySearch(a, is[0][i]);
			int s = binarySearch(a, is[0][i - 1]);
			freq[(int) is[1][i]] = cum[t - 1] - cum[s] - (t - s - 1) * is[0][i - 1] + (N - t) * (is[0][i] - is[0][i - 1]);
		}
		int t = binarySearch(a, is[0][0]);
		freq[(int) is[1][0]] = (t > 0 ? cum[t - 1] : 0) + (N - t) * is[0][0];

		for (int i = 1; i <= N; ++i) {
			System.out.println(Math.max(freq[i], 0));
		}
	}

	// 同じ数字が続いているときは一番後ろを返す。
	static int binarySearch(long[] a, long key) {
		int s = -1;
		int t = a.length;
		while (t - s > 1) {
			int m = (s + t) / 2;
			if (a[m] > key) {
				t = m;
			} else {
				s = m;
			}
		}
		if (a[s] != key)
			s *= -1;
		return s;
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

