import java.io.*;
import java.util.*;

public class Main {
  private static long[] solve(int n, int[] as) {
    Map<Integer, Integer> aToCount = new HashMap<>();
    Map<Integer, Integer> aToMinIndex = new HashMap<>();
    for (int i = 0; i < n; i++) {
      int a = as[i];
      aToCount.put(a, aToCount.getOrDefault(a, 0) + 1);
      aToMinIndex.putIfAbsent(a, i);
    }
    List<Integer> aSorted = new ArrayList<>();
    aSorted.add(0);
    for (int a : aToCount.keySet()) {
      aSorted.add(a);
    }
    Collections.sort(aSorted);

    long[] answers = new long[n];
    long countTotal = 0;
    int minIndex = Integer.MAX_VALUE;
    for (int i = aSorted.size() - 1; i > 0; i--) {
      int a = aSorted.get(i);
      int index = aToMinIndex.get(a);
      minIndex = Math.min(minIndex, index);
      countTotal += aToCount.get(a);
      int aLower = aSorted.get(i-1);
      answers[minIndex] += (a - aLower) * countTotal;
    }
    return answers;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[] as = reader.nextIntArray(n);
    long[] answers = solve(n, as);
    for (long answer : answers) {
      out.println(answer);
