    void run() {
        int n = sc.nextInt();
        int[] a = sc.nextIntArray(n);
        int[] c = new int[n + 1];

        int[] r = new int[n + 1];

        if (n == 1) {
            System.out.println(a[0]);
            return;
        }

        PriorityQueue<Pair> que = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 0; i < n; i++) {
            que.add(new Pair(i + 1, a[i]));
        }

         //while(!que.isEmpty()) {
         //    que.poll().show();
         //}
        while (true) {
            Pair top = que.poll();
            if (que.isEmpty()) {
                c[top.id] = top.cnt + r[top.id];
                break;
            }

            int equalN = 1;
            while (!que.isEmpty() && que.peek().cnt == top.cnt) {
                que.poll();
                equalN++;
            }

            equalN += r[top.id];
            if(que.isEmpty()) {
                c[top.id] = top.cnt +  equalN - 1;
                break;
            }
            Pair second = que.peek();
            r[second.id] = equalN;
            c[top.id] = (top.cnt  - second.cnt)  * equalN;
        }

        StringBuilder s = new StringBuilder();
        for (int i = 1; i <= n; i++)
            s.append(c[i] + "\n");
        System.out.print(s);
    }

