import java.util.StringTokenizer;

public class Main {

	public static void main(String[] args) throws IOException {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static int modP = 1000000007;

	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();

			List<P> list = new ArrayList<>();
			List<Integer> target = new ArrayList<>();
			for (int i = 0; i < n; i++) {
				long c = in.nextLong();
				list.add(new P(i, c));
			}

			long max = 0;
			for (int i = 0; i < n; i++) {
				if (max < list.get(i).c) {
					max = list.get(i).c;
					target.add(list.get(i).k);
				}
			}

			Collections.sort(list, (x, y) -> (int)x.c - (int)y.c);

			max = 0;
			int idx = 0;
			long sum = 0;
			long[] ans = new long[n];
			for (int i = 0; i < n; i++) {
				long c = list.get(i).c;
				if (max < c && list.get(i).k == target.get(idx)) {
					ans[list.get(i).k] = sum + (c - max)*(long)(n - i);
					max = c;
					idx++;
					sum = 0;
				} else {
					sum += list.get(i).c - max;
				}
			}

			for (long l : ans) {
				System.out.println(l);
			}

		}
	}
	static class P {
		int k; long c;

		public P(int k, long c) {
			this.k = k;
			this.c = c;
		}
	}

	static class InputReader {
		BufferedReader in;
		StringTokenizer tok;

		public String nextString() {
			while (!tok.hasMoreTokens()) {
				try {
					tok = new StringTokenizer(in.readLine(), " ");
				} catch (IOException e) {
					throw new InputMismatchException();
				}
			}
			return tok.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(nextString());
		}

		public long nextLong() {
			return Long.parseLong(nextString());
		}

		public double nextDouble() {
			return Double.parseDouble(nextString());
		}

		public int[] nextIntArray(int n) {
			int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public long[] nextLongArray(int n) {
			long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public InputReader(InputStream inputStream) {
			in = new BufferedReader(new InputStreamReader(inputStream));
			tok = new StringTokenizer("");
		}

	}

}

import java.util.*;
import java.io.*;

import static java.lang.System.in;

public class Main {
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n+1];
        for(int i=1;i<=n;i++) a[i] = sc.nextLong();
        long[] left = new long[n+1];
        for(int i=1;i<=n;i++) left[i] = Math.max(left[i-1],a[i]);
        PriorityQueue<Long> pq = new PriorityQueue<>(10,Collections.reverseOrder());
        long[] ans = new long[n+1];
        long hi = left[n];
        long cnt = 0;
        for(int i=n;i>0;i--){
            if(a[i]<=left[i-1]){
                pq.add(a[i]);
                continue;
            }
            long lo = left[i-1];
            cnt++;
            ans[i] += cnt*(hi-lo);
            while(pq.size()>0&&pq.peek()>lo){
                ans[i] += pq.poll()-lo;
                cnt++;
            }
            hi = lo;
        }
        PrintWriter out = new PrintWriter(System.out);
        for(int i=1;i<=n;i++) out.println(ans[i]);
        out.flush();
    }
}

