			for(int i=0;i<N;i++)countS[i]=0;

			Arrays.sort(a, new MComparator());
			int min=a[0][1];
			for(int i = 1;i<=N;i++){
				int cnt=a[i-1][0]-a[i][0];
				countS[min]+=i*cnt;
				min=Math.min(min, a[i][1]);
			}
			for(int i=0;i<N;i++)System.out.println(countS[i]);
		}
	}
}
