        long[] merge(long[] t1,long[] t2){
            if(t1==null) return t2;
            if(t2==null)return t1;
            int i=0;
            int j=0;
            int k=0;
            long tt[]=new long[t1.length+t2.length];
            while(i<t1.length&&j<t2.length){
                if(t1[i]<t2[j]){
                    tt[k++]=t1[i++];
                }
                else{
                    tt[k++]=t2[j++];
                }
            }
            while(i<t1.length){
