            int mid=(left+right)/2;
            init(2*i,left,mid);
            init(2*i+1,mid+1,right);
            tr[i]=merge(tr[2*i],tr[2*i+1]);
            int lnt=tr[i].length;
            pref[i]=new long[lnt];
            pref[i][lnt-1]=tr[i][lnt-1];
            for(int j=lnt-2;j>=0;j--)
                pref[i][j]=pref[i][j+1]+tr[i][j];
        }        
