public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.print(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        long[] a = In.nl(n);
        Compress ac = new Compress(a, false);
        int[] b = ac.compress;
        int m = ac.m;
        int[] c = new int[m];
        for (int i = 0; i < n; i++) {
            c[b[i]]++;
        }
        int[] s = new int[m + 1];
        for (int i = m - 1; i >= 0; i--) {
            s[i] = s[i + 1] + c[i];
        }
        IntArrayList ls = new IntArrayList();
        ls.add(0);
        for (int i = 1, max = b[0]; i < n; i++) {
            if (b[i] > max) {
                ls.add(i);
                max = b[i];
            }
        }
        ls.reverse();
        int[] idx = ls.toArray();
        int l = idx.length;
        long[] ans = new long[n];
        for (int i = 0, r = m; i < l; i++) {
            long p = i == l - 1 ? 0 : a[idx[i + 1]];
            if (r < m) {
                ans[idx[i]] += (long) s[r] * (ac.indexToLong(r) - p);
            }
            while (--r >= b[idx[i]]) {
                ans[idx[i]] += (long) c[r] * (ac.indexToLong(r) - p);
            }
        }
        for (int i = 0; i < n; i++) {
            out.append(ans[i]).append('\n');
        }
    }
}



