		    if (max < x) {
		        max = x;
		        map.put(x, new Unit(i, x));
		    } else {
		        map.lastEntry().getValue().add(x);
		    }
		}
		long[] counts = new long[n];
		Unit prev = map.pollLastEntry().getValue();
		while (map.size() > 0) {
		    Unit now = map.pollLastEntry().getValue();
		    counts[prev.idx] = prev.calcCount(now.value);
		    for (Map.Entry<Integer, Integer> entry : prev.map.entrySet()) {
		        if (now.map.containsKey(entry.getKey())) {
		            now.map.put(entry.getKey(), now.map.get(entry.getKey()) + entry.getValue());
		        } else {
		            now.map.put(entry.getKey(), entry.getValue());
		        }
		    }
		    prev = now;
		}
		counts[prev.idx] = prev.calcCount(0);
		StringBuilder sb = new StringBuilder();
		for (long x : counts) {
		    sb.append(x).append("\n");
		}
		System.out.print(sb);
	}

	static class Unit {
	    int idx;
	    int value;
	    TreeMap<Integer, Integer> map = new TreeMap<>();
	    long count = 0;

	    public Unit (int idx, int value) {
	        this.idx = idx;
	        this.value = value;
	        map.put(value, 1);
	    }

	    public void add(int x) {
	        if (map.containsKey(x)) {
	            map.put(x, map.get(x) + 1);
	        } else {
	            map.put(x, 1);
	        }
	    }

	    public long calcCount(int ceil) {
	        while (map.size() > 0) {
	            Map.Entry<Integer, Integer> entry = map.pollLastEntry();
	            int x = entry.getKey();
	            int v = entry.getValue();
	            if (x <= ceil) {
	                map.put(x, v);
	                break;
	            }
	            long size = x - ceil;
	            count += size * v;
	            if (map.containsKey(ceil)) {
	                map.put(ceil, map.get(ceil) + v);
	            } else {
	                map.put(ceil, v);
	            }
	        }
	        return count;
	    }
	}
}

import java.io.*;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {

    static int N;
    static Pile[] P;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();

        P = new Pile[N];
        for (int i = 0; i < N; i++) {
            int size = sc.nextInt();
            P[i] = new Pile(i+1, size);
        }

        PrintWriter pw = new PrintWriter(System.out);
        for (long l : solve()) {
            pw.println(l);
        }
        pw.flush();
    }

    static long[] solve() {
        PriorityQueue<Pile> q = new PriorityQueue<>((p1, p2) -> {
            if( p1.size != p2.size ) {
                return Integer.compare(p2.size, p1.size); // sizeで降順
            } else {
                return Integer.compare(p1.no, p2.no);
            }
        });
        q.addAll( Arrays.asList(P) );

        long[] cnt = new long[N];

        Pile first = q.poll();
        int no = first.no;
        int size = first.size;
        int piles = 1;
        while( !q.isEmpty() ) {
            Pile p = q.peek();
            if( p.size == size ) {
                piles++;
                q.poll();

            } else {
                int diff = size - p.size;
                cnt[no-1] += diff * piles;
                if( p.no < no ) {
                    no = p.no;
                }
                size -= diff;
                piles++;
                q.poll();
            }
        }
        cnt[no-1] += size * piles;
        return cnt;
    }

    static class Pile {
        int no, size;

        public Pile(int no, int size) {
            this.no = no;
            this.size = size;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

