		int sum = 0;
		Integer[] arr = map.keySet().toArray(new Integer[0]);
		for (int i = arr.length - 1; i > 0; i--) {
			Obj o = map.get(arr[i]);
			sum += o.size;
			ans[o.i] += (arr[i] - arr[i - 1]) * sum;
		}
