import java.io.*;
import java.util.*;

public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		Map<Integer, Integer> tmc = new TreeMap<>();
		Map<Integer, Integer> tml = new TreeMap<>();
		for (int i = 0; i < n; i++) {
			int a = sc.nextInt();

			if (!tmc.containsKey(a)) {
				tmc.put(a, 0);
				tml.put(a, i);
			}
			tmc.put(a, tmc.get(a) + 1);
			if (i < tml.get(a)) {
				tml.put(a, i);
			}
		}

		tmc.put(0, 0);
		tml.put(0, 0);
		List<Integer> as = new ArrayList<>(tmc.keySet());
		int[] ans = new int[n];
		for (int i = as.size() - 1; i > 0; i--) {
			int key = as.get(i);
			int keyc = tmc.get(key);
			int keyl = tml.get(key);
			int nkey = as.get(i - 1);
			int nkeyc = tmc.get(nkey);
			int nkeyl = tml.get(nkey);

			ans[keyl] += (key - nkey) * keyc;

			tmc.put(nkey, nkeyc + keyc);
			if (keyl < nkeyl) {
				tml.put(nkey, keyl);
			}
		}

		for (int e : ans) {
			pr.println(e);
		}
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	private static class Printer extends PrintWriter {
		Printer(PrintStream out) {
			super(out);
		}
	}
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	public void run() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		long[][] a = new long[n][2];

		for (int i = 0; i < n; ++i) {
			a[i][0] = sc.nextLong();
			a[i][1] = i;
		}
		// 値の降順にソート
		Arrays.sort(a, new Comparator<long[]>() {
			@Override
			public int compare(long[] o1, long[] o2) {
				if (o1[0] != o2[0]) {
					return -Long.compare(o1[0], o2[0]);
				} else {
					return Long.compare(o1[1], o2[1]);
				}
			}
		});
		long[] cnt = new long[n];
		int s = 0, t = 0;
		while (true) {
			if (s == n)
				break;
			while (t != n && a[s][1] <= a[t][1]) {
				++t;
			}
			cnt[(int) a[s][1]] += (a[s][0] - (t == n ? 0 : a[t][0])) * s;
			// [s:t-1]の範囲だけ考えれば良い
			for (int i = t - 1; i >= s; --i) {
				cnt[(int) a[s][1]] += (a[i][0] - (t == n ? 0 : a[t][0]));
			}
			s = t;
		}
		for(int i=0;i<cnt.length;++i){
			System.out.println(cnt[i]);
		}
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

