class Scanner implements Closeable {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int cur;
    private int num;

    Scanner(InputStream stream) {
        this.stream = stream;
    }

    int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = nextInt();
        return a;
    }

    int nextInt() {
        return (int) nextLong();
    }

    long nextLong() {
        int c = read();
        while (isdel(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long l = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            l *= 10;
            l += c - '0';
            c = read();
        } while (!isdel(c));
        return l * sgn;
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }

    String next() {
        int c = read();
        while (isdel(c))
            c = read();
        StringBuilder s = new StringBuilder();
        do {
            s.appendCodePoint(c);
            c = read();
        } while (!isdel(c));
        return s.toString();
    }

    private int read() {
        if (num == -1)
            throw new InputMismatchException();
        if (cur >= num) {
            cur = 0;
            try {
                num = stream.read(buf);
            } catch (Exception e) {
                throw new InputMismatchException();
            }
            if (num <= 0)
                return -1;
        }
        return buf[cur++];
    }

    private boolean isdel(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    @Override
    public void close() {
        try {
            stream.close();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

import java.util.*;

class Main {
	static int N;
	static int[] a;
	static long[][] is;
	static long[] freq;
	static long[] cum;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		a = new int[N];
		is = new long[2][N];
		freq = new long[N + 1];
		cum = new long[N];
		Arrays.fill(is[0], -1);
		Arrays.fill(is[1], -1);
		Arrays.fill(freq, -1);
		for (int i = 0; i < N; ++i) {
			a[i] = sc.nextInt();
		}

		int p = 0;
		for (int i = 0; i < N; ++i) {
			if (i == 0 || is[0][p - 1] < a[i]) {
				is[0][p] = a[i];
				is[1][p] = i + 1;
				++p;
			}
		}
		is[0] = Arrays.copyOf(is[0], p);
		is[1] = Arrays.copyOf(is[1], p);
		Arrays.sort(a);
		for (int i = 0; i < N; ++i) {
			cum[i] = (i > 0 ? cum[i - 1] : 0) + a[i];
		}
		for (int i = p - 1; i >= 1; --i) {
			int t = binarySearch(a, is[0][i]);
			int s = binarySearch(a, is[0][i - 1]);
			freq[is[1][i]] = cum[t - 1] - cum[s] - (t - s - 1) * is[0][i - 1] + (N - t) * (is[0][i] - is[0][i - 1]);
		}
		int t = binarySearch(a, is[0][0]);
		freq[is[1][0]] = (t > 0 ? cum[t - 1] : 0) + (N - t) * is[0][0];

		for (int i = 1; i <= N; ++i) {
			System.out.println(Math.max(freq[i], 0));
		}
	}

	// 同じ数字が続いているときは一番後ろを返す。
	static int binarySearch(int[] a, int key) {
		int s = -1;
		int t = a.length;
		while (t - s > 1) {
			int m = (s + t) / 2;
			if (a[m] > key) {
				t = m;
			} else {
				s = m;
			}
		}
		if (a[s] != key)
			s *= -1;
		return s;
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

