/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = in.nextIntArray(n);

            Pair[] pairs = new Pair[n];
            List<Integer> list = new ArrayList<>();
            int max = 0;
            for (int i = 0; i < n; i++) {
                if (max < a[i]) {
                    list.add(i);
                    max = a[i];
                }
                pairs[i] = new Pair(i, a[i]);
            }
            Arrays.sort(pairs);

            long[] ans = new long[n];
            int idx = 0;
            long sum = 0;
            max = 0;
            for (int i = 0; i < n; i++) {
                if (pairs[i].x == list.get(idx)) {
                    idx++;
                    ans[pairs[i].x] = sum + (long) (n - i) * (pairs[i].y - max);
                    max = pairs[i].y;
                    sum = 0;
                } else {
                    sum += a[pairs[i].x] - max;
                }
            }

            for (int i = 0; i < n; i++) {
                out.println(ans[i]);
            }
        }

        public class Pair implements Comparable<Pair> {
            int x;
            int y;

            Pair(int x, int y) {
                this.x = x;
                this.y = y;
            }

            public int compareTo(Pair p) {
                return y - p.y;
            }

        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public int[] nextIntArray(int n) {
            int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextInt();
            }
            return res;
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    Scanner   sc   = new Scanner(System.in);

    void run() {
        int n = sc.nextInt();
        Pair[] p = new Pair[n + 1];
        for (int i = 0; i < n; i++) p[i] = new Pair(i + 1, sc.nextLong());
        p[n] = new Pair(0, 0);
        Arrays.sort(p);
        long[] res = new long[n + 1];
        long cnt = 0;
        int idmin = n + 1;
        for (int i = 0; i < n; i++) {
            Pair nowP = p[i];
            idmin = Math.min(idmin, nowP.id);
            cnt++;
            while (nowP.cnt == p[i + 1].cnt) {
                i++;
                cnt++;
            }
            res[idmin] += cnt * (nowP.cnt - p[i + 1].cnt);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i < n + 1; i++) sb.append(res[i]+"\n");
        System.out.print(sb);
    }

    class Pair implements Comparable<Pair> {

        int  id;
        long cnt;

        public Pair(int id, long cnt) {
            super();
            this.id = id;
            this.cnt = cnt;
        }

        @Override
        public int compareTo(Pair arg0) {
            if (this.cnt == arg0.cnt) {
                return this.id - arg0.id;
            }
            return -Long.compare(this.cnt, arg0.cnt);
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

