    static class Data{
        int idx;
        int value;
    }

    public static class Solver extends  SolverAbstract{

        int N;
        int[] A;
        @Override
        public void readInput() throws IOException {
            N = scanner.nextInt(); //10^5
            A = scanner.loadIntArray(N); // 10^9
        }

        @Override
        protected String solve() throws IOException {
            PriorityQueue<Data> queue = new PriorityQueue<>((o1,o2)->o2.value - o1.value);
            for (int i = 0; i < N; i++) {
                Data data = new Data();
                data.idx = i+1;
                data.value = A[i];
                queue.add(data);
            }
            long MAX  = Long.MAX_VALUE / 2;
            long curVal = MAX;
            int minIdx = Integer.MAX_VALUE / 2;
            long[] res = new long[N];
            int cnt = 0;
            while(!queue.isEmpty()){
                Data next = queue.remove();
                curVal = next.value;
                minIdx = next.idx;
                cnt++;
                while(!queue.isEmpty() && queue.peek().value == curVal){
                    next = queue.remove();
                    minIdx = Math.min(minIdx, next.idx);
                    cnt++;
                }
                long nextVal = 0;
                if (!queue.isEmpty()){
                    nextVal = queue.peek().value;
                }
                res[minIdx-1] = (curVal - nextVal) * cnt;
            }
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < N; i++) {
                sb.append(res[i]).append("\n");
            }
            return sb.toString();
        }
    }

