		Scanner io = new Scanner(System.in);
		int N = io.nextInt();
		int[] ans = new int[N];
		PriorityQueue<Deck> que = new PriorityQueue<>();
		for(int i=1;i<=N;i++){
			que.add(new Deck(i,io.nextInt()));
		}
		que.add(new Deck(0,0));
/*		for (int i = 0; i < N; i++) {
			System.out.println(que.peek().NO+" "+que.poll().num);
		}
*/
		Deck nowDeck;
		int nowNO;
		int nowNum;
		for(int i=1;i<=N;i++){
			nowDeck = que.poll();
			nowNO = nowDeck.NO;
			nowNum = nowDeck.num;
			if(nowNum==0) break;
			while(nowNum-que.peek().num==0){
				nowDeck = que.poll();
				i++;
