        }
        void subtract(Pair p){
            f-=p.f;
            s-=p.s;
        }
    }
    static class BIT{
        HashMap<Integer, Pair> t;
        int n;
        BIT(int n){
            this.n=n+100;
            t=new HashMap<>();
        }
        void add(int i,Pair v){
            for(;i<n;i+=i&-i){
                Pair np=new Pair(0,0);
                Pair x=t.putIfAbsent(i,np);
                if(x==null)
                    x=np;
                x.add(v);
            }
        }
        Pair sum(int i){
            Pair sum=new Pair(0,0);
            for(;i>0;i-=i&-i){
                Pair xu=t.get(i);
                if(xu!=null)
                    sum.add(xu);
            }
            return sum;
        }
        Pair sum(int l, int r){
            Pair p=sum(r);
            p.subtract(sum(l-1));
            return p;
        }

    }
    static void solve() throws IOException {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n=in.nextInt();
        int a[]=in.nextIntArrayOneBased(n);
        int pm[]=new int[n+1];
        pm[1]=0;
        for(int i=1;i<=n;i++){
            if(a[i]>a[pm[i-1]])
                pm[i]=i;
            else
                pm[i]=pm[i-1];
        }
        long count=0;
        int lst=n;
        int vp=pm[n];
        long ans[]=new long[n+1];
        BIT b1=new BIT(1000000000);
        do{
            while (lst>=vp){
               b1.add(a[lst],new Pair(1,a[lst]));
               lst--;
            }
            Pair pv=b1.sum(a[pm[vp-1]],1000000001);
            long vpz=pv.s-pv.f*a[pm[vp-1]]-count;
            ans[vp]+=vpz;
            count+=vpz;
            vp=pm[vp-1];



        }while (vp>0);
        for(int i=1;i<=n;i++)
            out.println(ans[i]);

        out.close();

    }
