        for (int i = 0; i < n; i++) {
            map.compute(a[i], (key, value) -> value == null ? 1 : value + 1);
        }
        int count = 0;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            entry.setValue(entry.getValue() + count);
            count += entry.getValue() - count;
        }
        long s = 0;
