import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;
import java.util.SortedMap;
import java.util.TreeMap;


public class Main {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int N = sc.nextInt();
    long[] a = sc.nextLongList(N);

    SortedMap<Long, long[]> map = new TreeMap<>((o1, o2) -> Long.compare(o2, o1));
    for (int i = 0; i < N; i ++) {
      if (!map.containsKey(a[i])) {
        map.put(a[i], new long[]{Long.MAX_VALUE, 0, 0});
      }

      long[] d = map.get(a[i]);
      d[0] = Math.min(i, d[0]);
      d[1] ++;
      d[2] = a[i];
    }

    long[] ret = new long[N];
    long[][] table = map.values().toArray(new long[0][]);

    for (int i = 0; i < table.length - 1; i ++) {
      long d = table[i][2] - table[i + 1][2];
      ret[(int)table[i][0]] = table[i][1] * d;
      table[i + 1][1] += table[i][1];
    }

    ret[0] += table[table.length - 1][1] * table[table.length - 1][2];

    StringBuilder sb = new StringBuilder();
    for (long v : ret) {
      sb.append(v);
      sb.append("\n");
    }
    System.out.println(sb);
  }

}


class FastScanner {
	public static String debug = null;

	private final InputStream in = System.in;
	private int ptr = 0;
	private int buflen = 0;
	private byte[] buffer = new byte[1024];
	private boolean eos = false;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				if (debug != null) {
					buflen = debug.length();
					buffer = debug.getBytes();
					debug = "";
					eos = true;
				} else {
					buflen = in.read(buffer);
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen < 0) {
				eos = true;
				return false;
			} else if (buflen == 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private void skipUnprintable() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
	}

	public boolean isEOS() {
		return this.eos;
	}

	public boolean hasNext() {
		skipUnprintable();
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		return (int) nextLong();
	}

	public long[] nextLongList(int n) {
		return nextLongTable(1, n)[0];
	}

	public int[] nextIntList(int n) {
		return nextIntTable(1, n)[0];
	}

	public long[][] nextLongTable(int n, int m) {
		long[][] ret = new long[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextLong();
			}
		}
		return ret;
	}

	public int[][] nextIntTable(int n, int m) {
		int[][] ret = new int[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextInt();
			}
		}
		return ret;
	}
}

import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.InputMismatchException;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            solve(in);
        }
    }

    private static void solve(Scanner in) {
        int N = in.nextInt();
        Map<Integer, Yama> map = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int a = in.nextInt();
            Yama yama = new Yama(a, i);
            map.put(a, yama.merge(map.get(a)));
        }
        List<Yama> list = new ArrayList<>(map.values());
        Collections.sort(list);

        long[] freq = new long[N];
        for (int i = 0; i < list.size(); i++) {
            Yama y = list.get(i);
            if (i + 1 < list.size()) {
                Yama z = list.get(i + 1);
                freq[y.mini] += y.count * (y.a - z.a);
                z.merge(y);
            } else {
                freq[y.mini] += y.count * y.a;
            }
        }

        StringBuilder ans = new StringBuilder();
        for (long f : freq) {
            ans.append(f).append('\n');
        }
        System.out.println(ans);
    }
}

class Yama implements Comparable<Yama> {
    int a, mini, count;

    Yama(int a, int i) {
        this.a = a;
        mini = i;
        count = 1;
    }

    Yama merge(Yama o) {
        if (o != null) {
            mini = Math.min(mini, o.mini);
            count += o.count;
        }
        return this;
    }

    @Override
    public int compareTo(Yama o) {
        return o.a - a;
    }

    @Override
    public String toString() {
        return String.format("(a=%d,mini=%d,count=%d)", a, mini, count);
    }
}

class Scanner implements Closeable {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int cur;
    private int num;

    Scanner(InputStream stream) {
        this.stream = stream;
    }

    int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = nextInt();
        return a;
    }

    int nextInt() {
        return (int) nextLong();
    }

    long nextLong() {
        int c = read();
        while (isdel(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long l = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            l *= 10;
            l += c - '0';
            c = read();
        } while (!isdel(c));
        return l * sgn;
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }

    String next() {
        int c = read();
        while (isdel(c))
            c = read();
        StringBuilder s = new StringBuilder();
        do {
            s.appendCodePoint(c);
            c = read();
        } while (!isdel(c));
        return s.toString();
    }

    private int read() {
        if (num == -1)
            throw new InputMismatchException();
        if (cur >= num) {
            cur = 0;
            try {
                num = stream.read(buf);
            } catch (Exception e) {
                throw new InputMismatchException();
            }
            if (num <= 0)
                return -1;
        }
        return buf[cur++];
    }

    private boolean isdel(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    @Override
    public void close() {
        try {
            stream.close();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            //while(true)
            solve(in);
        }
    }

    private static void solve(Scanner in) {
        int N = in.nextInt();
        int[] a = new int[N];
        long SUM = 0;
        for (int i = 0; i < N; i++) {
            a[i] = in.nextInt();
            SUM += a[i];
        }
        StringBuilder s = new StringBuilder();

        while (SUM > 0) {
            int max = 0;
            int mini = 0;
            int maxi = 0;
            for (int i = 0; i < N; i++) {
                if (max < a[i]) {
                    max = a[i];
                    mini = i;
                    maxi = i;
                } else if (max == a[i]) {
                    maxi = i;
                }
            }
            s.append(mini + 1);
            a[maxi]--;
            SUM--;
        }

        StringBuilder ans = new StringBuilder();
        for (int i = 1; i < N + 1; i++) {
            int cnt = 0, idx = -1;
            do {
                idx = s.indexOf(String.valueOf(i), idx + 1);
                if (idx > -1) {
                    cnt++;
                }
            } while (idx > -1 && idx < s.length());
            ans.append(cnt).append("\n");
        }
        System.out.println(ans);
    }
}

