class Deck implements Comparable<Deck>{
	int NO;
	int num;
	public Deck(int NO, int num){
		this.NO = NO;
		this.num = num;
	}
	@Override
	public int compareTo(Deck o) {
		return (o.num-num==0)? o.NO-NO
							  :o.num-num;
	}

