public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.print(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        long[] a = In.nl(n);
        Compress ac = new Compress(a, false);
        int[] acmp = ac.compress;
        int m = ac.m;
        int[] c = new int[m];
        for (int i = 0; i < n; i++) {
            c[acmp[i]]++;
        }
        int[] s = new int[m + 1];
        for (int i = m - 1; i >= 0; i--) {
            s[i] = s[i + 1] + c[i];
        }
        IntArrayList ls = new IntArrayList();
        ls.add(0);
        for (int i = 1, max = acmp[0]; i < n; i++) {
            if (acmp[i] > max) {
                ls.add(i);
                max = acmp[i];
            }
        }
        ls.reverse();
        int[] idx = ls.toArray();
        int l = idx.length;
        long[] ans = new long[n];
        for (int i = 0, r = m; i < l - 1; i++) {
            long p = a[idx[i + 1]];
            if (r < m) {
                ans[idx[i]] += (long) s[r] * (ac.indexToLong(r) - p);
            }
            while (--r >= acmp[idx[i + 1]] + 1) {
                ans[idx[i]] += (long) c[r] * (ac.indexToLong(r) - p);
            }
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += a[i];
        }
        for (int i = 0; i < n; i++) {
            ans[idx[l - 1]] -= ans[i];
        }
        ans[idx[l - 1]] += sum;
        for (int i = 0; i < n; i++) {
            out.append(ans[i]).append('\n');
        }
    }
}



