    static void Solve()
    {
        var N = sc.ReadInt();
        var A = sc.ReadIntArray(N);
        var list = new List<Tuple<int, int>>();
        for (int i = 0; i < N; i++)
        {
            list.Add(Tuple.Create(A[i], i));
        }
        list = list.OrderByDescending(t => t.Item1).ThenBy(t => t.Item2).ToList();

        list.Add(Tuple.Create(0, -1));
        var ans = new long[N];
        var now = list[0].Item1;
        var index = list[0].Item2;
        var count = 1L;
        for (int i = 1; i < N + 1; i++)
        {
            if (now == list[i].Item1)
            {
                count++;
                continue;
            }
            var d = now - list[i].Item1;
            ans[index] += d * count;

            now = list[i].Item1;
            index = Math.Min(list[i].Item2, index);
            count++;
        }
        for (int i = 0; i < N; i++)
        {
            Console.WriteLine(ans[i]);
        }
    }
