public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		var a = GetLongs(N);

		var list = new List<(long, long)>();
		list.Add((-1, 0));
		for(long i = 0; i < N; i++)
			list.Add((i, a[i]));

		var grps = list.GroupBy(x => x.Item2).ToList();
		grps.Sort((x, y) => y.Key.CompareTo(x.Key));

		var ans = new long[N];
		long cnt = 0;
		for(int i = 0; i < grps.Count - 1; i++)
		{
			long idx = grps[i].Min(x => x.Item1);
			cnt += grps[i].Count();
			ans[idx] += cnt * (grps[i].Key - grps[i + 1].Key);
		}
		WriteLine(string.Join("\n", ans));
	}
}

