    static void Main()
    {
        int n = sc.Int;
        var a = sc.LongArr;
        var cp = a.copy();
        var indlis = new List<long>();
        var lis = new List<long>();
        long max = 0;
        for (int i = 0; i < n; i++)
        {
            if (max < a[i])
            {
                max = a[i];
                indlis.Add(i);
                lis.Add(a[i]);
            }
        }
        Array.Sort(cp);
        var sum = new long[n + 1];
        for (int i = 0; i < n; i++)
        {
            sum[i + 1] = sum[i] + cp[i];
        }
        var ans = new long[n];
        for (int i = 0; i < lis.Count; i++)
        {
            if (i == 0 && i == lis.Count - 1)
            {
                ans[indlis[i]] = sum[n];
                continue;
            }
            if (i == lis.Count - 1)
            {
                int aa = Search.LowerBound(cp, lis[i]);
                ans[indlis[i]] = sum[n] - sum[aa] - (n - aa) * lis[i - 1];
                continue;
            }
            if (i == 0)
            {
                int aa = Search.LowerBound(cp, lis[i]);
                int bb = Search.LowerBound(cp, lis[i + 1]);
                ans[indlis[i]] = sum[n] - sum[aa] - (sum[n] - sum[bb] - (n - bb) * lis[i]);
                continue;
            }
            int l = Search.LowerBound(cp, lis[i]);
            int r = Search.LowerBound(cp, lis[i + 1]);
            ans[indlis[i]] = sum[n] - sum[l] - (n - l) * lis[i - 1] - (sum[n] - sum[r] - (n - r) * lis[i]);
        }
        foreach (var item in ans)
