        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            int n = sc.nextInt();
            long[] ls = sc.nextLong(n);
            long[] ans = new long[n];
            Dictionary<long, List<int>> dic = new Dictionary<long, List<int>>(); //val,no
            HashSet<long> set = new HashSet<long>();    //no

            for (int i = 0; i < n; i++)
            {
                set.Add(ls[i]);
                if(dic.ContainsKey(ls[i]) == false)
                {
                    dic.Add(ls[i], new List<int>());
                }
                dic[ls[i]].Add(i);
            }
            long[] valls = set.ToArray();
            Array.Sort(valls);
            long cnt = 0;
            for (int i = valls.Length - 1; i >= 0; i--)
            {
                long val = valls[i];
                int no = dic[val][0];
                if(no==0)
                {
                    for (int j = 0; j < n; j++)
                    {
                        ans[0] -= ans[j];
                        ans[0] += ls[j];
                    }
                    break;
                }
                else
                {
                    long nextval = valls[i - 1];
                    cnt += dic[val].Count;
                    ans[no] += cnt * (val - nextval);
                }
            }

            for (int i = 0; i < n; i++)
            {
                pr.WriteLine(ans[i]);
            }
        }
    }
