                    {
                        list1.Add(A[i]);
                        list2.Add(i);
                        max = A[i];
                    }
                }
                long[] ans = new long[list1.Count];
                int[] count = new int[list1.Count];
                for(int i = 0; i < N; ++i)
                {
                    var a = A[i];
                    var idx = Bound.Lowerbound(list1, a);
                    if (list1[idx] > a)
                    {
                        ans[idx] += a - (idx > 0 ? list1[idx - 1] : 0);                        if (idx > 0)
                        {
                            count[idx - 1]++;
                        }
                    }
                    else
                    {
                        count[idx]++;
                    }
                }
                int cum = 0;
                for (int i = list1.Count - 1; i >= 0; --i)
                {
                    cum += count[i];
                    ans[i] += cum * (list1[i] - (i > 0 ? list1[i - 1] : 0));
                }
                var dict = new Dictionary<int, int>();
                for(int i = 0; i < list1.Count; ++i)
                {
                    dict.Add(list2[i], i);
                }
                var sb = new System.Text.StringBuilder();
                for(int i = 0; i < N; ++i)
