public class Kyopuro{

    int n;
    int[] a;
    long[] ans;
    List<int> list;
    Dictionary<int, int[]> dict;

    public void AtCoder(){

        n = int.Parse(Console.ReadLine());
        a = new int[n];
        string[] input = Console.ReadLine().Split(' ');
        for(int i=0; i<n; i++){
            a[i] = int.Parse(input[i]);
        }

        dict = new Dictionary<int, int[]>();
        list = new List<int>();
        for(int i=0; i<n; i++){
            if(dict.ContainsKey(a[i])){
                dict[a[i]][1]++;
            } else {
                dict.Add(a[i], new int[]{i, 1});
                list.Add(a[i]);
            }
        }
        list.Add(0);
        list.Sort((x, y) => y - x);
        int e = n;
        long cum = 0;
        long tmp = 0;

        ans = new long[n];
        for(int i=0; i<list.Count - 1; i++){
            e = Math.Min(dict[list[i]][0], e);
            cum += dict[list[i]][1];
            tmp = cum;
            tmp *= list[i] - list[i+1];
            ans[e] += tmp;
        }

        for(int i=0; i<n; i++) Console.WriteLine(ans[i]);
    }

