public class Program
{
    private int N;
    private int[] A;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();

        var highest = new List<int>();
        int h = 0;

        for (int i = 0; i < N; i++)
        {
            if (h < A[i])
            {
                highest.Add(i);
                h = A[i];
            }
        }

        var tmpA = A.ToArray();
        Array.Sort(tmpA, (a, b) => a.CompareTo(b));

        // iより大きいやつがc[i]個
        var c = new Dictionary<int,int>();
        for (int i = 0; i < N; i++)
        {
            c[tmpA[i]] = N - i - 1;
        }

        c[0] = N;


        // iより大きいやつの和 sum[i]
        var sum = new Dictionary<int, long>();
        long s = 0;

        foreach (int i in A)
        {
            s += i;
        }

        sum[0] = s;
        for (int i = 0; i < N; i++)
        {
            s -= tmpA[i];
            sum[tmpA[i]] = s;
        }

        long[]ans = new long[N];
        long tmp = 0;
        for (int i = highest.Count - 2; i >= 0; i--)
        {
            int hi = A[highest[i]];
            long ss = sum[hi];
            long t = ss - c[hi] * hi; 
            ans[highest[i + 1]] = t-tmp;
            tmp = t;
        }

        ans[0] = sum[0] - tmp;
        Console.WriteLine(String.Join("\n",ans));
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

