        var tuples = Enumerable.Range(0, N).Select(i => Tuple.Create(A[i], i)).OrderByDescending(tuple => tuple.Item1).ToArray();
        int min = int.MaxValue;
        for (int i = 0; i < N; ++i)
        {
            min = Math.Min(tuples[i].Item2, min);
            int a = tuples[i].Item1;
            int b = (i + 1 < N) ? tuples[i + 1].Item1 : 0;
            ans[min] += Math.BigMul(a - b, i + 1);
        }
        return ans;
    }

