    {
        var num = Input.num;
        var ps = new Pi[num+1];ps[num] = new Pi(0, -1);
        for (var i = 0; i < num; i++)
            ps[i] = new Pi(Input.Next<int>(), i);
        Array.Sort(ps, (a, b) => b.v1 - a.v1);
        var idx = ps[0].v2;
        var res = new long[num];
        for(var i = 1L; i <= num; i++)
        {
            res[idx] += i * (ps[i-1].v1 - ps[i].v1);
            chmin(ref idx, ps[i].v2);
        }

        Console.WriteLine(string.Join("\n", res));
    }
}

