		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var a = cin.ReadLongArray(n);

			var ans = new long[n];

			var l = new List<Pair<long, int>>();
			for (int i = 0; i < n; i++)
			{
				l.Add(new Pair<long, int>(a[i], i));
			}
			l.Add(new Pair<long, int>(0, -1));
			l.Sort();

			int index = 0;
			long now = l[index].First;
			while (index < n)
			{
				int next = index;
				while (next <= n && now <= l[next].First)
				{
					next++;
				}
				ans[l[index].Second] += (l[index].First - l[next].First) * (index + 1);
				if(l[index].Second == 0)
				{
					var t = index;
					while (index < n)
					{
						ans[l[t].Second] += l[index].First;
						index++;
					}
					ans[l[t].Second]--;
					break;
				}
				index = next;
				if (index <= n) now = l[index].First;
			}

			foreach (var e in ans)
			{
				Console.WriteLine(e);
			}
		}

