	public class Pair<T, U> : IComparable, IComparable<Pair<T, U>>, IEquatable<Pair<T, U>> where T : IComparable<T>, IEquatable<T> where U : IComparable<U>, IEquatable<U>
	{
		public T First { get; set; }
		public U Second { get; set; }

		public Pair(T first, U second)
		{
			First = first;
			Second = second;
		}

		public int CompareTo(object obj)
		{
			Pair<T, U> castedObj = (Pair<T, U>)obj;
			int x = First.CompareTo(castedObj.First);
			if (x != 0) return x * (-1);
			else return Second.CompareTo(castedObj.Second);
		}

		public int CompareTo(Pair<T, U> x)
		{
			int t = First.CompareTo(x.First);
			if (t != 0) return t * (-1);
			else return Second.CompareTo(x.Second);
		}

		public static bool operator ==(Pair<T, U> x, Pair<T, U> y) => x.CompareTo(y) == 0;

		public static bool operator !=(Pair<T, U> x, Pair<T, U> y) => x.CompareTo(y) != 0;

		public static bool operator <(Pair<T, U> x, Pair<T, U> y) => x.CompareTo(y) == 1;

		public static bool operator >(Pair<T, U> x, Pair<T, U> y) => x.CompareTo(y) == -1;

		public static bool operator <=(Pair<T, U> x, Pair<T, U> y) => x.CompareTo(y) > 0;

		public static bool operator >=(Pair<T, U> x, Pair<T, U> y) => x.CompareTo(y) < 0;

		public override string ToString()
		{
			return $"{First}, {Second}";
		}

		public bool Equals(Pair<T, U> x) => First.Equals(x.First) && Second.Equals(x.Second);

		public override bool Equals(object obj)
		{
			return obj is Pair<T, U> pair &&
				   EqualityComparer<T>.Default.Equals(First, pair.First) &&
				   EqualityComparer<U>.Default.Equals(Second, pair.Second);
		}

		public override int GetHashCode()
		{
			unchecked
			{
				var hashCode = 405212230;
				hashCode = hashCode * -1521134295 + EqualityComparer<T>.Default.GetHashCode(First);
				hashCode = hashCode * -1521134295 + EqualityComparer<U>.Default.GetHashCode(Second);
				return hashCode;
			}
		}
	}


	static class Extention
	{
		public static string Join<T>(this IEnumerable<T> x, string separator = "") => string.Join(separator, x);

		public static int UpperBound<T>(this IList<T> list, T value) => list.BinarySearch(value, true, 0, list.Count, Comparer<T>.Default);
		public static int LowerBound<T>(this IList<T> list, T value) => list.BinarySearch(value, false, 0, list.Count, Comparer<T>.Default);
		public static int BinarySearch<T>(this IList<T> list, T value, bool isUpperBound, int index, int length, Comparer<T> comparer)
		{
			var ng = index - 1;
			var ok = index + length;
			while (ok - ng > 1)
			{
				var mid = ng + (ok - ng) / 2;
				var res = comparer.Compare(list[mid], value);
				if (res < 0 || (isUpperBound && res == 0)) ng = mid;
				else ok = mid;
			}
			return ok;
		}
	}

