        var sortedIndex = a.Select((x, y) => new Tuple<int, int>(x, y)).OrderByDescending(x => x.Item1).Select(x => x.Item2).ToArray();
        long[] res = new long[n];

        int last = a.Max();
        int minLastIndex = n + 1;

        long duplicateCount = 0;

        for (int i = 0; i < a.Length; i++)
        {
            var curentIndex = sortedIndex[i];

            if (last != a[curentIndex])
            {
                res[minLastIndex] += (last - a[curentIndex]) * duplicateCount;
                minLastIndex = n + 1;
            }

            duplicateCount++;
            minLastIndex = Min(minLastIndex, curentIndex);
            last = a[curentIndex];
        }
        Console.WriteLine(string.Join("\n", res));
    }
}

