type Stones []*Pair
type Counter []int

func Get() (int, Stones) {
  r := bufio.NewReaderSize(os.Stdin, AI)

  sn, _, _ := r.ReadLine()
  n, _ := strconv.Atoi(string(sn))

  ss := make([]*Pair, n)
  for i := 1; i <= n; i++ {
    c, _ := r.ReadString(' ')
    ai, _ := strconv.Atoi(c[:len(c)-1])
    ss[i-1] = &Pair { i, ai }
  }

  return n-1, ss
}

func (c *Counter)Post() {
  for _, i := range (*c)[1:] {
    fmt.Println(i)
  }
}

func (ss *Stones)Sort() {
  sort.Slice(*ss, func(a,b int) bool {
    return (*ss)[a].Count > (*ss)[b].Count
  })
}

func (ss *Stones)Show() {
  for _, s := range *ss {
    fmt.Printf("[%v] %v\n", s.Index, s.Count)
  }
}

func (c *Counter)Show() {
  for _, n := range *c {
    fmt.Printf("%v ", n)
  }
  fmt.Println()
}

func (ss *Stones)Solve(size int) Counter {
  counter := make(Counter, size+2)
  i := 0
  for i <= size {

    maxmin := i
    maxmax := i
    maxthen := i

    for ii := i; ii <= size; ii++ {
      if (*ss)[maxmax].Count > (*ss)[ii].Count && (*ss)[ii].Count > 0 {
        maxthen = ii
        break
      } else if (*ss)[maxmax].Count < (*ss)[ii].Count {
        maxmin = ii
        maxmax = ii
      } else {
        if (*ss)[maxmin].Index > (*ss)[ii].Index {
          maxmin = ii
        }
        if (*ss)[maxmax].Index < (*ss)[ii].Index {
          maxmax = ii
        }
      }
    }

    //fmt.Println(maxmin,maxmax,maxthen)
    //counter.Show()
    //ss.Show()

    if (*ss)[maxmin].Count == 1 {
      counter[(*ss)[maxmin].Index] += size + 1
      return counter
    } else {
      diff := (*ss)[maxmax].Count - (*ss)[maxthen].Count
      for ii := 0; ii < maxthen; ii++ {
        if (*ss)[ii].Count > 0 {
          (*ss)[ii].Count -= diff
        }
      }

      counter[(*ss)[maxmin].Index] += diff * maxthen
    }

    i = maxmax
  }

  return counter
}

