	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)
	solve(scanner, writer)
	for i := 0; i < cnt; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
	writer.Flush()
}
func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	ans := make([]int64, n)
	dec := newDecomposition(n)
	pp := &pairs{}
	heap.Init(pp)
	var s int64
	for i := 0; i < n; i++ {
		a := getNextInt(scanner)
		dec.maximize(i, a)
		heap.Push(pp, newPair(i, a))
		s += int64(a)
	}
	for pp.Len() > 0 {
		p := heap.Pop(pp).(pair)
		if p[1] == 0 {
			continue
		}
		m := 0
		if p[0] > 0 {
			m = dec.max(0, p[0])
		}
		if m == 0 {
			ans[p[0]] += s
			break
		}
		s -= int64(p[1] - m)
		ans[p[0]] += int64(p[1] - m)
		p[1] = m
		dec.maximize(p[0], p[1])
		if p[1] > 0 {
			heap.Push(pp, p)
		}
		cur := p[0]
		for p[0]+1 < n && dec.max(p[0]+1, n) > m {
			p = heap.Pop(pp).(pair)
			s -= int64(p[1] - m)
			ans[cur] += int64(p[1] - m)
			p[1] = m
			dec.maximize(p[0], p[1])
			if p[1] > 0 {
				heap.Push(pp, p)
			}
		}
	}
	for i := 0; i < n; i++ {
		fmt.Fprintln(writer, ans[i])
	}
}

func newPair(i, a int) pair {
	return pair{
		i,
		a,
	}
}

type pair [2]int
type pairs []pair

func (h pairs) Len() int { return len(h) }
func (h pairs) Less(i, j int) bool {
	if h[i][1] == h[j][1] {
		return h[i][0] < h[j][0]
	}
	return h[i][1] > h[j][1]
}
func (h pairs) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *pairs) Push(x interface{}) {
	*h = append(*h, x.(pair))
}
func (h *pairs) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

type decomposition struct {
	chunk  int
	bucket [][]int
}

func newDecomposition(n int) decomposition {
	bucket := make([][]int, 1)
	bucket[0] = make([]int, n)
	chunk := 8
	for i := 0; n > 1; i++ {
		n = (n-1)/chunk + 1
		bucket = append(bucket, make([]int, n))
	}
	return decomposition{
		chunk:  chunk,
		bucket: bucket,
	}
}
func (dec *decomposition) upleft(l int) int {
	return (l + dec.chunk - 1) / dec.chunk
}
func (dec *decomposition) upright(r int) int {
	return r / dec.chunk
}

func (dec *decomposition) maximize(index int, value int) {
	dec.bucket[0][index] = value
	h := len(dec.bucket)
	for i := 0; i < h-1; i++ {
		p := index / dec.chunk
		r := (p + 1) * dec.chunk
		if r >= len(dec.bucket[i]) {
			r = len(dec.bucket[i])
		}
		dec.bucket[i+1][p] = value
		for j := p * dec.chunk; j < r; j++ {
			if dec.bucket[i+1][p] < dec.bucket[i][j] {
				dec.bucket[i+1][p] = dec.bucket[i][j]
			}
		}
		index /= dec.chunk
	}
}
func (dec *decomposition) max(l, r int) int {
	return dec.maxh(l, r, 0)
}
func (dec *decomposition) maxh(l, r, h int) int {
	m := dec.bucket[h][l]
	ll := dec.upleft(l)
	rr := dec.upright(r)
	for i := l; i < r && i < ll*dec.chunk; i++ {
		if m < dec.bucket[h][i] {
			m = dec.bucket[h][i]
		}
	}
	if ll < rr {
		mm := dec.maxh(ll, rr, h+1)
		if m < mm {
			m = mm
		}
	}
	for i := rr * dec.chunk; i < r && ll <= rr; i++ {
		if m < dec.bucket[h][i] {
			m = dec.bucket[h][i]
		}
	}
	return m
}

