func (ss *Stones)Solve(size int) Counter {
  counter := make(Counter, size+2)
  i := 0
  for i <= size {

    maxmin := i
    maxmax := i
    maxthen := i

    for ii := i; ii <= size; ii++ {
      if (*ss)[maxmax].Count > (*ss)[ii].Count && (*ss)[ii].Count > 0 {
        maxthen = ii
        break
      } else if (*ss)[maxmax].Count < (*ss)[ii].Count {
        maxmin = ii
        maxmax = ii
      } else {
        if (*ss)[maxmin].Index > (*ss)[ii].Index {
          maxmin = ii
        }
        if (*ss)[maxmax].Index < (*ss)[ii].Index {
          maxmax = ii
        }
      }
    }

    //fmt.Println(maxmin,maxmax,maxthen)
    //counter.Show()
    //ss.Show()

    if (*ss)[maxmin].Count == 1 {
      counter[(*ss)[maxmin].Index] += size + 1
      return counter
    } else {
      diff := (*ss)[maxmax].Count - (*ss)[maxthen].Count
      for ii := 0; ii < maxthen; ii++ {
        if (*ss)[ii].Count > 0 {
          (*ss)[ii].Count -= diff
        }
      }

      counter[(*ss)[maxmin].Index] += diff * maxthen
    }

    i = maxmax
  }

  return counter
}

