ulong[] solve()
{
    int N = readInt;
    auto list = readInts.enumerate(cast(size_t)1).array();

    list.sort!"a.value > b.value"();
    Entry[] entries;
    foreach(e; list){
        if(entries.length == 0)
            entries ~= Entry(e.value, e.index, 1);
        else if(entries[$-1].value == e.value){
            entries[$-1].minIdx = min(entries[$-1].minIdx, e.index);
            entries[$-1].cnt += 1;
        }
        else
            entries ~= Entry(e.value, e.index, 1);
    }

    // writeln(entries);

    ulong[] result = new ulong[N];
    auto M = entries.length;
    foreach(i; 0 .. M){
        // writeln(entries);
        // writeln(result);
        // writeln();

        if(i != M-1){
            int diff = entries[i].value - entries[i+1].value;
            auto idx = entries[i].minIdx;
            result[idx-1] += diff * entries[i].cnt;

            entries[i+1].minIdx = min(entries[i+1].minIdx, idx);
            entries[i+1].cnt += entries[i].cnt;
        }else{
            int diff = entries[i].value;
            auto idx = entries[i].minIdx;
            result[idx-1] += diff * entries[i].cnt;
        }
    }


    return result;
}


