fn solve() {
    let n = read::<usize>();
    let mut a = read_vec::<usize>(n);
    let mut memo_max = vec![0; n + 10];
    let mut x = a[0];
    for i in 0..n {
        memo_max[i + 1] = cmp::max(memo_max[i], a[i]);
    }

    let mut heap = BinaryHeap::new();
    let mut cnt = 0;
    let mut ans = vec![0; n];
    //println!("{:?}", memo_max);
    for i in (0..n).rev() {
        if memo_max[i] > a[i] {
            // 使われない
            ans[i] = 0;
            heap.push(Node { val: -(a[i] as i64) });
        } else {
            if memo_max[i + 1] > memo_max[i] {
                ans[i] += (cnt + 1) * (memo_max[i + 1] - memo_max[i]);
                cnt += 1;
            }
            //これよりも右にあるa[i]より大きいもんはmemo_max[i]になる
            while let Some(Node { val }) = heap.pop() {
                let val_plus = -val;
                if val_plus < a[i] as i64 {
                    heap.push(Node { val });
                    break;
                } else {
                    cnt += 1;
                    ans[i] += (val_plus as usize - memo_max[i]);
                }
            }
        }
    }
    for i in &ans {
        println!("{}", i);
    }
}

