struct Scanner {
    stdin: Stdin,
    id: usize,
    buf: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            stdin: io::stdin(),
            id: 0,
            buf: Vec::new(),
        }
    }
    fn next_line(&mut self) -> Option<String> {
        let mut res = String::new();
        match self.stdin.read_line(&mut res) {
            Ok(0) => return None,
            Ok(_) => Some(res),
            Err(why) => panic!("error in read_line: {}", why.description()),
        }
    }
    fn next<T: FromStr>(&mut self) -> Option<T> {
        while self.buf.len() == 0 {
            self.buf = match self.next_line() {
                Some(r) => {
                    self.id = 0;
                    r.trim().as_bytes().to_owned()
                }
                None => return None,
            };
        }
        let l = self.id;
        assert!(self.buf[l] != b' ');
        let n = self.buf.len();
        let mut r = l;
        while r < n && self.buf[r] != b' ' {
            r += 1;
        }
        let res = match str::from_utf8(&self.buf[l..r]).ok().unwrap().parse::<T>() {
            Ok(s) => Some(s),
            Err(_) => {
                panic!("parse error, {:?}",
                       String::from_utf8(self.buf[l..r].to_owned()))
            }
        };
        while r < n && self.buf[r] == b' ' {
            r += 1;
        }
        if r == n {
            self.buf.clear();
        } else {
            self.id = r;
        }
        res
    }
    fn ne<T: FromStr>(&mut self) -> T {
        self.next::<T>().unwrap()
    }
}

use std::io::{BufRead, Write, stdin, stdout};
use std::cmp::min;
use std::collections::btree_map::BTreeMap;
use std::collections::btree_map::Entry::*;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    s.clear();
    input.read_line(&mut s).unwrap();
    let a: Vec<u64> = s.split_whitespace().map(|x| x.parse().unwrap()).collect();
    let n = a.len();
    let mut map: BTreeMap<u64, (u64, u64)> = BTreeMap::new(); // number => (minimum index, amount)
    for (i, val) in a.into_iter().enumerate() {
        match map.entry(val) {
            Vacant(e) => {
                e.insert((i as u64, 1));
            }
            Occupied(mut e) => {
                let &(index, amount) = e.get();
                e.insert((min(i as u64, index), amount + 1));
            }
        }
    }
    let mut result = vec![0u64;n];
    while map.len() >= 2 {
        let max_n = *map.keys().next_back().unwrap();
        let max = map.remove(&max_n).unwrap();
        let next = map.iter_mut().next_back().unwrap();
        (next.1).0 = min((next.1).0, max.0);
        (next.1).1 += max.1;
        result[max.0 as usize] += (max_n - next.0) * max.1;
    }
    {
        let max_n = *map.keys().next_back().unwrap();
        let max = map.remove(&max_n).unwrap();
        result[max.0 as usize] += max_n * max.1;
    }
    for i in result {
        writeln!(output, "{}", i).unwrap();
    }
}

