pub trait Monoid {
    type T: Clone;
    fn id() -> Self::T;
    fn op(a: &Self::T, b: &Self::T) -> Self::T;
}
pub struct SegTree<M: Monoid> {
    n: usize,
    data: Vec<M::T>,
}
impl<M: Monoid> SegTree<M> {
    pub fn new(n_: usize) -> SegTree<M> {
        let mut n = 1 as usize;
        while (n < n_) {
            n *= 2;
        }
        SegTree {
            n: n,
            data: vec![M::id().clone(); (2 * n)],
        }
    }
    #[macro_use]
    pub fn update(&mut self, index: usize, v: M::T) {
        let mut k = index + self.n - 1;
        self.data[k] = v;
        while (k > 0) {
            k = (k - 1) / 2;
            self.data[k] = M::op(&self.data[2 * k + 1], &self.data[2 * k + 2]);
        }
    }
    pub fn query(&mut self, l: usize, r: usize) -> M::T {
        let mut l = l + self.n - 1;
        let mut r = r + self.n - 1;
        if (l == r) {
            return M::op(&M::id().clone(), &self.data[l]);
        }
        let mut ret = M::id().clone();
        while (l < r) {
            if (l % 2 == 0) {
                ret = M::op(&ret, &self.data[l]);
            }
            if (r % 2 == 0) {
                ret = M::op(&ret, &self.data[r - 1]);
            }
            l = l / 2;
            r = (r - 1) / 2;
        }
        return ret;
    }
}
struct SUM;
impl Monoid for SUM {
    type T = u64;
    fn id() -> Self::T {
        0
    }
    fn op(a: &Self::T, b: &Self::T) -> Self::T {
        *a + *b
    }
}

