fn solve() {
    let n = get!(usize);
    let mut a = get!([usize]);
    a.insert(0,0);
    let mut b = a.iter().cloned().enumerate().collect::<Vec<_>>();

    b.sort_by_key(|e| -(e.1 as isize));

    let mut sum_tree = SegmentTree::<usize, IMonoid>::new(n+1);
    let mut count_tree = SegmentTree::<usize, IMonoid>::new(n+1);
    let mut counts = vec![0; n+1];
    for (i,e) in b {
        counts[i] = sum_tree.get(i, n+1) - e*count_tree.get(i,n+1);
        sum_tree.update(i,e);
        count_tree.update(i,1);
    }

    let mut selected = vec![0];
    for i in 1..n+1 {
        let last = selected.iter().rev().next().cloned().unwrap();
        let lv = a[last];
        if lv < a[i] {
            selected.push(i);
        }
    }

    let mut res = vec![0; n+1];
    for (&before, &after) in selected.iter().zip(selected.iter().skip(1)) {
        res[after] = counts[before]-counts[after];
    }
    for i in 1..n+1 {
        println!("{}", res[i]);
    }
}

